const QUESTIONS = [{"num":1,"text":"A company purchased cyber insurance to address items listed on the risk register. Which of the following strategies does this represent?","options":[["A","Accept"],["B","Transfer"],["C","Mitigate"],["D","Avoid"]],"correct":"B","explanation":"N/A"},{"num":2,"text":"Which of the following is the most likely to be used to document risks, responsible parties, and thresholds?","options":[["A","Risk tolerance"],["B","Risk transfer"],["C","Risk register"],["D","Risk analysis"]],"correct":"C","explanation":"N/A"},{"num":4,"text":"A systems administrator notices that the research and development department is not using the company VPN when accessing various company-related services and systems. Which of the following scenarios describes this activity?","options":[["A","Espionage"],["B","Data exfiltration"],["C","Nation-state attack"],["D","Shadow IT"]],"correct":"D","explanation":"N/A"},{"num":5,"text":"Which of the following threat vectors is most commonly utilized by insider threat actors attempting data exfiltration?","options":[["A","Unidentified removable devices"],["B","Default network device credentials"],["C","Spear phishing emails"],["D","Impersonation of business units through typosquatting"]],"correct":"A","explanation":"N/A"},{"num":6,"text":"Which of the following agreement types defines the time frame in which a vendor needs to respond?","options":[["A","SOW"],["B","SLA"],["C","MOA"],["D","MOU"]],"correct":"B","explanation":"N/A"},{"num":7,"text":"Which of the following is a feature of a next-generation SIEM system?","options":[["A","Virus signatures"],["B","Automated response actions"],["C","Security agent deployment"],["D","Vulnerability scanning"]],"correct":"B","explanation":"N/A"},{"num":8,"text":"To improve the security at a data center, a security administrator implements a CCTV system and posts several signs about the possibility of being filmed. Which of the following best describe these types of controls? (Choose two.)","options":[["A","Preventive"],["B","Deterrent"],["C","Corrective"],["D","Directive"],["E","Compensating"],["F","Detective"]],"correct":"BF","explanation":"N/A"},{"num":9,"text":"Which of the following examples would be best mitigated by input sanitization?","options":[["A","<script>alert(\"Warning!\");</script>"],["B","nmap - 10.11.1.130"],["C","Email message: \"Click this link to get your free gift card.\""],["D","Browser message: \"Your connection is not private.\""]],"correct":"A","explanation":"N/A"},{"num":10,"text":"An attacker posing as the Chief Executive Officer calls an employee and instructs the employee to buy gift cards. Which of the following techniques is the attacker using?","options":[["A","Smishing"],["B","Disinformation"],["C","Impersonating"],["D","Whaling"]],"correct":"C","explanation":"N/A"},{"num":11,"text":"After conducting a vulnerability scan, a systems administrator notices that one of the identified vulnerabilities is not present on the systems that were scanned. Which of the following describes this example?","options":[["A","False positive"],["B","False negative"],["C","True positive"],["D","True negative"]],"correct":"A","explanation":"N/A"},{"num":12,"text":"A recent penetration test identified that an attacker could flood the MAC address table of network switches. Which of the following would best mitigate this type of attack?","options":[["A","Load balancer"],["B","Port security"],["C","IPS"],["D","NGFW"]],"correct":"B","explanation":"N/A"},{"num":13,"text":"A user would like to install software and features that are not available with a smartphone's default software. Which of the following would allow the user to install unauthorized software and enable new features?","options":[["A","SQLi"],["B","Cross-site scripting"],["C","Jailbreaking"],["D","Side loading"]],"correct":"C","explanation":"N/A"},{"num":14,"text":"Which of the following phases of an incident response involves generating reports?","options":[["A","Recovery"],["B","Preparation"],["C","Lessons learned"],["D","Containment"]],"correct":"C","explanation":"N/A"},{"num":15,"text":"Which of the following methods would most likely be used to identify legacy systems?","options":[["A","Bug bounty program"],["B","Vulnerability scan"],["C","Package monitoring"],["D","Dynamic analysis"]],"correct":"B","explanation":"N/A"},{"num":16,"text":"Employees located off-site must have access to company resources in order to complete their assigned tasks. These employees utilize a solution that allows remote access without interception concerns. Which of the following best describes this solution?","options":[["A","Proxy server"],["B","NGFW"],["C","VPN"],["D","Security zone"]],"correct":"C","explanation":"N/A"},{"num":17,"text":"A company allows customers to upload PDF documents to its public e-commerce website. Which of the following would a security analyst most likely recommend?","options":[["A","Utilizing attack signatures in an IDS"],["B","Enabling malware detection through a UTM"],["C","Limiting the affected servers with a load balancer"],["D","Blocking command injections via a WAF"]],"correct":"B","explanation":"N/A"},{"num":18,"text":"A security analyst developed a script to automate a trivial and repeatable task. Which of the following best describes the benefits of ensuring other team members understand how the script works?","options":[["A","To reduce implementation cost"],["B","To identify complexity"],["C","To remediate technical debt"],["D","To prevent a single point of failure"]],"correct":"D","explanation":"N/A"},{"num":19,"text":"A company is decommissioning its physical servers and replacing them with an architecture that will reduce the number of individual operating systems. Which of the following strategies should the company use to achieve this security requirement?","options":[["A","Microservices"],["B","Containerization"],["C","Virtualization"],["D","Infrastructure as code"]],"correct":"B","explanation":"N/A"},{"num":20,"text":"An administrator needs to perform server hardening before deployment. Which of the following steps should the administrator take? (Choose two.)","options":[["A","Disable default accounts."],["B","Add the server to the asset inventory."],["C","Remove unnecessary services."],["D","Document default passwords."],["E","Send server logs to the SIEM."],["F","Join the server to the corporate domain."]],"correct":"AC","explanation":"N/A"},{"num":21,"text":"A Chief Information Security Officer would like to conduct frequent, detailed reviews of systems and procedures to track compliance objectives. Which of the following will be the best method to achieve this objective?","options":[["A","Third-party attestation"],["B","Penetration testing"],["C","Internal auditing"],["D","Vulnerability scans"]],"correct":"C","explanation":"N/A"},{"num":22,"text":"Which of the following security concepts is accomplished with the installation of a RADIUS server?","options":[["A","CIA"],["B","AAA"],["C","ACL"],["D","PEM"]],"correct":"B","explanation":"N/A"},{"num":23,"text":"After creating a contract for IT contractors, the human resources department changed several clauses. The contract has gone through three revisions. Which of the following processes should the human resources department follow to track revisions?","options":[["A","Version validation"],["B","Version changes"],["C","Version updates"],["D","Version control"]],"correct":"D","explanation":"N/A"},{"num":24,"text":"The executive management team is mandating the company develop a disaster recovery plan. The cost must be kept to a minimum, and the money to fund additional internet connections is not available. Which of the following would be the best option?","options":[["A","Hot site"],["B","Cold site"],["C","Failover site"],["D","Warm site"]],"correct":"B","explanation":"N/A"},{"num":25,"text":"An administrator at a small business notices an increase in support calls from employees who receive a blocked page message after trying to navigate to a spoofed website. Which of the following should the administrator do?","options":[["A","Deploy multifactor authentication."],["B","Decrease the level of the web filter settings."],["C","Implement security awareness training."],["D","Update the acceptable use policy."]],"correct":"C","explanation":"N/A"},{"num":26,"text":"Which of the following teams is best suited to determine whether a company has systems that can be exploited by a potential, identified vulnerability?","options":[["A","Purple team"],["B","Blue team"],["C","Red team"],["D","White team"]],"correct":"C","explanation":"N/A"},{"num":27,"text":"A company is reviewing options to enforce user logins after several account takeovers. The following conditions must be met as part of the solution: Allow employees to work remotely or from assigned offices around the world. Provide a seamless login experience. Limit the amount of equipment required. Which of the following best meets these conditions?","options":[["A","Trusted devices"],["B","Geotagging"],["C","Smart cards"],["D","Time-based logins"]],"correct":"A","explanation":"N/A"},{"num":28,"text":"Which of the following methods can be used to detect attackers who have successfully infiltrated a network? (Choose two.)","options":[["A","Tokenization"],["B","CI/CD"],["C","Honeypots"],["D","Threat modeling"],["E","DNS sinkhole"],["F","Data obfuscation"]],"correct":"CE","explanation":"N/A"},{"num":29,"text":"A company wants to ensure that the software it develops will not be tampered with after the final version is completed. Which of the following should the company most likely use?","options":[["A","Hashing"],["B","Encryption"],["C","Baselines"],["D","Tokenization"]],"correct":"A","explanation":"N/A"},{"num":30,"text":"An organization completed a project to deploy SSO across all business applications last year. Recently, the finance department selected a new cloud-based accounting software vendor. Which of the following should most likely be configured during the new software deployment?","options":[["A","RADIUS"],["B","SAML"],["C","EAP"],["D","OpenID"]],"correct":"B","explanation":"N/A"},{"num":31,"text":"A user, who is waiting for a flight at an airport, logs in to the airline website using the public Wi-Fi, ignores a security warning and purchases an upgraded seat. When the flight lands, the user finds unauthorized credit card charges. Which of the following attacks most likely occurred?","options":[["A","Replay attack"],["B","Memory leak"],["C","Buffer overflow attack"],["D","On-path attack"]],"correct":"D","explanation":"N/A"},{"num":32,"text":"A network engineer deployed a redundant switch stack to increase system availability. However, the budget can only cover the cost of one ISP connection. Which of the following best describes the potential risk factor?","options":[["A","The equipment MTBF is unknown."],["B","The ISP has no SLA."],["C","An RPO has not been determined."],["D","There is a single point of failure."]],"correct":"D","explanation":"N/A"},{"num":33,"text":"A network team segmented a critical, end-of-life server to a VLAN that can only be reached by specific devices but cannot be reached by the perimeter network. Which of the following best describe the controls the team implemented? (Choose two.)","options":[["A","Managerial"],["B","Physical"],["C","Corrective"],["D","Detective"],["E","Compensating"],["F","Technical"],["G","Deterrent"]],"correct":"EF","explanation":"N/A"},{"num":34,"text":"A threat actor was able to use a username and password to log in to a stolen company mobile device. Which of the following provides the best solution to increase mobile data security on all employees' company mobile devices?","options":[["A","Application management"],["B","Full disk encryption"],["C","Remote wipe"],["D","Containerization"]],"correct":"B","explanation":"N/A"},{"num":35,"text":"Which of the following best describes the risk present after controls and mitigating factors have been applied?","options":[["A","Residual"],["B","Avoided"],["C","Inherent"],["D","Operational"]],"correct":"A","explanation":"N/A"},{"num":36,"text":"A software development team asked a security administrator to recommend techniques that should be used to reduce the chances of the software being reverse engineered. Which of the following should the security administrator recommend?","options":[["A","Digitally signing the software"],["B","Performing code obfuscation"],["C","Limiting the use of third-party libraries"],["D","Using compile flags"]],"correct":"B","explanation":"N/A"},{"num":37,"text":"Which of the following is a possible factor for MFA?","options":[["A","Something you exhibit"],["B","Something you have"],["C","Somewhere you are"],["D","Someone you know"]],"correct":"B","explanation":"N/A"},{"num":38,"text":"Easy-to-guess passwords led to an account compromise. The current password policy requires at least 12 alphanumeric characters, one uppercase character, one lowercase character, a password history of two passwords, a minimum password age of one day, and a maximum password age of 90 days. Which of the following would reduce the risk of this incident from happening again? (Choose two.)","options":[["A","Increasing the minimum password length to 14 characters."],["B","Upgrading the password hashing algorithm from MD5 to SHA-512."],["C","Increasing the maximum password age to 120 days."],["D","Reducing the minimum password length to ten characters."],["E","Reducing the minimum password age to zero days."],["F","Including a requirement for at least one special character."]],"correct":"AF","explanation":"N/A"},{"num":39,"text":"A user downloaded software from an online forum. After the user installed the software, the security team observed external network traffic connecting to the user's computer on an uncommon port. Which of the following is the most likely explanation of this unauthorized connection?","options":[["A","The software had a hidden keylogger."],["B","The software was ransomware."],["C","The user's computer had a fileless virus."],["D","The software contained a backdoor."]],"correct":"D","explanation":"N/A"},{"num":40,"text":"A utility company is designing a new platform that will host all the virtual machines used by business applications. The requirements include: A starting baseline of 50% memory utilization Storage scalability Single circuit failure resilience Which of the following best meets all of these requirements?","options":[["A","Connecting dual PDUs to redundant power supplies"],["B","Transitioning the platform to an IaaS provider"],["C","Configuring network load balancing for multiple paths"],["D","Deploying multiple large NAS devices for each host"]],"correct":"B","explanation":"N/A"},{"num":41,"text":"Which of the following best describes a use case for a DNS sinkhole?","options":[["A","Attackers can see a DNS sinkhole as a highly valuable resource to identify a company's domain structure."],["B","A DNS sinkhole can be used to draw employees away from known-good websites to malicious ones owned by the attacker."],["C","A DNS sinkhole can be used to capture traffic to known-malicious domains used by attackers."],["D","A DNS sinkhole can be set up to attract potential attackers away from a company's network resources."]],"correct":"C","explanation":"N/A"},{"num":42,"text":"An incident analyst finds several image files on a hard disk. The image files may contain geolocation coordinates. Which of the following best describes the type of information the analyst is trying to extract from the image files?","options":[["A","Log data"],["B","Metadata"],["C","Encrypted data"],["D","Sensitive data"]],"correct":"B","explanation":"N/A"},{"num":43,"text":"Which of the following most likely describes why a security engineer would configure all outbound emails to use S/MIME digital signatures?","options":[["A","To meet compliance standards"],["B","To increase delivery rates"],["C","To block phishing attacks"],["D","To ensure non-repudiation"]],"correct":"D","explanation":"N/A"},{"num":44,"text":"During a recent company safety stand-down, the cyber-awareness team gave a presentation on the importance of cyber hygiene. One topic the team covered was best practices for printing centers. Which of the following describes an attack method that relates to printing centers?","options":[["A","Whaling"],["B","Credential harvesting"],["C","Prepending"],["D","Dumpster diving"]],"correct":"D","explanation":"N/A"},{"num":45,"text":"Which of the following considerations is the most important regarding cryptography used in an IoT device?","options":[["A","Resource constraints"],["B","Available bandwidth"],["C","The use of block ciphers"],["D","The compatibility of the TLS version"]],"correct":"A","explanation":"N/A"},{"num":46,"text":"A coffee shop owner wants to restrict internet access to only paying customers by prompting them for a receipt number. Which of the following is the best method to use given this requirement?","options":[["A","WPA3"],["B","Captive portal"],["C","PSK"],["D","IEEE 802.1X"]],"correct":"B","explanation":"N/A"},{"num":47,"text":"While performing digital forensics, which of the following is considered the most volatile and should have the contents collected first?","options":[["A","Hard drive"],["B","RAM"],["C","SSD"],["D","Temporary files"]],"correct":"B","explanation":"N/A"},{"num":48,"text":"A hosting provider needs to prove that its security controls have been in place over the last six months and have sufficiently protected customer data. Which of the following would provide the best proof that the hosting provider has met the requirements?","options":[["A","NIST CSF"],["B","SOC 2 Type 2 report"],["C","CIS Top 20 compliance reports"],["D","Vulnerability report"]],"correct":"B","explanation":"N/A"},{"num":49,"text":"A city municipality lost its primary data center when a tornado hit the facility. Which of the following should the city staff use immediately after the disaster to handle essential public services?","options":[["A","BCP"],["B","Communication plan"],["C","DRP"],["D","IRP"]],"correct":"C","explanation":"N/A"},{"num":50,"text":"Which of the following is considered a preventive control?","options":[["A","Configuration auditing"],["B","Log correlation"],["C","Incident alerts"],["D","Segregation of duties"]],"correct":"D","explanation":"N/A"},{"num":51,"text":"A systems administrator notices that a testing system is down. While investigating, the systems administrator finds that the servers are online and accessible from any device on the server network. The administrator reviews the following information from the monitoring system: Which of the following is the most likely cause of the outage?","options":[["A","Denial of service"],["B","ARP poisoning"],["C","Jamming"],["D","Kerberoasting"]],"correct":"A","explanation":"N/A","image":"q51.jpg"},{"num":52,"text":"A security team has been alerted to a flood of incoming emails that have various subject lines and are addressed to multiple email inboxes. Each email contains a URL shortener link that is redirecting to a dead domain. Which of the following is the best step for the security team to take?","options":[["A","Create a blocklist for all subject lines."],["B","Send the dead domain to a DNS sinkhole."],["C","Quarantine all emails received and notify all employees."],["D","Block the URL shortener domain in the web proxy."]],"correct":"D","explanation":"N/A"},{"num":53,"text":"A security administrator is working to secure company data on corporate laptops in case the laptops are stolen. Which of the following solutions should the administrator consider?","options":[["A","Disk encryption"],["B","Data loss prevention"],["C","Operating system hardening"],["D","Boot security"]],"correct":"A","explanation":"N/A"},{"num":54,"text":"A company needs to keep the fewest records possible, meet compliance needs, and ensure destruction of records that are no longer needed. Which of the following best describes the policy that meets these requirements?","options":[["A","Security policy"],["B","Classification policy"],["C","Retention policy"],["D","Access control policy"]],"correct":"C","explanation":"N/A"},{"num":55,"text":"Which of the following is a common source of unintentional corporate credential leakage in cloud environments?","options":[["A","Code repositories"],["B","Dark web"],["C","Threat feeds"],["D","State actors"],["E","Vulnerability databases"]],"correct":"A","explanation":"N/A"},{"num":56,"text":"Which of the following is the best reason an organization should enforce a data classification policy to help protect its most sensitive information?","options":[["A","End users will be required to consider the classification of data that can be used in documents."],["B","The policy will result in the creation of access levels for each level of classification."],["C","The organization will have the ability to create security requirements based on classification levels."],["D","Security analysts will be able to see the classification of data within a document before opening it."]],"correct":"C","explanation":"N/A"},{"num":57,"text":"An analyst is performing a vulnerability scan against the web servers exposed to the internet without a system account. Which of the following is most likely being performed?","options":[["A","Non-credentialed scan"],["B","Packet capture"],["C","Privilege escalation"],["D","System enumeration"],["E","Passive scan"]],"correct":"A","explanation":"N/A"},{"num":58,"text":"A security administrator is hardening corporate systems and applying appropriate mitigations by consulting a real-world knowledge base for adversary behavior. Which of the following would be best for the administrator to reference?","options":[["A","MITRE ATT&CK"],["B","CSIRT"],["C","CVSS"],["D","SOAR"]],"correct":"A","explanation":"N/A"},{"num":59,"text":"An architect has a request to increase the speed of data transfer using JSON requests externally. Currently, the organization uses SFTP to transfer data files. Which of the following will most likely meet the requirements?","options":[["A","A website-hosted solution"],["B","Cloud shared storage"],["C","A secure email solution"],["D","Microservices using API"]],"correct":"D","explanation":"N/A"},{"num":60,"text":"Which of the following addresses individual rights such as the right to be informed, the right of access, and the right to be forgotten?","options":[["A","GDPR"],["B","PCI DSS"],["C","NIST"],["D","ISO"]],"correct":"A","explanation":"N/A"},{"num":61,"text":"An administrator is installing an LDAP browser tool in order to view objects in the corporate LDAP directory. Secure connections to the LDAP server are required. When the browser connects to the server, certificate errors are being displayed, and then the connection is terminated. Which of the following is the most likely solution?","options":[["A","The administrator should allow SAN certificates in the browser configuration."],["B","The administrator needs to install the server certificate into the local truststore."],["C","The administrator should request that the secure LDAP port be opened to the server."],["D","The administrator needs to increase the TLS version on the organization's RA."]],"correct":"B","explanation":"N/A"},{"num":62,"text":"Which of the following is the most important security concern when using legacy systems to provide production service?","options":[["A","Instability"],["B","Lack of vendor support"],["C","Loss of availability"],["D","Use of insecure protocols"]],"correct":"B","explanation":"N/A"},{"num":63,"text":"A security investigation revealed that malicious software was installed on a server using a server administrator's credentials. During the investigation, the server administrator explained that Telnet was regularly used to log in. Which of the following most likely occurred?","options":[["A","A spraying attack was used to determine which credentials to use."],["B","A packet capture tool was used to steal the password."],["C","A remote-access Trojan was used to install the malware."],["D","A dictionary attack was used to log in as the server administrator."]],"correct":"B","explanation":"N/A"},{"num":64,"text":"A user is requesting Telnet access to manage a remote development web server. Insecure protocols are not allowed for use within any environment. Which of the following should be configured to allow remote access to this server?","options":[["A","HTTPS"],["B","SNMPv3"],["C","SSH"],["D","RDP"],["E","SMTP"]],"correct":"C","explanation":"N/A"},{"num":65,"text":"A security administrator is working to find a cost-effective solution to implement certificates for a large number of domains and subdomains owned by the company. Which of the following types of certificates should the administrator implement?","options":[["A","Wildcard"],["B","Client certificate"],["C","Self-signed"],["D","Code signing"]],"correct":"A","explanation":"N/A"},{"num":66,"text":"An auditor discovered multiple insecure ports on some servers. Other servers were found to have legacy protocols enabled. Which of the following tools did the auditor use to discover these issues?","options":[["A","Nessus"],["B","curl"],["C","Wireshark"],["D","netcat"]],"correct":"A","explanation":"N/A"},{"num":67,"text":"A security analyst received a tip that sensitive proprietary information was leaked to the public. The analyst is reviewing the PCAP and notices traffic between an internal server and an external host that includes the following: ... 12:47:22.327233 PPPoE [ses 0x8122] IP (tos 0x0, ttl 64, id 0, offset 0, flags [DF], proto IPv6 (41), length 331) 10.5.1.1 > 52.165.16.154: IP6 (hlim E3, next-header TCP (6) paylcad length: 271) 2001:67c:2158:a019::ace.53104 > 2001:0:5ef5:79fd:380c:dddd:a601:24fa.13788: Flags [P.], cksum 0xd7ee (correct), seq 97:348, ack 102, win 16444, length 251 ... Which of the following was most likely used to exfiltrate the data?","options":[["A","Encapsulation"],["B","MAC address spoofing"],["C","Steganography"],["D","Broken encryption"],["E","Sniffing via on-path position"]],"correct":"A","explanation":"N/A"},{"num":68,"text":"A company wants to reduce the time and expense associated with code deployment. Which of the following technologies should the company utilize?","options":[["A","Serverless architecture"],["B","Thin clients"],["C","Private cloud"],["D","Virtual machines"]],"correct":"A","explanation":"N/A"},{"num":69,"text":"A security administrator is performing an audit on a stand-alone UNIX server, and the following message is immediately displayed: (Error 13): /etc/shadow: Permission denied. Which of the following best describes the type of tool that is being used?","options":[["A","Pass-the-hash monitor"],["B","File integrity monitor"],["C","Forensic analysis"],["D","Password cracker"]],"correct":"D","explanation":"N/A"},{"num":70,"text":"A security administrator needs to create firewall rules for the following protocols: RTP, SIP, H.323. and SRTP. Which of the following does this rule set support?","options":[["A","RTOS"],["B","VoIP"],["C","SoC"],["D","HVAC"]],"correct":"B","explanation":"N/A"},{"num":71,"text":"Which of the following best describes a social engineering attack that uses a targeted electronic messaging campaign aimed at a Chief Executive Officer?","options":[["A","Whaling"],["B","Spear phishing"],["C","Impersonation"],["D","Identity fraud"]],"correct":"A","explanation":"N/A"},{"num":72,"text":"During a penetration test, a flaw in the internal PKI was exploited to gain domain administrator rights using specially crafted certificates. Which of the following remediation tasks should be completed as part of the cleanup phase?","options":[["A","Updating the CRL"],["B","Patching the CA"],["C","Changing passwords"],["D","Implementing SOAR"]],"correct":"B","explanation":"N/A"},{"num":73,"text":"A company wants to implement MFA. Which of the following enables the additional factor while using a smart card?","options":[["A","PIN"],["B","Hardware token"],["C","User ID"],["D","SMS"]],"correct":"A","explanation":"N/A"},{"num":74,"text":"A company hired an external consultant to assist with required system upgrades to a critical business application. A systems administrator needs to secure the consultant's access without sharing passwords to critical systems. Which of the following solutions should most likely be utilized?","options":[["A","TACACS+"],["B","SAML"],["C","An SSO platform"],["D","Role-based access control"],["E","PAM software"]],"correct":"E","explanation":"N/A"},{"num":75,"text":"A newly implemented wireless network is designed so that visitors can connect to the wireless network for business activities. The legal department is concerned that visitors might connect to the network and perform illicit activities. Which of me following should the security team implement to address this concern?","options":[["A","Configure a RADIUS server to manage device authentication."],["B","Use 802.1X on all devices connecting to wireless."],["C","Add a guest captive portal requiring visitors to accept terms and conditions."],["D","Allow for new devices to be connected via WPS."]],"correct":"C","explanation":"N/A"},{"num":76,"text":"Which of the following data roles is responsible for identifying risks and appropriate access to data?","options":[["A","Owner"],["B","Custodian"],["C","Steward"],["D","Controller"]],"correct":"A","explanation":"N/A"},{"num":77,"text":"Which of the following physical controls can be used to both detect and deter? (Choose two.)","options":[["A","Lighting"],["B","Fencing"],["C","Signage"],["D","Sensor"],["E","Bollard"],["F","Lock"]],"correct":"AD","explanation":"N/A"},{"num":78,"text":"A multinational bank hosts several servers in its data center. These servers run a business-critical application used by customers to access their account information. Which of the following should the bank use to ensure accessibility during peak usage times?","options":[["A","Load balancer"],["B","Cloud backups"],["C","Geographic dispersal"],["D","Disk multipathing"]],"correct":"A","explanation":"N/A"},{"num":79,"text":"The author of a software package is concerned about bad actors repackaging and inserting malware into the software. The software download is hosted on a website, and the author exclusively controls the website's contents. Which of the following techniques would best ensure the software's integrity?","options":[["A","Input validation"],["B","Code signing"],["C","Secure cookies"],["D","Fuzzing"]],"correct":"B","explanation":"N/A"},{"num":80,"text":"A third-party vendor is moving a particular application to the end-of-life stage at the end of the current year. Which of the following is the most critical risk if the company chooses to continue running the application?","options":[["A","Lack of security updates"],["B","Lack of new features"],["C","Lack of support"],["D","Lack of source code access"]],"correct":"A","explanation":"N/A"},{"num":81,"text":"A security analyst recently read a report about a flaw in several of the organization's printer models that causes credentials to be sent over the network in cleartext, regardless of the encryption settings. Which of the following would be best to use to validate this finding?","options":[["A","Wireshark"],["B","netcat"],["C","Nessus"],["D","Nmap"]],"correct":"A","explanation":"N/A"},{"num":82,"text":"A development team is launching a new public-facing web product. The Chief Information Security Officer has asked that the product be protected from attackers who use malformed or invalid inputs to destabilize the system. Which of the following practices should the development team implement?","options":[["A","Fuzzing"],["B","Continuous deployment"],["C","Static code analysis"],["D","Manual peer review"]],"correct":"A","explanation":"N/A"},{"num":83,"text":"During an annual review of the system design, an engineer identified a few issues with the currently released design. Which of the following should be performed next according to best practices?","options":[["A","Risk management process"],["B","Product design process"],["C","Design review process"],["D","Change control process"]],"correct":"D","explanation":"N/A"},{"num":84,"text":"Which of the following is best to use when determining the severity of a vulnerability?","options":[["A","CVE"],["B","OSINT"],["C","SOAR"],["D","CVSS"]],"correct":"D","explanation":"N/A"},{"num":85,"text":"An organization experienced a security breach that allowed an attacker to send fraudulent wire transfers from a hardened PC exclusively to the attacker's bank through remote connections. A security analyst is creating a timeline of events and has found a different PC on the network containing malware. Upon reviewing the command history, the analyst finds the following: PS>.\\mimikatz.exe \"sekurlsa::pth /user:localadmin /domain:corp-domain.com / ntlm:B4B9B02E1F29A3CF193EAB28C8D617D3F327 Which of the following best describes how the attacker gained access to the hardened PC?","options":[["A","The attacker created fileless malware that was hosted by the banking platform."],["B","The attacker performed a pass-the-hash attack using a shared support account."],["C","The attacker utilized living-off-the-land binaries to evade endpoint detection and response software."],["D","The attacker socially engineered the accountant into performing bad transfers."]],"correct":"B","explanation":"N/A"},{"num":86,"text":"Which of the following is the best resource to consult for information on the most common application exploitation methods?","options":[["A","OWASP"],["B","STIX"],["C","OVAL"],["D","Threat intelligence feed"],["E","Common Vulnerabilities and Exposures"]],"correct":"A","explanation":"N/A"},{"num":87,"text":"A security analyst is reviewing the logs on an organization's DNS server and notices the following unusual snippet: Which of the following attack techniques was most likely used?","options":[["A","Determining the organization's ISP-assigned address space"],["B","Bypassing the organization's DNS sinkholing"],["C","Footprinting the internal network"],["D","Attempting to achieve initial access to the DNS server"],["E","Exfiltrating data from fshare.int.complia.org"]],"correct":"C","explanation":"N/A","image":"q87.jpg"},{"num":88,"text":"A security analyst at an organization observed several user logins from outside the organization's network. The analyst determined that these logins were not performed by individuals within the organization. Which of the following recommendations would reduce the likelihood of future attacks? (Choose two.)","options":[["A","Disciplinary actions for users"],["B","Conditional access policies"],["C","More regular account audits"],["D","Implementation of additional authentication factors"],["E","Enforcement of content filtering policies"],["F","A review of user account permissions"]],"correct":"BD","explanation":"N/A"},{"num":89,"text":"A security team is addressing a risk associated with the attack surface of the organization's web application over port 443. Currently, no advanced network security capabilities are in place. Which of the following would be best to set up? (Choose two.)","options":[["A","NIDS"],["B","Honeypot"],["C","Certificate revocation list"],["D","HIPS"],["E","WAF"],["F","SIEM"]],"correct":"AE","explanation":"N/A"},{"num":90,"text":"A systems administrator would like to create a point-in-time backup of a virtual machine. Which of the following should the administrator use?","options":[["A","Replication"],["B","Simulation"],["C","Snapshot"],["D","Containerization"]],"correct":"C","explanation":"N/A"},{"num":91,"text":"A security administrator notices numerous unused, non-compliant desktops are connected to the network. Which of the following actions would the administrator most likely recommend to the management team?","options":[["A","Monitoring"],["B","Decommissioning"],["C","Patching"],["D","Isolating"]],"correct":"B","explanation":"N/A"},{"num":92,"text":"Which of the following is a common data removal option for companies that want to wipe sensitive data from hard drives in a repeatable manner but allow the hard drives to be reused?","options":[["A","Sanitization"],["B","Formatting"],["C","Degaussing"],["D","Defragmentation"]],"correct":"A","explanation":"N/A"},{"num":93,"text":"An organization wants to improve the company's security authentication method for remote employees. Given the following requirements: Must work across SaaS and internal network applications Must be device manufacturer agnostic Must have offline capabilities Which of the following would be the most appropriate authentication method?","options":[["A","Username and password"],["B","Biometrics"],["C","SMS verification"],["D","Time-based tokens"]],"correct":"D","explanation":"N/A"},{"num":94,"text":"A security officer is implementing a security awareness program and has placed security-themed posters around the building and assigned online user training. Which of the following will the security officer most likely implement?","options":[["A","Password policy"],["B","Access badges"],["C","Phishing campaign"],["D","Risk assessment"]],"correct":"C","explanation":"N/A"},{"num":95,"text":"A malicious update was distributed to a common software platform and disabled services at many organizations. Which of the following best describes this type of vulnerability?","options":[["A","DDoS attack"],["B","Rogue employee"],["C","Insider threat"],["D","Supply chain"]],"correct":"D","explanation":"N/A"},{"num":96,"text":"A company web server is initiating outbound traffic to a low-reputation, public IP on non-standard pat. The web server is used to present an unauthenticated page to clients who upload images the company. An analyst notices a suspicious process running on the server hat was not created by the company development team. Which of the following is the most likely explanation for his security incident?","options":[["A","A web shell has been deployed to the server through the page."],["B","A vulnerability has been exploited to deploy a worm to the server."],["C","Malicious insiders are using the server to mine cryptocurrency."],["D","Attackers have deployed a rootkit Trojan to the server over an exposed RDP port."]],"correct":"A","explanation":"N/A"},{"num":97,"text":"An organization requests a third-party full-spectrum analysis of its supply chain. Which of the following would the analysis team use to meet this requirement?","options":[["A","Vulnerability scanner"],["B","Penetration test"],["C","SCAP"],["D","Illumination tool"]],"correct":"D","explanation":"N/A"},{"num":98,"text":"A systems administrator deployed a monitoring solution that does not require installation on the endpoints that the solution is monitoring. Which of the following is described in this scenario?","options":[["A","Agentless solution"],["B","Client-based soon"],["C","Open port"],["D","File-based solution"]],"correct":"A","explanation":"N/A"},{"num":99,"text":"A security analyst is reviewing the source code of an application in order to identify misconfigurations and vulnerabilities. Which of the following kinds of analysis best describes this review?","options":[["A","Dynamic"],["B","Static"],["C","Gap"],["D","Impact"]],"correct":"B","explanation":"N/A"},{"num":100,"text":"Which of the following agreement types is used to limit external discussions?","options":[["A","BPA"],["B","NDA"],["C","SLA"],["D","MSA"]],"correct":"B","explanation":"N/A"},{"num":101,"text":"A security analyst is evaluating a SaaS application that the human resources department would like to implement. The analyst requests a SOC 2 report from the SaaS vendor. Which of the following processes is the analyst most likely conducting?","options":[["A","Internal audit"],["B","Penetration testing"],["C","Attestation"],["D","Due diligence"]],"correct":"D","explanation":"N/A"},{"num":102,"text":"Which of the following is used to conceal credit card information in a database log file?","options":[["A","Tokenization"],["B","Masking"],["C","Hashing"],["D","Obfuscation"]],"correct":"B","explanation":"N/A"},{"num":104,"text":"An organization recently started hosting a new service that customers access through a web portal. A security engineer needs to add to the existing security devices a new solution to protect this new service. Which of the following is the engineer most likely to deploy?","options":[["A","Layer 4 firewall"],["B","NGFW"],["C","WAF"],["D","UTM"]],"correct":"C","explanation":"N/A"},{"num":105,"text":"Which of the following topics would most likely be included within an organization's SDLC?","options":[["A","Service-level agreements"],["B","Information security policy"],["C","Penetration testing methodology"],["D","Branch protection requirements"]],"correct":"D","explanation":"N/A"},{"num":106,"text":"Which of the following control types is AUP an example of?","options":[["A","Physical"],["B","Managerial"],["C","Technical"],["D","Operational"]],"correct":"D","explanation":"N/A"},{"num":107,"text":"An organization is adopting cloud services at a rapid pace and now has multiple SaaS applications in use. Each application has a separate log-in, so the security team wants to reduce the number of credentials each employee must maintain. Which of the following is the first step the security team should take?","options":[["A","Enable SAML."],["B","Create OAuth tokens."],["C","Use password vaulting."],["D","Select an IdP."]],"correct":"D","explanation":"N/A"},{"num":108,"text":"A company's online shopping website became unusable shortly after midnight on January 30, 2023. When a security analyst reviewed the database server, the analyst noticed the following code used for backing up data: Which of the following should the analyst do next?","options":[["A","Check for recently terminated DBAs."],["B","Review WAF logs for evidence of command injection."],["C","Scan the database server for malware."],["D","Search the web server for ransomware notes."]],"correct":"B","explanation":"N/A","image":"q108.jpg"},{"num":109,"text":"Which of the following would be the best way to test resiliency in the event of a primary power failure?","options":[["A","Parallel processing"],["B","Tabletop exercise"],["C","Simulation testing"],["D","Production failover"]],"correct":"D","explanation":"N/A"},{"num":110,"text":"Which of the following would be the most appropriate way to protect data in transit?","options":[["A","SHA-256"],["B","SSL3.0"],["C","TLS 1.3"],["D","AES-256"]],"correct":"C","explanation":"N/A"},{"num":111,"text":"Which of the following is a common, passive reconnaissance technique employed by penetration testers in the early phases of an engagement?","options":[["A","Open-source intelligence"],["B","Port scanning"],["C","Pivoting"],["D","Exploit validation"]],"correct":"A","explanation":"N/A"},{"num":112,"text":"Which of the following threat actors is the most likely to seek financial gain through the use of ransomware attacks?","options":[["A","Organized crime"],["B","Insider threat"],["C","Nation-state"],["D","Hacktivists"]],"correct":"A","explanation":"Organized crime groups are primarily motivated by financial gain. Ransomware attacks are a popular tool for these groups because they can encrypt a victim's data and demand a ransom payment (often in cryptocurrency) to restore access. This form of attack can yield a high financial return if victims choose to pay."},{"num":113,"text":"Which of the following would a systems administrator follow when upgrading the firmware of an organization\u2019s router?","options":[["A","Software development life cycle"],["B","Risk tolerance"],["C","Certificate signing request"],["D","Maintenance window"]],"correct":"D","explanation":"A maintenance window is a pre-scheduled period when system or network changes, updates, or repairs are performed. By using a designated maintenance window, a systems administrator can minimize disruption to the organization\u2019s operations, as this window is typically chosen during a time when network usage is lower, reducing the impact on users."},{"num":114,"text":"The security team has been asked to only enable host A (10.2.2.7) and host B (10.3.9.9) to the new isolated network segment (10.9.8.14) that provides access to legacy devices. Access from all other hosts should be blocked. Which of the following entries would need to be added on the firewall?","options":[["A","Permit 10.2.2.0/24 to 10.9.8.14/27 Permit 10.3.9.0/24 to 10.9.8.14/27 Deny 0.0.0.0/0 to 10.9.8.14/27"],["B","Deny 0.0.0.0/0 to 10.9.8.14/27 Permit 10.2.2.0/24 to 10.9.8.14/27 Permit 10.3.9.0/24 to 10.9.8.14/27"],["C","Permit 10.2.2.7/32 to 10.9.8.14/27 Permit 10.3.9.9/32 to 10.9.8.14/27 Deny 0.0.0.0/0 to 10.9.8.14/27"],["D","Permit 10.2.2.7/32 to 10.9.8.14/27 Permit 10.3.9.0/24 to 10.9.8.14/27 Deny 10.9.8.14/27 to 0.0.0.0/0"]],"correct":"C","explanation":"Permit 10.2.2.7/32 to 10.9.8.14/27: This rule allows host A (10.2.2.7) specific access to the isolated network (10.9.8.14/27). Permit 10.3.9.9/32 to 10.9.8.14/27: This rule allows host B (10.3.9.9) specific access to the isolated network (10.9.8.14/27). Deny 0.0.0.0/0 to 10.9.8.14/27: This rule blocks access from all other IPs to the isolated network (10.9.8.14/27).","image":"q114.jpg"},{"num":116,"text":"A systems administrator needs to ensure the secure communication of sensitive data within the organization\u2019s private cloud. Which of the following is the best choice for the administrator to implement?","options":[["A","IPSec"],["B","SHA-1"],["C","RSA"],["D","TGT"]],"correct":"A","explanation":"IPSec (Internet Protocol Security) is a suite of protocols designed to secure IP communications by authenticating and encrypting each IP packet in a communication session. It is widely used for securing data transfer in networks, including private clouds, by providing confidentiality, integrity, and authenticity of data."},{"num":117,"text":"Which of the following should an internal auditor check for first when conducting an audit of the organization\u2019s risk management program?","options":[["A","Policies and procedures"],["B","Asset management"],["C","Vulnerability assessment"],["D","Business impact analysis"]],"correct":"A","explanation":"Policies and procedures form the foundation of an organization's risk management program. They establish the framework and guidelines for managing risks across the organization, including roles, responsibilities, and the approach for identifying, assessing, and mitigating risks. Without well-defined policies and procedures, it would be challenging to assess other areas of risk management effectively, as they are all built upon these foundational documents. Asset management, vulnerability assessment, and business impact analysis are critical components of a risk management program, but they should follow a review of policies and procedures. These documents set the standards and processes that the organization uses to manage assets, assess vulnerabilities, and conduct impact analyses."},{"num":118,"text":"Which of the following activities are associated with vulnerability management? (Choose two.)","options":[["A","Reporting"],["B","Prioritization"],["C","Exploiting"],["D","Correlation"],["E","Containment"],["F","Tabletop exercise"]],"correct":"AB","explanation":"Reporting involves documenting and communicating the findings of vulnerability scans and assessments. This allows stakeholders to be informed about existing vulnerabilities and track remediation efforts. Prioritization is the process of ranking vulnerabilities based on their severity, impact, and exploitability, helping the organization address the most critical vulnerabilities first."},{"num":119,"text":"An administrator wants to perform a risk assessment without using proprietary company information. Which of the following methods should the administrator use to gather information?","options":[["A","Network scanning"],["B","Penetration testing"],["C","Open-source intelligence"],["D","Configuration auditing"]],"correct":"C","explanation":"Open-source intelligence (OSINT) involves collecting information from publicly available sources, such as websites, social media, news articles, and other publicly accessible databases. OSINT allows an administrator to gather valuable information about potential risks without using any proprietary or internal company information."},{"num":120,"text":"A systems administrator is concerned about vulnerabilities within cloud computing instances. Which of the following is most important for the administrator to consider when architecting a cloud computing environment?","options":[["A","SQL injection"],["B","TOC/TOU"],["C","VM escape"],["D","Tokenization"],["E","Password spraying"]],"correct":"C","explanation":"In cloud computing, virtual machines (VMs) share physical resources. VM escape is a critical vulnerability where an attacker could break out of a virtualized environment and access the host system or other VMs running on the same physical hardware. This would pose a significant security risk, as it could allow attackers to compromise the entire cloud infrastructure."},{"num":121,"text":"A database administrator is updating the company\u2019s SQL database, which stores credit card information for pending purchases. Which of the following is the best method to secure the data against a potential breach?","options":[["A","Hashing"],["B","Obfuscation"],["C","Tokenization"],["D","Masking"]],"correct":"C","explanation":"Tokenization replaces sensitive data, like credit card information, with a unique identifier (token) that has no exploitable value outside of a specific context. This approach is widely used to secure payment card information and reduces the risk of exposure in case of a breach, as the actual credit card data is not stored in the database."},{"num":122,"text":"Which of the following is a benefit of vendor diversity?","options":[["A","Patch availability"],["B","Zero-day resiliency"],["C","Secure configuration guide applicability"],["D","Load balancing"]],"correct":"B","explanation":"Vendor diversity can help mitigate the impact of zero-day vulnerabilities. By using multiple vendors for similar services or components, organizations reduce the likelihood that a single vulnerability affecting one vendor's products will compromise the entire system. This diversity creates resilience against attacks exploiting unknown vulnerabilities in any single vendor's software."},{"num":123,"text":"An employee used a company\u2019s billing system to issue fraudulent checks. The administrator is looking for evidence of other occurrences of this activity. Which of the following should the administrator examine?","options":[["A","Application logs"],["B","Vulnerability scanner logs"],["C","IDS/IPS logs"],["D","Firewall logs"]],"correct":"A","explanation":"Application logs will contain records of activities within the billing system, including transactions, actions taken by users, and any anomalies. This is the most direct source of evidence for tracing fraudulent activity within the specific application, such as issuing unauthorized checks."},{"num":124,"text":"An organization is looking to optimize its environment and reduce the number of patches necessary for operating systems. Which of the following will best help to achieve this objective?","options":[["A","Microservices"],["B","Virtualization"],["C","Real-time operating system"],["D","Containers"]],"correct":"D","explanation":"Containers package applications with only the necessary components and dependencies, which reduces the footprint of the operating system components in each instance. This approach minimizes the number of OS patches required, as each container runs only essential services instead of a full OS environment, making it easier to isolate and update application dependencies without affecting the host or requiring frequent OS-level patches."},{"num":125,"text":"Which of the following tasks is typically included in the BIA process?","options":[["A","Estimating the recovery time of systems"],["B","Identifying the communication strategy"],["C","Evaluating the risk management plan"],["D","Establishing the backup and recovery procedures"],["E","Developing the incident response plan"]],"correct":"A","explanation":"In a BIA, estimating the recovery time of systems, also known as the Recovery Time Objective (RTO), is crucial. The BIA process focuses on identifying critical systems, understanding the impact of their unavailability, and determining acceptable downtime. This helps in planning for recovery times, resource allocation, and continuity strategies."},{"num":126,"text":"Which of the following is a risk of conducting a vulnerability assessment?","options":[["A","A disruption of business operations"],["B","Unauthorized access to the system"],["C","Reports of false positives"],["D","Finding security gaps in the system"]],"correct":"A","explanation":"During a vulnerability assessment, scanning or testing can sometimes interfere with normal system operations, potentially leading to slowdowns, unresponsiveness, or even outages. This can disrupt business operations, especially if the assessment is run on production systems without adequate precautions or scheduling during low-impact times."},{"num":127,"text":"Which of the following techniques would attract the attention of a malicious attacker in an insider threat scenario?","options":[["A","Creating a false text file in /docs/salaries"],["B","Setting weak passwords in /etc/shadow"],["C","Scheduling vulnerable jobs in /etc/crontab"],["D","Adding a fake account to /etc/passwd"]],"correct":"A","explanation":"A file with a name like \"salaries\" suggests sensitive information, which would likely draw the attention of an insider threat looking for valuable or confidential data. This technique is often used as part of a honeypot strategy to monitor and detect suspicious activity by insiders attempting unauthorized access."},{"num":128,"text":"An organization maintains intellectual property that it wants to protect. Which of the following concepts would be most beneficial to add to the company\u2019s security awareness training program?","options":[["A","Insider threat detection"],["B","Simulated threats"],["C","Phishing awareness"],["D","Business continuity planning"]],"correct":"A","explanation":"Insider threats pose a significant risk to intellectual property, as insiders often have access to sensitive information and may attempt to misuse it. Training employees to recognize signs of insider threats, along with implementing monitoring and reporting protocols, helps protect intellectual property from theft or unauthorized disclosure by employees or other trusted individuals within the organization."},{"num":129,"text":"An organization plans to expand its operations internationally and needs to keep data at the new location secure. The organization wants to use the most secure architecture model possible. Which of the following models offers the highest level of security?","options":[["A","Cloud-based"],["B","Peer-to-peer"],["C","On-premises"],["D","Hybrid"]],"correct":"C","explanation":"An on-premises architecture provides the highest level of control over data security, as the organization manages its own hardware, software, and network infrastructure directly. This setup enables the organization to implement strict access controls, customize security measures according to regulatory requirements, and avoid some of the risks associated with data transmission and storage in cloud environments, particularly for sensitive or proprietary information."},{"num":130,"text":"Which of the following is the most relevant reason a DPO would develop a data inventory?","options":[["A","To manage data storage requirements better"],["B","To determine the impact in the event of a breach"],["C","To extend the length of time data can be retained"],["D","To automate the reduction of duplicated data"]],"correct":"B","explanation":"A data inventory provides a comprehensive overview of what data the organization holds, where it is stored, and its sensitivity. This information is crucial for assessing the potential impact of a data breach, as it allows the DPO to identify which data would be affected and the associated risks. Additionally, it aids in compliance with data protection regulations by ensuring that sensitive data is adequately managed and protected."},{"num":131,"text":"Which of the following cryptographic solutions protects data at rest?","options":[["A","Digital signatures"],["B","Full disk encryption"],["C","Private key"],["D","Steganography"]],"correct":"B","explanation":"Full disk encryption (FDE) secures data at rest by encrypting the entire storage drive, ensuring that data is protected when the system is powered off or if the drive is accessed without authorization. This approach is commonly used to protect sensitive data stored on devices like laptops, servers, and storage media."},{"num":132,"text":"Which of the following should an organization use to protect its environment from external attacks conducted by an unauthorized hacker?","options":[["A","ACL"],["B","IDS"],["C","HIDS"],["D","NIPS"]],"correct":"D","explanation":"A Network Intrusion Prevention System (NIPS) actively monitors network traffic and can detect and block malicious activities in real-time, helping to prevent external attacks. Unlike IDS, which only detects intrusions, NIPS can take immediate action to stop threats, making it a strong defensive measure against unauthorized external attacks."},{"num":133,"text":"Which of the following would enable a data center to remain operational through a multiday power outage?","options":[["A","Generator"],["B","Uninterruptible power supply"],["C","Replication"],["D","Parallel processing"]],"correct":"A","explanation":"A generator can provide continuous power for extended periods during a power outage, as long as it has sufficient fuel. Unlike an Uninterruptible Power Supply (UPS), which is typically used to bridge short power interruptions, a generator is designed to sustain operations over longer durations, making it ideal for keeping a data center functional during a multiday outage."},{"num":134,"text":"A company installed cameras and added signs to alert visitors that they are being recorded. Which of the following controls did the company implement? (Choose two.)","options":[["A","Directive"],["B","Deterrent"],["C","Preventive"],["D","Detective"],["E","Corrective"],["F","Technical"]],"correct":"BD","explanation":"N/A"},{"num":135,"text":"Which of the following is the best way to securely store an encryption key for a data set in a manner that allows multiple entities to access the key when needed?","options":[["A","Public key infrastructure"],["B","Open public ledger"],["C","Public key encryption"],["D","Key escrow"]],"correct":"D","explanation":"Key escrow involves storing the encryption key with a trusted third party or system that securely retains the key and grants access to authorized entities as needed. This approach ensures that multiple authorized parties can access the key in a controlled and secure manner, making it a reliable solution for shared access requirements."},{"num":136,"text":"For which of the following reasons would a systems administrator leverage a 3DES hash from an installer file that is posted on a vendor\u2019s website?","options":[["A","To test the integrity of the file"],["B","To validate the authenticity of the file"],["C","To activate the license for the file"],["D","To calculate the checksum of the file"]],"correct":"A","explanation":"A hash (such as one generated using 3DES) is used to verify that the file has not been altered or corrupted during download. By comparing the hash of the downloaded file with the one provided by the vendor, the administrator can confirm the file's integrity."},{"num":137,"text":"A company is redesigning its infrastructure and wants to reduce the number of physical servers in use. Which of the following architectures is best suited for this goal?","options":[["A","Isolation"],["B","Segmentation"],["C","Virtualization"],["D","Redundancy"]],"correct":"C","explanation":"Virtualization allows multiple virtual machines (VMs) to run on a single physical server, reducing the need for multiple physical servers. This approach consolidates workloads, optimizes hardware usage, and lowers operational costs by enabling multiple isolated environments on fewer physical devices."},{"num":138,"text":"Which of the following security concepts is being followed when implementing a product that offers protection against DDoS attacks?","options":[["A","Availability"],["B","Non-repudiation"],["C","Integrity"],["D","Confidentiality"]],"correct":"A","explanation":"DDoS (Distributed Denial of Service) attacks aim to overwhelm resources and make services unavailable to legitimate users. By implementing protection against DDoS attacks, the organization is focusing on maintaining the availability of its services, ensuring that they remain accessible even in the face of such attacks."},{"num":139,"text":"A security manager created new documentation to use in response to various types of security incidents. Which of the following is the next step the manager should take?","options":[["A","Set the maximum data retention policy."],["B","Securely store the documents on an air-gapped network."],["C","Review the documents\u2019 data classification policy."],["D","Conduct a tabletop exercise with the team."]],"correct":"D","explanation":"A tabletop exercise allows the team to walk through various incident response scenarios using the new documentation, helping to ensure everyone understands their roles and the procedures. This step verifies the effectiveness of the documentation, identifies any gaps, and provides practical experience for the team, which is essential for effective incident response."},{"num":140,"text":"After failing an audit twice, an organization has been ordered by a government regulatory agency to pay fines. Which of the following causes this action?","options":[["A","Non-compliance"],["B","Contract violations"],["C","Government sanctions"],["D","Rules of engagement"]],"correct":"A","explanation":"Failure to meet regulatory standards or requirements (non-compliance) can result in fines and penalties imposed by a government regulatory agency. When an organization does not comply with mandated regulations or fails audits, it may face financial repercussions to enforce adherence to required standards."},{"num":141,"text":"A company is developing a critical system for the government and storing project information on a fileshare. Which of the following describes how this data will most likely be classified? (Choose two.)","options":[["A","Private"],["B","Confidential"],["C","Public"],["D","Operational"],["E","Urgent"],["F","Restricted"]],"correct":"BF","explanation":"Since the company is developing a critical system for the government, project information would likely be classified as Confidential to prevent unauthorized access and maintain secrecy, and Restricted to limit access strictly to authorized personnel only, given the sensitivity and importance of government-related work."},{"num":142,"text":"Which of the following activities is included in the post-incident review phase?","options":[["A","Determining the root cause of the incident"],["B","Developing steps to mitigate the risks of the incident"],["C","Validating the accuracy of the evidence collected during the investigation"],["D","Reestablishing the compromised system\u2019s configuration and settings"]],"correct":"A","explanation":"During the post-incident review, the team analyzes the incident to understand its root cause. This phase is focused on learning from the incident, identifying vulnerabilities, and implementing improvements to prevent similar future incidents."},{"num":143,"text":"Which of the following attacks exploits a potential vulnerability as a result of using weak cryptographic algorithms?","options":[["A","Password cracking"],["B","On-path"],["C","Digital signing"],["D","Side-channel"]],"correct":"A","explanation":"Weak cryptographic algorithms make it easier for attackers to crack passwords by using techniques such as brute-force or dictionary attacks. When encryption algorithms are weak, they produce predictable patterns or can be processed faster, allowing attackers to break the encryption and recover sensitive information, such as passwords, more easily."},{"num":144,"text":"Which of the following is a preventive physical security control?","options":[["A","Video surveillance system"],["B","Bollards"],["C","Alarm system"],["D","Motion sensors"]],"correct":"B","explanation":"Bollards are physical barriers that prevent unauthorized vehicle access to certain areas, helping to protect a facility by physically blocking entry. Unlike detection-focused controls like video surveillance, alarms, and motion sensors, bollards serve as a proactive, preventive measure by stopping threats before they can reach the facility."},{"num":145,"text":"Which of the following is most likely to be used as a just-in-time reference document within a security operations center?","options":[["A","Change management policy"],["B","Risk profile"],["C","Playbook"],["D","SIEM profile"]],"correct":"C","explanation":"A playbook provides step-by-step procedures for responding to specific types of security incidents, making it an essential just-in-time reference during active incidents. SOC analysts rely on playbooks to quickly access instructions and guidance for consistent and effective response actions."},{"num":146,"text":"A security engineer configured a remote access VPN. The remote access VPN allows end users to connect to the network by using an agent that is installed on the endpoint, which establishes an encrypted tunnel. Which of the following protocols did the engineer most likely implement?","options":[["A","GRE"],["B","IPSec"],["C","SD-WAN"],["D","EAP"]],"correct":"B","explanation":"IPSec is commonly used in remote access VPNs to establish secure, encrypted tunnels between the endpoint and the network. This ensures that data transmitted over the VPN is protected from interception, providing confidentiality, integrity, and authentication. IPSec is a widely used protocol for secure remote access VPNs."},{"num":147,"text":"Executives at a company are concerned about employees accessing systems and information about sensitive company projects unrelated to the employees\u2019 normal job duties. Which of the following enterprise security capabilities will the security team most likely deploy to detect that activity?","options":[["A","UBA"],["B","EDR"],["C","NAC"],["D","DLP"]],"correct":"A","explanation":"UBA helps detect unusual or unauthorized access patterns by analyzing user behavior and identifying deviations from typical access patterns. It can alert the security team when employees attempt to access systems or data unrelated to their job duties, which addresses the executives' concern about potential insider threats or policy violations related to sensitive projects."},{"num":148,"text":"Several customers want an organization to verify its security controls are operating effectively and have requested an independent opinion. Which of the following is the most efficient way to address these requests?","options":[["A","Hire a vendor to perform a penetration test"],["B","Perform an annual self-assessment."],["C","Allow each client the right to audit"],["D","Provide a third-party attestation report"]],"correct":"D","explanation":"A third-party attestation report, such as a SOC 2 report, is an independent assessment of the organization\u2019s security controls conducted by an external auditor. This report provides clients with the assurance they need without requiring each client to conduct their own audit or the organization to perform separate assessments, making it both efficient and credible."},{"num":149,"text":"A university employee logged on to the academic server and attempted to guess the system administrators\u2019 log-in credentials. Which of the following security measures should the university have implemented to detect the employee\u2019s attempts to gain access to the administrators\u2019 accounts?","options":[["A","Two-factor authentication"],["B","Firewall"],["C","Intrusion prevention system"],["D","User activity logs"]],"correct":"D","explanation":"User activity logs record user actions, including failed login attempts, account access patterns, and unusual behaviors. By reviewing these logs, security teams can detect unauthorized access attempts, such as an employee attempting to guess administrator credentials."},{"num":150,"text":"Which of the following consequences would a retail chain most likely face from customers in the event the retailer is non-compliant with PCI DSS?","options":[["A","Contractual impacts"],["B","Sanctions"],["C","Fines"],["D","Reputational damage"]],"correct":"D","explanation":"While fines, sanctions, and contractual impacts are possible outcomes from regulatory bodies or payment processors, reputational damage is the primary consequence directly impacting customers. If customers learn that the retailer failed to protect their payment information, their trust in the brand may erode, potentially leading to a loss of business and harm to the retailer's reputation."},{"num":151,"text":"A security analyst is reviewing logs and discovers the following: Which of the following should be used to best mitigate this type of attack?","options":[["A","Input sanitization"],["B","Secure cookies"],["C","Static code analysis"],["D","Sandboxing"]],"correct":"A","explanation":"Input sanitization ensures that any user-supplied data is properly filtered and cleaned before being processed by the application. By sanitizing inputs, the system can prevent malicious command injection attempts like the one shown in the log entry.","image":"q151.jpg"},{"num":152,"text":"An administrator is installing an SSL certificate on a new system. During testing, errors indicate that the certificate is not trusted. The administrator has verified with the issuing CA and has validated the private key. Which of the following should the administrator check for next?","options":[["A","If the wildcard certificate is configured"],["B","If the certificate signing request is valid"],["C","If the root certificate is installed"],["D","If the public key is configured"]],"correct":"C","explanation":"If the certificate is not trusted, it\u2019s often because the root certificate (or intermediate certificate) from the issuing Certificate Authority (CA) is not installed or not recognized by the system. The root certificate verifies the chain of trust, and without it, the SSL certificate may not be trusted by the system or browser. Installing the root and any necessary intermediate certificates should resolve the trust issue."},{"num":153,"text":"An employee emailed a new systems administrator a malicious web link and convinced the administrator to change the email server\u2019s password. The employee used this access to remove the mailboxes of key personnel. Which of the following security awareness concepts would help prevent this threat in the future?","options":[["A","Recognizing phishing"],["B","Providing situational awareness training"],["C","Using password management"],["D","Reviewing email policies"]],"correct":"A","explanation":"In this scenario, the employee used a form of social engineering by sending a malicious link and persuading the administrator to take unauthorized actions. Training employees to recognize phishing attempts and other social engineering tactics would help them identify and avoid suspicious requests, reducing the likelihood of falling victim to similar threats in the future."},{"num":154,"text":"Which of the following strategies should an organization use to efficiently manage and analyze multiple types of logs?","options":[["A","Deploy a SIEM solution"],["B","Create custom scripts to aggregate and analyze logs."],["C","Implement EDR technology."],["D","Install a unified threat management appliance."]],"correct":"A","explanation":"A Security Information and Event Management (SIEM) solution centralizes log collection, aggregation, and analysis from various sources. SIEMs provide real-time monitoring, correlation, and alerting on security events, enabling organizations to efficiently manage and analyze logs from diverse systems in a single platform. This approach is highly effective for identifying security incidents and ensuring compliance."},{"num":155,"text":"A new security regulation was announced that will take effect in the coming year. A company must comply with it to remain in business. Which of the following activities should the company perform next?","options":[["A","Gap analysis"],["B","Policy review"],["C","Security procedure evaluation"],["D","Threat scope reduction"]],"correct":"A","explanation":"A gap analysis will help the company identify the differences between its current security practices and the requirements of the new regulation. This analysis provides a clear understanding of what needs to be addressed to achieve compliance, allowing the company to prioritize and implement necessary changes before the regulation takes effect."},{"num":156,"text":"An accountant is transferring information to a bank over FTP. Which of the following mitigations should the accountant use to protect the confidentiality of the data?","options":[["A","Tokenization"],["B","Data masking"],["C","Encryption"],["D","Obfuscation"]],"correct":"C","explanation":"Encrypting the data ensures that it remains confidential and protected from unauthorized access during transfer. Standard FTP does not provide secure transmission, so adding encryption\u2014such as using FTPS (FTP Secure) or SFTP (SSH File Transfer Protocol)\u2014will safeguard the data by making it unreadable to anyone intercepting the transfer."},{"num":157,"text":"An organization has recently decided to implement SSO. The requirements are to leverage access tokens and focus on application authorization rather than user authentication. Which of the following solutions would the engineering team most likely configure?","options":[["A","LDAP"],["B","Federation"],["C","SAML"],["D","OAuth"]],"correct":"D","explanation":"OAuth is designed for authorization rather than authentication. It uses access tokens to grant applications permission to access resources on behalf of a user, focusing on what the application can do with the user's data rather than verifying the user's identity. This makes OAuth a suitable choice for Single Sign-On (SSO) when the focus is on application authorization."},{"num":158,"text":"Which of the following would most likely be used by attackers to perform credential harvesting?","options":[["A","Social engineering"],["B","Supply chain compromise"],["C","Third-party software"],["D","Rainbow table"]],"correct":"A","explanation":"Social engineering tactics, such as phishing, are commonly used by attackers to trick individuals into revealing their login credentials. By posing as a trusted entity or creating a fake login page, attackers can harvest usernames and passwords directly from unsuspecting users. This method is highly effective and frequently used for credential harvesting."},{"num":159,"text":"A security engineer would like to enhance the use of automation and orchestration within the SIEM. Which of the following would be the primary benefit of this enhancement?","options":[["A","It increases complexity."],["B","It removes technical debt."],["C","It adds additional guard rails."],["D","It acts as a workforce multiplier."]],"correct":"D","explanation":"By automating repetitive tasks and orchestrating responses to common security incidents, the SIEM can handle more work without requiring additional personnel. This enhancement allows the security team to be more efficient, respond faster, and focus on more complex tasks, effectively multiplying the impact of the existing workforce."},{"num":160,"text":"A systems administrator receives an alert that a company\u2019s internal file server is very slow and is only working intermittently. The systems administrator reviews the server management software and finds the following information about the server: Which of the following indicators most likely triggered this alert?","options":[["A","Concurrent session usage"],["B","Network saturation"],["C","Account lockout"],["D","Resource consumption"]],"correct":"D","explanation":"The attached information shows that the CPU usage is at 99.6% and memory usage is at 97%. These high levels of resource consumption would lead to slow performance and intermittent issues, triggering an alert due to the server\u2019s limited ability to handle additional requests.","image":"q160.jpg"},{"num":161,"text":"Which of the following data states applies to data that is being actively processed by a database server?","options":[["A","In use"],["B","At rest"],["C","In transit"],["D","Being hashed"]],"correct":"A","explanation":"Data \"in use\" refers to data actively being accessed, processed, or modified by an application or system, such as a database server. This is distinct from data \"at rest,\" which is stored but not actively accessed, and data \"in transit,\" which is being transmitted over a network."},{"num":162,"text":"Which of the following architectures is most suitable to provide redundancy for critical business processes?","options":[["A","Network-enabled"],["B","Server-side"],["C","Cloud-native"],["D","Multitenant"]],"correct":"C","explanation":"Cloud-native architectures are designed with scalability, redundancy, and resilience in mind. They leverage the distributed nature of cloud infrastructure, allowing for automatic failover, load balancing, and redundancy across multiple geographic regions. This ensures high availability and continuous operation for critical business processes, even in the event of hardware or regional failures."},{"num":163,"text":"After a security incident, a systems administrator asks the company to buy a NAC platform. Which of the following attack surfaces is the systems administrator trying to protect?","options":[["A","Bluetooth"],["B","Wired"],["C","NFC"],["D","SCADA"]],"correct":"B","explanation":"Network Access Control (NAC) platforms are primarily used to secure access to the organization's network, typically focusing on wired and wireless connections. By implementing NAC, the administrator can control which devices are allowed to connect to the network and enforce security policies, reducing the risk of unauthorized access via the wired network."},{"num":164,"text":"While reviewing logs, a security administrator identifies the following code: <script>function (send_info)</script> Which of the following best describes the vulnerability being exploited?","options":[["A","XSS"],["B","SQLi"],["C","DDoS"],["D","CSRF"]],"correct":"A","explanation":"The <script> tags in the code suggest a Cross-Site Scripting (XSS) attack, where malicious scripts are injected into web pages viewed by other users. XSS vulnerabilities allow attackers to execute scripts in the context of a user's browser, which can lead to data theft, session hijacking, and other malicious actions."},{"num":165,"text":"An organization issued new laptops to all employees and wants to provide web filtering both in and out of the office without configuring additional access to the network. Which of the following types of web filtering should a systems administrator configure?","options":[["A","Agent-based"],["B","Centralized proxy"],["C","URL scanning"],["D","Content categorization"]],"correct":"A","explanation":"An agent-based web filtering solution installs a software agent directly on the laptops. This approach allows the filtering to work regardless of the device's location (in or out of the office) without requiring additional network configuration. The agent enforces web filtering policies locally on each laptop, ensuring consistent protection across various network environments."},{"num":166,"text":"Which of the following should be used to aggregate log data in order to create alerts and detect anomalous activity?","options":[["A","SIEM"],["B","WAF"],["C","Network taps"],["D","IDS"]],"correct":"A","explanation":"A SIEM solution collects and aggregates log data from various sources across the network, enabling realtime monitoring, correlation, and alerting on security events. It is designed to detect anomalous activity and provide insights into potential security incidents by analyzing patterns and behaviors across the log data."},{"num":167,"text":"Which of the following provides the best protection against unwanted or insecure communications to and from a device?","options":[["A","System hardening"],["B","Host-based firewall"],["C","Intrusion detection system"],["D","Anti-malware software"]],"correct":"B","explanation":"A host-based firewall monitors and controls incoming and outgoing network traffic on a specific device, based on predetermined security rules. It provides protection by blocking unauthorized or potentially harmful communications, ensuring that only trusted traffic can access the device. This helps prevent both inbound and outbound threats at the device level."},{"num":168,"text":"Which of the following is the primary purpose of a service that tracks log-ins and time spent using the service?","options":[["A","Availability"],["B","Accounting"],["C","Authentication"],["D","Authorization"]],"correct":"B","explanation":"Accounting involves tracking and recording user activities, such as log-ins and time spent using a service. This information can be used for auditing, billing, usage analysis, and ensuring compliance with policies. Accounting is one of the components of the AAA model (Authentication, Authorization, and Accounting)."},{"num":169,"text":"An employee who was working remotely lost a mobile device containing company data. Which of the following provides the best solution to prevent future data loss?","options":[["A","MDM"],["B","DLP"],["C","FDE"],["D","EDR"]],"correct":"A","explanation":"MDM allows an organization to remotely manage, monitor, and secure mobile devices used by employees, especially when they contain company data. With MDM, administrators can enforce security policies, remotely lock or wipe lost or stolen devices, and ensure compliance with data protection policies, thereby mitigating the risk of data loss."},{"num":170,"text":"An IT administrator needs to ensure data retention standards are implemented on an enterprise application. Which of the following describes the administrator\u2019s role?","options":[["A","Processor"],["B","Custodian"],["C","Privacy officer"],["D","Owner"]],"correct":"B","explanation":"A custodian is responsible for the implementation and enforcement of data management policies, including data retention standards, on systems and applications. Custodians manage the technical aspects of data storage and maintenance according to the organization\u2019s policies and standards, supporting the data owner\u2019s requirements."},{"num":171,"text":"A company plans to secure its systems by: Preventing users from sending sensitive data over corporate email Restricting access to potentially harmful websites Which of the following features should the company set up? (Choose two.)","options":[["A","DLP software"],["B","DNS filtering"],["C","File integrity monitoring"],["D","Stateful firewall"],["E","Guardrails"],["F","Antivirus signatures"]],"correct":"AB","explanation":"DLP (Data Loss Prevention) software: DLP helps prevent users from sending sensitive data over corporate email by monitoring and controlling the flow of sensitive information. DNS filtering: DNS filtering restricts access to potentially harmful websites by blocking access to sites based on their domain names, helping to protect users from malicious or inappropriate content."},{"num":172,"text":"A company processes and stores sensitive data on its own systems. Which of the following steps should the company take first to ensure compliance with privacy regulations?","options":[["A","Implement access controls and encryption."],["B","Develop and provide training on data protection policies."],["C","Create incident response and disaster recovery plans."],["D","Purchase and install security software."]],"correct":"B","explanation":"Establishing clear data protection policies and training employees is foundational for compliance. It ensures that everyone in the organization understands the requirements, their responsibilities, and how to handle sensitive data correctly. This foundation enables effective implementation of technical controls, incident response plans, and security measures in alignment with privacy regulations."},{"num":173,"text":"Which of the following cryptographic methods is preferred for securing communications with limited computing resources?","options":[["A","Hashing algorithm"],["B","Public key infrastructure"],["C","Symmetric encryption"],["D","Elliptic curve cryptography"]],"correct":"C","explanation":"N/A"},{"num":174,"text":"A network administrator wants to ensure that network traffic is highly secure while in transit. Which of the following actions best describes the actions the network administrator should take?","options":[["A","Ensure that NAC is enforced on all network segments, and confirm that firewalls have updated policies to block unauthorized traffic."],["B","Ensure only TLS and other encrypted protocols are selected for use on the network, and only permit authorized traffic via secure protocols."],["C","Configure the perimeter IPS to block inbound HTTPS directory traversal traffic, and verify that signatures are updated on a daily basis."],["D","Ensure the EDR software monitors for unauthorized applications that could be used by threat actors, and configure alerts for the security team."]],"correct":"B","explanation":"Using TLS and other encrypted protocols ensures that data is securely transmitted, protecting it from interception or eavesdropping. By restricting traffic to secure protocols, the administrator can maintain high security for data in transit across the network. This approach directly addresses securing network traffic rather than focusing solely on perimeter or endpoint security."},{"num":175,"text":"Which of the following definitions best describes the concept of log correlation?","options":[["A","Combining relevant logs from multiple sources into one location"],["B","Searching and processing data to identify patterns of malicious activity"],["C","Making a record of the events that occur in the system"],["D","Analyzing the log files of the system components"]],"correct":"B","explanation":"Log correlation involves analyzing and linking data from multiple sources to identify patterns, trends, or sequences of events that indicate potential security incidents or malicious activity. This process helps security teams detect complex threats that may not be evident from individual logs alone."},{"num":176,"text":"An enterprise security team is researching a new security architecture to better protect the company\u2019s networks and applications against the latest cyberthreats. The company has a fully remote workforce. The solution should be highly redundant and enable users to connect to a VPN with an integrated, softwarebased firewall. Which of the following solutions meets these requirements?","options":[["A","IPS"],["B","SIEM"],["C","SASE"],["D","CASB"]],"correct":"C","explanation":"SASE combines network and security functions, including VPN, software-based firewalls, secure web gateways, and more, into a single cloud-delivered service. It is well-suited for a fully remote workforce as it provides secure, scalable, and redundant access to company resources from any location, while protecting networks and applications against the latest cyberthreats."},{"num":177,"text":"Which of the following is the best way to validate the integrity and availability of a disaster recovery site?","options":[["A","Lead a simulated failover."],["B","Conduct a tabletop exercise."],["C","Periodically test the generators."],["D","Develop requirements for database encryption."]],"correct":"A","explanation":"A simulated failover involves switching operations from the primary site to the disaster recovery site, testing the systems, applications, and processes in a real-world scenario. This approach validates that the disaster recovery site can support operations effectively, ensuring both integrity and availability in the event of an actual disaster."},{"num":178,"text":"Which of the following allows an exploit to go undetected by the operating system?","options":[["A","Firmware vulnerabilities"],["B","Side loading"],["C","Memory injection"],["D","Encrypted payloads"]],"correct":"C","explanation":"Memory injection techniques allow attackers to inject malicious code directly into a process's memory space, often bypassing traditional file-based detection methods. By operating in-memory, these exploits can evade detection by the operating system and avoid leaving traces on disk, making them harder for antivirus and other security software to identify."},{"num":179,"text":"A malicious insider from the marketing team alters records and transfers company funds to a personal account. Which of the following methods would be the best way to secure company records in the future?","options":[["A","Permission restrictions"],["B","Hashing"],["C","Input validation"],["D","Access control list"]],"correct":"A","explanation":"Implementing strict permission restrictions ensures that users can only access the data and functions necessary for their specific roles. By limiting access rights, the company can reduce the risk of unauthorized modifications by restricting sensitive financial records to only those who absolutely need access. Additionally, permission restrictions allow for better monitoring and control over sensitive data, making it harder for malicious insiders to perform unauthorized actions."},{"num":180,"text":"An organization is required to provide assurance that its controls are properly designed and operating effectively. Which of the following reports will best achieve the objective?","options":[["A","Red teaming"],["B","Penetration testing"],["C","Independent audit"],["D","Vulnerability assessment"]],"correct":"C","explanation":"An independent audit provides an unbiased assessment of the organization\u2019s controls, verifying that they are properly designed and operating effectively. Such audits often result in formal reports, such as SOC (Service Organization Control) reports, which are specifically designed to give assurance to stakeholders regarding the effectiveness of controls."},{"num":181,"text":"A systems administrator successfully configures VPN access to a cloud environment. Which of the following capabilities should the administrator use to best facilitate remote administration?","options":[["A","A jump host in the shared services security zone"],["B","An SSH server within the corporate LAN"],["C","A reverse proxy on the firewall"],["D","An MDM solution with conditional access"]],"correct":"A","explanation":"A jump host in a shared services security zone is specifically designed to provide secure access to remote environments, such as a cloud environment, while ensuring that access is monitored and controlled. This setup facilitates remote administration by providing a dedicated entry point, allowing administrators to access sensitive network areas through a secure, segmented pathway. This setup minimizes direct exposure to the cloud environment and enhances security."},{"num":182,"text":"Which of the following best describes the concept of information being stored outside of its country of origin while still being subject to the laws and requirements of the country of origin?","options":[["A","Data sovereignty"],["B","Geolocation"],["C","Intellectual property"],["D","Geographic restrictions"]],"correct":"A","explanation":"Data sovereignty refers to the concept that data stored outside its country of origin is still subject to the laws and regulations of that original country. This means that, regardless of where the data is physically stored, it remains governed by the legal requirements and privacy standards of its originating country. This concept is essential for ensuring that data complies with national regulations, even in cross-border storage scenarios."},{"num":183,"text":"An audit reveals that cardholder database logs are exposing account numbers inappropriately. Which of the following mechanisms would help limit the impact of this error?","options":[["A","Segmentation"],["B","Hashing"],["C","Journaling"],["D","Masking"]],"correct":"D","explanation":"Masking is a technique used to obscure sensitive data, such as account numbers, in order to prevent unauthorized access to the full details. By applying masking to the cardholder data in the logs, only part of the account number would be visible, limiting the exposure of sensitive information and thus reducing the potential impact of the error. This approach allows for secure handling of data in scenarios where the information needs to be referenced but not fully exposed."},{"num":184,"text":"A security analyst attempts to start a company's database server. When the server starts, the analyst receives an error message indicating the database server did not pass authentication. After reviewing and testing the system, the analyst receives confirmation that the server has been compromised and that attackers have redirected all outgoing database traffic to a server under their control. Which of the following MITRE ATT&CK techniques did the attacker most likely use to redirect database traffic?","options":[["A","Browser extension"],["B","Process injection"],["C","Valid accounts"],["D","Escape to host"]],"correct":"D","explanation":"N/A"},{"num":185,"text":"A penetration tester enters an office building at the same time as a group of employees despite not having an access badge. Which of the following attack types is the penetration tester performing?","options":[["A","Tailgating"],["B","Shoulder surfing"],["C","RFID cloning"],["D","Forgery"]],"correct":"A","explanation":"Tailgating is a social engineering technique where an unauthorized person gains access to a restricted area by following closely behind authorized individuals without their knowledge or consent. In this scenario, the penetration tester enters the office building at the same time as a group of employees despite not having an access badge, which exemplifies tailgating."},{"num":186,"text":"Which of the following enables the ability to receive a consolidated report from different devices on the network?","options":[["A","IPS"],["B","DLP"],["C","SIEM"],["D","Firewall"]],"correct":"C","explanation":"SIEM (Security Information and Event Management) systems aggregate and analyze log data from various devices across a network, enabling the collection, correlation, and analysis of security-related events. SIEM provides a consolidated report of activities, helping to identify potential security incidents by correlating data from multiple sources, which enhances visibility and response capabilities across the network."},{"num":187,"text":"Which of the following should an organization focus on the most when making decisions about vulnerability prioritization?","options":[["A","Exposure factor"],["B","CVSS"],["C","CVE"],["D","Industry impact"]],"correct":"B","explanation":"The Common Vulnerability Scoring System (CVSS) is a widely used standard that provides a numerical score reflecting the severity of a vulnerability. Organizations use CVSS scores to prioritize vulnerabilities based on their potential impact and exploitability, which helps in assessing which vulnerabilities need urgent remediation. This approach enables systematic vulnerability prioritization based on quantifiable metrics."},{"num":188,"text":"An organization needs to monitor its users\u2019 activities in order to prevent insider threats. Which of the following solutions would help the organization achieve this goal?","options":[["A","Behavioral analytics"],["B","Access control lists"],["C","Identity and access management"],["D","Network intrusion detection system"]],"correct":"A","explanation":"Behavioral analytics involves monitoring and analyzing user behaviors to detect unusual or suspicious patterns that may indicate insider threats. By establishing a baseline of normal behavior, behavioral analytics solutions can identify deviations that could signal potential malicious or risky activities by users, helping to prevent insider threats. This approach is effective in detecting unauthorized actions that traditional access control or identity management systems might miss."},{"num":189,"text":"A customer of a large company receives a phone call from someone claiming to work for the company and asking for the customer\u2019s credit card information. The customer sees the caller ID is the same as the company's main phone number. Which of the following attacks is the customer most likely a target of?","options":[["A","Phishing"],["B","Whaling"],["C","Smishing"],["D","Vishing"]],"correct":"D","explanation":"Vishing (voice phishing) is a social engineering attack where attackers impersonate a trusted entity over the phone to obtain sensitive information, such as credit card details. In this case, the attacker spoofed the company's main phone number on the caller ID to gain the customer\u2019s trust, making it likely that the customer is the target of a vishing attack."},{"num":190,"text":"A security analyst is reviewing logs to identify the destination of command-and-control traffic originating from a compromised device within the on-premises network. Which of the following is the best log to review?","options":[["A","IDS"],["B","Antivirus"],["C","Firewall"],["D","Application"]],"correct":"C","explanation":"Firewall logs are ideal for identifying the destination of command-and-control (C2) traffic because they log all inbound and outbound connections, including IP addresses, ports, and protocols used. By reviewing firewall logs, a security analyst can trace where the compromised device is attempting to send data and potentially identify the external command-and-control server, aiding in the containment of the threat."},{"num":191,"text":"When trying to access an internal website, an employee reports that a prompt displays, stating that the site is insecure. Which of the following certificate types is the site most likely using?","options":[["A","Wildcard"],["B","Root of trust"],["C","Third-party"],["D","Self-signed"]],"correct":"D","explanation":"A self-signed certificate is not issued by a trusted certificate authority, which often causes browsers to flag it as insecure. When accessing a site with a self-signed certificate, users typically receive a warning about the site\u2019s security since the certificate cannot be automatically trusted, making it likely that the internal website is using a self-signed certificate."},{"num":192,"text":"Which of the following would most likely be deployed to obtain and analyze attacker activity and techniques?","options":[["A","Firewall"],["B","IDS"],["C","Honeypot"],["D","Layer 3 switch"]],"correct":"C","explanation":"A honeypot is a decoy system or network resource designed to attract attackers and observe their activity. It is intentionally left vulnerable to capture and analyze attacker behavior, techniques, and tools, providing valuable insights into potential threats without risking actual production systems. This makes it the ideal choice for studying attacker tactics and patterns."},{"num":193,"text":"Which of the following objectives is best achieved by a tabletop exercise?","options":[["A","Familiarizing participants with the incident response process"],["B","Deciding red and blue team rules of engagement"],["C","Quickly determining the impact of an actual security breach"],["D","Conducting multiple security investigations in parallel"]],"correct":"A","explanation":"A tabletop exercise is a discussion-based exercise where participants walk through different scenarios to better understand and familiarize themselves with the incident response process. This type of exercise allows teams to review roles, procedures, and potential responses to various incidents in a low-stress environment, enhancing preparedness and coordination."},{"num":194,"text":"The private key for a website was stolen, and a new certificate has been issued. Which of the following needs to be updated next?","options":[["A","SCEP"],["B","CRL"],["C","OCSP"],["D","CSR"]],"correct":"B","explanation":"The Certificate Revocation List (CRL) should be updated when a private key is compromised. The CRL is a list of certificates that have been revoked by the issuing Certificate Authority (CA) and are no longer trusted. Updating the CRL ensures that clients and systems know the previous certificate is no longer valid, preventing it from being trusted even if the key has been compromised."},{"num":195,"text":"Which of the following organizational documents is most often used to establish and communicate expectations associated with integrity and ethical behavior within an organization?","options":[["A","AUP"],["B","SLA"],["C","EULA"],["D","MOA"]],"correct":"A","explanation":"An Acceptable Use Policy (AUP) is commonly used to establish and communicate the organization\u2019s expectations regarding acceptable behavior, integrity, and ethical conduct. It outlines guidelines for appropriate use of company resources and sets standards for employees to follow, promoting a secure and ethical work environment."},{"num":196,"text":"Which of the following explains how to determine the global regulations that data is subject to regardless of the country where the data is stored?","options":[["A","Geographic dispersion"],["B","Data sovereignty"],["C","Geographic restrictions"],["D","Data segmentation"]],"correct":"B","explanation":"Data sovereignty refers to the principle that data is subject to the laws and regulations of the country where it originated, regardless of where it is stored. This concept ensures that data complies with the legal requirements of its country of origin, even when stored or processed across borders."},{"num":197,"text":"An organization's web servers host an online ordering system. The organization discovers that the servers are vulnerable to a malicious JavaScript injection, which could allow attackers to access customer payment information. Which of the following mitigation strategies would be most effective for preventing an attack on the organization's web servers? (Choose two.)","options":[["A","Regularly updating server software and patches"],["B","Implementing strong password policies"],["C","Encrypting sensitive data at rest and in transit"],["D","Utilizing a web-application firewall"],["E","Performing regular vulnerability scans"],["F","Removing payment information from the servers"]],"correct":"AD","explanation":"Regularly updating server software and applying patches addresses known vulnerabilities, reducing the risk of exploitation through unpatched flaws. A web-application firewall (WAF) is particularly effective against malicious injections, as it monitors and filters HTTP traffic to block injection attempts, such as JavaScript injections. Together, these strategies provide robust protection against attacks targeting the web servers."},{"num":198,"text":"Which of the following tools is best for logging and monitoring in a cloud environment?","options":[["A","IPS"],["B","FIM"],["C","NAC"],["D","SIEM"]],"correct":"D","explanation":"A Security Information and Event Management (SIEM) system is best suited for logging and monitoring in a cloud environment. SIEM tools collect, aggregate, and analyze log data from multiple sources within the environment, providing real-time monitoring, alerts, and analysis of security events. This centralized approach helps identify potential security incidents across cloud resources effectively."},{"num":199,"text":"During a SQL update of a database, a temporary field that was created was replaced by an attacker in order to allow access to the system. Which of the following best describes this type of vulnerability?","options":[["A","Race condition"],["B","Memory injection"],["C","Malicious update"],["D","Side loading"]],"correct":"C","explanation":"N/A"},{"num":200,"text":"A group of developers has a shared backup account to access the source code repository. Which of the following is best way to secure the backup account if there is an SSO failure?","options":[["A","RAS"],["B","EAP"],["C","SAML"],["D","PAM"]],"correct":"D","explanation":"Privileged Access Management (PAM) is the best way to secure shared, privileged accounts like a backup account, especially in cases of Single Sign-On (SSO) failure. PAM solutions provide strict controls over access to sensitive accounts, enforce logging and monitoring, and often include features like session recording and access expiration. This approach ensures that access to the backup account remains secure even when other authentication methods, like SSO, are unavailable."},{"num":201,"text":"Which of the following elements of digital forensics should a company use if it needs to ensure the integrity of evidence?","options":[["A","Preservation"],["B","E-discovery"],["C","Acquisition"],["D","Containment"]],"correct":"A","explanation":"Preservation is the process in digital forensics that ensures the integrity of evidence by maintaining it in its original, unaltered state. This involves safeguarding data against modification or tampering throughout the investigation process, ensuring that the evidence remains reliable and admissible in court if needed."},{"num":202,"text":"A company suffered a critical incident where 30GB of data was exfiltrated from the corporate network. Which of the following actions is the most efficient way to identify where the system data was exfiltrated from and what location the attacker sent the data to?","options":[["A","Analyze firewall and network logs for large amounts of outbound traffic to external IP addresses or domains."],["B","Analyze IPS and IDS logs to find the IP addresses used by the attacker for reconnaissance scans."],["C","Analyze endpoint and application logs to see whether file-sharing programs were running on the company systems."],["D","Analyze external vulnerability scans and automated reports to identify the systems the attacker could have exploited a remote code vulnerability."]],"correct":"A","explanation":"Firewall and network logs are the most efficient sources for identifying large outbound data transfers, as they record all traffic leaving the network. By examining these logs for significant data flows to unfamiliar or external IP addresses or domains, the security team can determine where the data was exfiltrated and potentially identify the destination of the exfiltrated data. This approach directly targets the incident\u2019s key indicators: large data transfer and external communication."},{"num":203,"text":"Which of the following describes the procedures a penetration tester must follow while conducting a test?","options":[["A","Rules of engagement"],["B","Rules of acceptance"],["C","Rules of understanding"],["D","Rules of execution"]],"correct":"A","explanation":"The rules of engagement outline the specific procedures, scope, and limitations that a penetration tester must follow during testing. These rules define acceptable activities, testing boundaries, reporting requirements, and guidelines to ensure the test is conducted ethically, safely, and in alignment with organizational expectations."},{"num":204,"text":"A security analyst wants to better understand the behavior of users and devices in order to gain visibility into potential malicious activities. The analyst needs a control to detect when actions deviate from a common baseline. Which of the following should the analyst use?","options":[["A","Intrusion prevention system"],["B","Sandbox"],["C","Endpoint detection and response"],["D","Antivirus"]],"correct":"C","explanation":"Endpoint Detection and Response (EDR) solutions provide visibility into the behavior of users and devices, monitoring for deviations from established baselines. EDR tools are designed to detect suspicious activities by continuously analyzing endpoint behaviors, which helps identify potential threats, including malicious activities, that may otherwise go unnoticed. This is particularly useful for spotting deviations from normal patterns and enhancing security response."},{"num":205,"text":"A legal department must maintain a backup from all devices that have been shredded and recycled by a third party. Which of the following best describes this requirement?","options":[["A","Data retention"],["B","Certification"],["C","Sanitization"],["D","Destruction"]],"correct":"A","explanation":"Data retention refers to the practice of keeping copies or backups of data for a specific period, even after the original devices have been disposed of or destroyed. In this case, the legal department requires a backup to be maintained from devices that have been shredded and recycled, ensuring that necessary data is preserved in compliance with legal or regulatory requirements."},{"num":206,"text":"Which of the following can be used to compromise a system that is running an RTOS?","options":[["A","Cross-site scripting"],["B","Memory injection"],["C","Replay attack"],["D","Ransomware"]],"correct":"B","explanation":"Memory injection attacks are particularly dangerous for systems running a Real-Time Operating System (RTOS) because these systems often have limited resources and strict timing requirements, making them more susceptible to disruptions caused by injected code. Memory injection can compromise the system's integrity, allowing an attacker to alter its operation or cause it to behave unpredictably."},{"num":207,"text":"Which of the following threat actors would most likely deface the website of a high-profile music group?","options":[["A","Unskilled attacker"],["B","Organized crime"],["C","Nation-state"],["D","Insider threat"]],"correct":"A","explanation":"Unskilled attackers, often referred to as \"script kiddies,\" are more likely to deface websites for attention or to make a public statement rather than for financial gain or political motivations. Defacing a high-profile music group's website aligns with the typical goals of an unskilled attacker seeking notoriety or a sense of accomplishment by exploiting visible and relatively simple vulnerabilities."},{"num":208,"text":"A security architect wants to prevent employees from receiving malicious attachments by email. Which of the following functions should the chosen solution do?","options":[["A","Apply IP address reputation data."],["B","Tap and monitor the email feed."],["C","Scan email traffic inline."],["D","Check SPF records."]],"correct":"C","explanation":"Scanning email traffic inline enables the security solution to inspect attachments and other content in realtime as emails are received. This allows the system to detect and block malicious attachments before they reach employees, effectively preventing potential security incidents caused by harmful email attachments. This approach is essential for identifying and neutralizing threats within email content directly."},{"num":209,"text":"Which of the following activities is the first stage in the incident response process?","options":[["A","Detection"],["B","Declaration"],["C","Containment"],["D","Verification"]],"correct":"A","explanation":"Detection is the first stage in the incident response process. It involves identifying potential security incidents through alerts, monitoring, and analysis to determine if an incident has occurred. Effective detection is crucial as it initiates the response process, allowing the team to assess the situation and proceed with containment and other response steps."},{"num":210,"text":"Which of the following is the main consideration when a legacy system that is a critical part of a company's infrastructure cannot be replaced?","options":[["A","Resource provisioning"],["B","Cost"],["C","Single point of failure"],["D","Complexity"]],"correct":"C","explanation":"When a legacy system that is critical to a company's infrastructure cannot be replaced, the primary consideration is that it may become a single point of failure. This is because legacy systems are often difficult to support, lack redundancy, and may no longer receive updates, making them vulnerable. Ensuring that this critical system is protected from failure is essential to maintain continuity and reduce the risk of operational disruptions."},{"num":211,"text":"Which of the following is a compensating control for providing user access to a high-risk website?","options":[["A","Enabling threat prevention features on the firewall"],["B","Configuring a SIEM tool to capture all web traffic"],["C","Setting firewall rules to allow traffic from any port to that destination"],["D","Blocking that website on the endpoint protection software"]],"correct":"A","explanation":"Enabling threat prevention features on the firewall is a compensating control that adds a layer of security when accessing a high-risk website. This approach helps to detect and block malicious activities associated with the website by scanning for threats, malicious code, and suspicious traffic patterns, thereby mitigating potential risks without completely restricting access."},{"num":212,"text":"An organization is implementing a COPE mobile device management policy. Which of the following should the organization include in the COPE policy? (Choose two.)","options":[["A","Remote wiping of the device"],["B","Data encryption"],["C","Requiring passwords with eight characters"],["D","Data usage caps"],["E","Employee data ownership"],["F","Personal application store access"]],"correct":"AB","explanation":"In a Corporate-Owned, Personally-Enabled (COPE) mobile device management policy, the organization provides devices that employees can use for both work and personal purposes. Remote wiping ensures that the organization can remove sensitive data if the device is lost, stolen, or if the employee leaves the organization. Data encryption protects sensitive data on the device, ensuring security for both corporate and personal use. These controls are essential for securing organizational data on devices used in a COPE model."},{"num":213,"text":"A security administrator observed the following in a web server log while investigating an incident: \"GET ../../../../etc/passwd\" Which of the following attacks did the security administrator most likely see?","options":[["A","Privilege escalation"],["B","Credential replay"],["C","Brute force"],["D","Directory traversal"]],"correct":"D","explanation":"The log entry GET ../../../../etc/passwd indicates a directory traversal attack. Directory traversal is an attack technique that attempts to access files and directories outside the web server's root directory by using sequences like ../ to move up the directory tree. In this case, the attacker is attempting to reach the /etc/passwd file, which typically contains user account information on Unix-based systems. This type of attack can allow unauthorized access to sensitive files on the server."},{"num":214,"text":"An organization wants a third-party vendor to do a penetration test that targets a specific device. The organization has provided basic information about the device. Which of the following best describes this kind of penetration test?","options":[["A","Partially known environment"],["B","Unknown environment"],["C","Integrated"],["D","Known environment"]],"correct":"A","explanation":"A partially known environment penetration test, also known as a \"gray box\" test, is where the tester has limited information about the target, such as basic device details provided by the organization. This type of test simulates an attack by someone with some insider knowledge, allowing for a more realistic assessment of security vulnerabilities than an unknown environment test but with less detailed information than a fully known environment test."},{"num":215,"text":"Which of the following should a security team do first before a new web server goes live?","options":[["A","Harden the virtual host."],["B","Create WAF rules."],["C","Enable network intrusion detection."],["D","Apply patch management."]],"correct":"A","explanation":"Before a new web server goes live, the first step should be to harden the virtual host. Hardening involves securing the server by disabling unnecessary services, configuring permissions, and applying best practices to minimize vulnerabilities. This foundational step reduces the attack surface and ensures the server is secure before additional security measures, such as WAF rules, intrusion detection, or patch management, are applied."},{"num":216,"text":"Which of the following techniques can be used to sanitize the data contained on a hard drive while allowing for the hard drive to be repurposed?","options":[["A","Degaussing"],["B","Drive shredder"],["C","Retention platform"],["D","Wipe tool"]],"correct":"D","explanation":"A wipe tool can be used to securely erase all data on a hard drive without physically damaging it, making it suitable for repurposing. Wiping overwrites the data on the drive multiple times, ensuring that previously stored information cannot be recovered. This approach allows the hard drive to be reused safely, as opposed to degaussing or physical destruction, which renders the drive unusable."},{"num":217,"text":"An attacker submits a request containing unexpected characters in an attempt to gain unauthorized access to information within the underlying systems. Which of the following best describes this attack?","options":[["A","Side loading"],["B","Target of evaluation"],["C","Resource reuse"],["D","SQL injection"]],"correct":"D","explanation":"SQL injection is an attack technique where an attacker includes unexpected characters or SQL code in a request to manipulate a database query, aiming to gain unauthorized access to data or execute additional database commands. This form of injection targets vulnerabilities in applications that don\u2019t properly validate input, allowing attackers to interact with underlying database systems maliciously."},{"num":218,"text":"A security analyst has determined that a security breach would have a financial impact of $15,000 and is expected to occur twice within a three-year period. Which of the following is the ALE for this risk?","options":[["A","$7,500"],["B","$10,000"],["C","$15,000"],["D","$30,000"]],"correct":"B","explanation":"The Annualized Loss Expectancy (ALE) is calculated by multiplying the Single Loss Expectancy (SLE) by the Annualized Rate of Occurrence (ARO). In this case: SLE (Single Loss Expectancy) = $15,000 ARO (Annualized Rate of Occurrence) = 2 occurrences / 3 years = 0.67 per year ALE = SLE \u00d7 ARO = $15,000 \u00d7 0.67 \u2248 $10,000"},{"num":219,"text":"A systems administrator discovers a system that is no longer receiving support from the vendor. However, this system and its environment are critical to running the business, cannot be modified, and must stay online. Which of the following risk treatments is the most appropriate in this situation?","options":[["A","Reject"],["B","Accept"],["C","Transfer"],["D","Avoid"]],"correct":"B","explanation":"When a system is critical, cannot be modified, and must stay online despite no longer receiving vendor support, the most appropriate risk treatment is to accept the risk. This decision acknowledges the potential vulnerabilities but continues operation due to the system's importance. Additional compensating controls, such as network isolation, monitoring, and backup procedures, may be implemented to help mitigate associated risks while accepting them as part of the business necessity."},{"num":220,"text":"A company discovered its data was advertised for sale on the dark web. During the initial investigation, the company determined the data was proprietary data. Which of the following is the next step the company should take?","options":[["A","Identify the attacker\u2019s entry methods."],["B","Report the breach to the local authorities."],["C","Notify the applicable parties of the breach."],["D","Implement vulnerability scanning of the company's systems."]],"correct":"B","explanation":"N/A"},{"num":221,"text":"Which of the following would be the best solution to deploy a low-cost standby site that includes hardware and internet access?","options":[["A","Recovery site"],["B","Cold site"],["C","Hot site"],["D","Warm site"]],"correct":"D","explanation":"N/A"},{"num":222,"text":"An organization needs to determine how many employees are accessing the building each day in order to configure the proper access controls. Which of the following control types best meets this requirement?","options":[["A","Detective"],["B","Preventive"],["C","Corrective"],["D","Directive"]],"correct":"A","explanation":"A detective control is used to identify and record events or actions after they occur. In this case, tracking the number of employees accessing the building each day is a detective control, as it involves monitoring and logging access to gather data for configuring appropriate access controls. This helps the organization assess usage patterns to adjust security measures accordingly."},{"num":223,"text":"An organization wants to implement a secure solution for remote users. The users handle sensitive PHI on a regular basis and need to access an internally developed corporate application. Which of the following best meet the organization's security requirements? (Choose two.)","options":[["A","Local administrative password"],["B","Perimeter network"],["C","Jump server"],["D","WAF"],["E","MFA"],["F","VPN"]],"correct":"EF","explanation":"Multi-factor authentication (MFA) and a virtual private network (VPN) best meet the organization's security requirements for remote access to sensitive information like protected health information (PHI). MFA adds a layer of security by requiring multiple forms of verification before granting access, which helps protect against unauthorized access. VPN provides a secure encrypted connection for remote users, ensuring that data transmitted over the network remains confidential and secure. Together, these controls help secure remote access to the corporate application handling sensitive data."},{"num":224,"text":"A security officer is implementing a security awareness program and is placing security-themed posters around the building and is assigning online user training. Which of the following would the security officer most likely implement?","options":[["A","Password policy"],["B","Access badges"],["C","Phishing campaign"],["D","Risk assessment"]],"correct":"C","explanation":"In a security awareness program, a phishing campaign is often implemented alongside other awareness activities, such as security-themed posters and online user training. Phishing simulations help users recognize and respond correctly to phishing attempts, reinforcing the training's effectiveness. This practical exercise increases awareness about social engineering attacks, making it a suitable component of a comprehensive security awareness program."},{"num":225,"text":"A security consultant is working with a client that wants to physically isolate its secure systems. Which of the following best describes this architecture?","options":[["A","SDN"],["B","Air gapped"],["C","Containerized"],["D","Highly available"]],"correct":"B","explanation":"An air-gapped system is physically isolated from any other network, meaning it has no direct or indirect connection to the internet or other networks. This architecture is commonly used to protect highly secure systems by ensuring that they are not accessible remotely, thus reducing the risk of unauthorized access or cyberattacks. This approach aligns with the client\u2019s goal of physically isolating its secure systems."},{"num":226,"text":"A company is in the process of migrating to cloud-based services. The company\u2019s IT department has limited resources for migration and ongoing support. Which of the following best meets the company\u2019s needs?","options":[["A","IPS"],["B","WAF"],["C","SASE"],["D","IAM"]],"correct":"C","explanation":"Secure Access Service Edge (SASE) combines network security functions with wide area network (WAN) capabilities in a cloud-delivered model, which simplifies management and provides scalable, secure access to cloud-based services. For a company with limited IT resources, SASE offers an integrated solution that reduces the need for extensive on-premises infrastructure and simplifies ongoing support. This approach allows the company to enhance security while efficiently supporting its cloud migration."},{"num":227,"text":"An employee clicks a malicious link in an email that appears to be from the company's Chief Executive Officer. The employee's computer is infected with ransomware that encrypts the company's files. Which of the following is the most effective way for the company to prevent similar incidents in the future?","options":[["A","Security awareness training"],["B","Database encryption"],["C","Segmentation"],["D","Reporting suspicious emails"]],"correct":"A","explanation":"Security awareness training is the most effective way to prevent similar incidents, as it educates employees on how to recognize and respond to phishing emails and other social engineering attacks. By training employees to spot suspicious links and emails, especially those that appear to be from high-level executives, the company can reduce the likelihood of employees falling victim to such attacks in the future."},{"num":228,"text":"Which of the following types of vulnerabilities is primarily caused by improper use and management of cryptographic certificates?","options":[["A","Misconfiguration"],["B","Resource reuse"],["C","Insecure key storage"],["D","Weak cipher suites"]],"correct":"C","explanation":"N/A"},{"num":229,"text":"Which of the following best describe the benefits of a microservices architecture when compared to a monolithic architecture? (Choose two.)","options":[["A","Easier debugging of the system"],["B","Reduced cost of ownership of the system"],["C","Improved scalability of the system"],["D","Increased compartmentalization of the system"],["E","Stronger authentication of the system"],["F","Reduced complexity of the system"]],"correct":"CD","explanation":"A microservices architecture offers the following benefits compared to a monolithic architecture: Improved scalability: Each microservice can be independently scaled based on demand, allowing more efficient resource usage and better performance for high-demand components. Increased compartmentalization : Microservices are designed as separate, independent components, which improves modularity and allows for better fault isolation, easier updates, and focused development on specific services. While microservices have benefits such as easier debugging and reduced cost of ownership, their primary advantages lie in scalability and compartmentalization."},{"num":230,"text":"A user's workstation becomes unresponsive and displays a ransom note demanding payment to decrypt files. Before the attack, the user opened a resume they received in a message, browsed the company's website, and installed OS updates. Which of the following is the most likely vector of this attack?","options":[["A","Spear-phishing attachment"],["B","Watering hole"],["C","Infected website"],["D","Typosquatting"]],"correct":"A","explanation":"The most likely vector of this attack is a spear-phishing attachment. The user opened a resume received in a message, which is a common method used in spear-phishing attacks. These attacks often involve sending a specifically crafted attachment (like a resume) to the targeted user. Once the attachment is opened, it could trigger malware, such as ransomware, which encrypts files on the system and displays a ransom note. This attack vector aligns with the described symptoms, as the user interacted with the malicious attachment before experiencing the ransomware infection."},{"num":231,"text":"A penetration tester finds an unused Ethernet port during an on-site penetration test. Upon plugging a device into the unused port, the penetration tester notices that the machine is assigned an IP address, allowing the tester to enumerate the local network. Which of the following should an administrator implement in order to prevent this situation from happening in the future?","options":[["A","Port security"],["B","Transport Layer Security"],["C","Proxy server"],["D","Security zones"]],"correct":"A","explanation":"Port security is a network security feature that restricts input to an Ethernet port based on MAC addresses, which helps prevent unauthorized devices from gaining access to the network. By implementing port security, administrators can control which devices are allowed to connect to specific network ports, preventing unauthorized access through unused or untrusted ports. This measure would have prevented the penetration tester from gaining access to the local network by plugging into an unused port."},{"num":232,"text":"Which of the following should be used to ensure an attacker is unable to read the contents of a mobile device's drive if the device is lost?","options":[["A","TPM"],["B","ECC"],["C","FDE"],["D","HSM"]],"correct":"C","explanation":"Full Disk Encryption (FDE) ensures that all data on a mobile device's drive is encrypted, making it unreadable without the proper decryption key. If the device is lost or stolen, the data remains protected because the contents of the drive are encrypted and cannot be accessed without the appropriate credentials. This is the most effective method to protect the data in case of device loss."},{"num":233,"text":"A security administrator documented the following records during an assessment of network services: Two weeks later, the administrator performed a log review and noticed the records were changed as follows: When consulting the service owner, the administrator validated that the new address was not part of the company network. Which of the following was the company most likely experiencing?","options":[["A","DDoS attack"],["B","DNS poisoning"],["C","Ransomware compromise"],["D","Spyware infection"]],"correct":"B","explanation":"DNS poisoning (also known as DNS cache poisoning) involves an attacker manipulating DNS records, redirecting traffic to malicious destinations. In this case, the change in the DNS records to an IP address outside the company's network suggests that the attacker may have poisoned the DNS cache or altered the DNS records to reroute traffic, potentially leading to a malicious site or server. This is not a DDoS attack, ransomware compromise, or spyware infection as the primary issue appears to be manipulation of DNS records, which is characteristic of DNS poisoning.","image":"q233.jpg"},{"num":234,"text":"Which of the following is the primary reason why false negatives on a vulnerability scan should be a concern?","options":[["A","The system has vulnerabilities that are not being detected."],["B","The time to remediate vulnerabilities that do not exist is excessive."],["C","Vulnerabilities with a lower severity will be prioritized over critical vulnerabilities."],["D","The system has vulnerabilities, and a patch has not yet been released."]],"correct":"A","explanation":"False negatives in vulnerability scanning occur when the scan fails to detect existing vulnerabilities. This is a concern because it means that the system has vulnerabilities, but they are not being identified and addressed, leaving the system potentially exposed to exploitation. Unlike false positives, which result in wasted time on vulnerabilities that aren't actually present, false negatives directly impact security by failing to identify real risks."},{"num":235,"text":"A company is concerned about theft of client data from decommissioned laptops. Which of the following is the most cost-effective method to decrease this risk?","options":[["A","Wiping"],["B","Recycling"],["C","Shredding"],["D","Deletion"]],"correct":"A","explanation":"Wiping is the most cost-effective method to decrease the risk of client data theft from decommissioned laptops. Wiping involves using software tools to securely erase all data on the hard drive, making it unrecoverable. This ensures that sensitive information cannot be accessed, even if the laptop is later reused or disposed of. Compared to shredding (which involves physical destruction and is more costly) or simple deletion (which does not truly erase the data), wiping is an effective, inexpensive way to mitigate the risk."},{"num":236,"text":"A company that has a large IT operation is looking to better control, standardize, and lower the time required to build new servers. Which of the following architectures will best achieve the company\u2019s objectives?","options":[["A","IoT"],["B","IaC"],["C","IaaS"],["D","ICS"]],"correct":"B","explanation":"Infrastructure as Code (IaC) is the best solution for controlling, standardizing, and speeding up the process of building new servers. IaC allows the company to define the infrastructure using code, enabling automated provisioning, configuration, and management of servers and other IT resources. This approach ensures consistency, reduces human error, and accelerates the deployment process. With IaC, the company can quickly spin up new servers in a standardized and efficient manner."},{"num":237,"text":"A government official receives a blank envelope containing photos and a note instructing the official to wire a large sum of money by midnight to prevent the photos from being leaked on the internet. Which of the following best describes the threat actor's intent?","options":[["A","Organized crime"],["B","Philosophical beliefs"],["C","Espionage"],["D","Blackmail"]],"correct":"D","explanation":"The threat actor's intent in this scenario is best described as blackmail. The official is being threatened with the release of compromising photos unless a large sum of money is paid, which is a classic form of blackmail. The attacker is using the threat of exposing sensitive information to coerce the official into making a payment."},{"num":238,"text":"Which of the following is the best security reason for closing service ports that are not needed?","options":[["A","To mitigate risks associated with unencrypted traffic"],["B","To eliminate false positives from a vulnerability scan"],["C","To reduce a system's attack surface"],["D","To improve a system's resource utilization"]],"correct":"C","explanation":"Closing unnecessary service ports is a critical security measure because it helps to reduce the system's attack surface. Each open port represents a potential entry point for attackers, and if a service is not needed, keeping the associated port open unnecessarily increases the risk of exploitation. By closing unused ports, you minimize the number of possible attack vectors, making it harder for attackers to compromise the system."},{"num":239,"text":"Which of the following would a security administrator use to comply with a secure baseline during a patch update?","options":[["A","Information security policy"],["B","Service-level expectations"],["C","Standard operating procedure"],["D","Test result report"]],"correct":"C","explanation":"A Standard Operating Procedure (SOP) is used to ensure that patch updates and other security practices are carried out in a consistent, secure, and compliant manner, adhering to the organization's secure baseline. SOPs provide step-by-step instructions and guidelines for performing tasks like patching, ensuring that all actions taken are in line with established security standards and compliance requirements."},{"num":240,"text":"A malicious actor conducted a brute-force attack on a company's web servers and eventually gained access to the company's customer information database. Which of the following is the most effective way to prevent similar attacks?","options":[["A","Regular patching of servers"],["B","Web application firewalls"],["C","Multifactor authentication"],["D","Enabling encryption of customer data"]],"correct":"C","explanation":"The most effective way to prevent similar brute-force attacks in the future is to implement multifactor authentication (MFA). MFA requires users to provide multiple forms of authentication (such as a password and a one-time code sent to a mobile device) before gaining access. This significantly reduces the likelihood of successful brute-force attacks, as attackers would need more than just the password to gain unauthorized access to the system. While regular patching, web application firewalls, and encryption of customer data are important security measures, MFA directly addresses the core vulnerability exploited by brute-force attacks."},{"num":241,"text":"Which of the following options will provide the lowest RTO and RPO for a database?","options":[["A","Snapshots"],["B","On-site backups"],["C","Journaling"],["D","Hot site"]],"correct":"C","explanation":"N/A"},{"num":242,"text":"Which of the following is a possible consequence of a VM escape?","options":[["A","Malicious instructions can be inserted into memory and give the attacker elevated permissions."],["B","An attacker can access the hypervisor and compromise other VMs."],["C","Unencrypted data can be read by a user who is in a separate environment."],["D","Users can install software that is not on the manufacturer\u2019s approved list."]],"correct":"B","explanation":"A VM escape occurs when an attacker manages to break out of a virtual machine (VM) and gain access to the underlying hypervisor or host system. Once the attacker has access to the hypervisor, they can potentially compromise other VMs running on the same host, which could lead to unauthorized access, data breaches, or further exploitation of the system."},{"num":243,"text":"A security team at a large, global company needs to reduce the cost of storing data used for performing investigations. Which of the following types of data should have its retention length reduced?","options":[["A","Packet capture"],["B","Endpoint logs"],["C","OS security logs"],["D","Vulnerability scan"]],"correct":"A","explanation":"Packet capture data generally has a high storage cost because it records detailed network traffic and is often voluminous. While packet capture data is valuable for short-term investigations and troubleshooting, it typically does not need to be retained long-term for most security operations. Reducing its retention length can help lower the cost of storing such data."},{"num":244,"text":"Which of the following is a type of vulnerability that involves inserting scripts into web-based applications in order to take control of the client's web browser?","options":[["A","SQL injection"],["B","Cross-site scripting"],["C","Zero-day exploit"],["D","On-path attack"]],"correct":"B","explanation":"Cross-site scripting (XSS) is a type of vulnerability that occurs when attackers inject malicious scripts into web applications. These scripts are then executed by the client's web browser, which can allow the attacker to steal sensitive data (such as cookies or session tokens), impersonate users, or perform other malicious actions within the context of the user's session."},{"num":245,"text":"While investigating a possible incident, a security analyst discovers the following: Which of the following should the analyst do first?","options":[["A","Implement a WAF."],["B","Disable the query.php script."],["C","Block brute-force attempts on temporary users."],["D","Check the users table for new accounts."]],"correct":"D","explanation":"The log snippet shows an HTTP request where an attacker is attempting to insert new data into the database through a SQL injection attack. The request contains an SQL command INSERT INTO users VALUES ('temp', 'pass123'), which is likely an attempt to create a new user with the username \"temp\" and the password \"pass123.\"","image":"q245.jpg"},{"num":246,"text":"Due to a cyberattack, a company's IT systems were not operational for an extended period of time. The company wants to measure how quickly the systems must be restored in order to minimize business disruption. Which of the following would the company most likely use?","options":[["A","Recovery point objective"],["B","Risk appetite"],["C","Risk tolerance"],["D","Recovery time objective"],["E","Mean time between failure"]],"correct":"D","explanation":"The Recovery Time Objective (RTO) refers to the maximum acceptable amount of time that an IT system can be down after an incident before causing significant disruption to the business. This metric is used to set restoration goals and minimize business impact. RTO helps the company define how quickly the systems need to be restored to resume normal operations."},{"num":247,"text":"Which of the following actors attacking an organization is the most likely to be motivated by personal beliefs?","options":[["A","Nation-state"],["B","Organized crime"],["C","Hacktivist"],["D","Insider threat"]],"correct":"C","explanation":"A hacktivist is a type of attacker who is motivated by personal or political beliefs, often aiming to promote a cause or to protest against certain actions or policies. Hacktivists typically use hacking as a means of expressing their views or making a statement, rather than for financial gain or other personal benefits, which distinguishes them from other types of threat actors like nation-states or organized crime groups."},{"num":248,"text":"Which of the following should a security team use to document persistent vulnerabilities with related recommendations?","options":[["A","Audit report"],["B","Risk register"],["C","Compliance report"],["D","Penetration test"]],"correct":"B","explanation":"A risk register is a document used to track and manage risks, including persistent vulnerabilities. It includes details about each vulnerability, its potential impact, the likelihood of its occurrence, and recommendations for mitigating or managing the risk. The risk register serves as a tool to prioritize and address ongoing security issues systematically."},{"num":249,"text":"An organization purchased a critical business application containing sensitive data. The organization would like to ensure that the application is not exploited by common data exfiltration attacks. Which of the following approaches would best help to fulfill this requirement?","options":[["A","URL scanning"],["B","WAF"],["C","Reverse proxy"],["D","NAC"]],"correct":"B","explanation":"A Web Application Firewall (WAF) is specifically designed to protect web applications by filtering and monitoring HTTP traffic. It helps prevent common data exfiltration attacks, such as SQL injection, cross-site scripting (XSS), and other web-based threats, by inspecting incoming traffic and blocking malicious requests. A WAF would be an effective choice for safeguarding the sensitive data in the application and ensuring it is not exploited by attackers attempting data exfiltration."},{"num":250,"text":"A company wants to improve the availability of its application with a solution that requires minimal effort in the event a server needs to be replaced or added. Which of the following would be the best solution to meet these objectives?","options":[["A","Load balancing"],["B","Fault tolerance"],["C","Proxy servers"],["D","Replication"]],"correct":"A","explanation":"Load balancing is the best solution for improving the availability of an application with minimal effort in the event that a server needs to be replaced or added. A load balancer distributes incoming traffic across multiple servers, ensuring that the application remains available even if one or more servers experience issues. This approach allows the system to scale and remain highly available without requiring significant manual intervention when adding or replacing servers."},{"num":251,"text":"A company is performing a risk assessment on new software the company plans to use. Which of the following should the company assess during this process?","options":[["A","Software vulnerabilities"],["B","Cost-benefit analysis"],["C","Ongoing monitoring strategies"],["D","Network infrastructure compatibility"]],"correct":"A","explanation":"When performing a risk assessment on new software, the company needs to evaluate the potential vulnerabilities within the software. Identifying software vulnerabilities helps assess the potential security risks, such as possible exploits or weaknesses that could be exploited by attackers. This is a critical part of the risk assessment process to ensure that the software does not introduce security threats to the company's environment."},{"num":252,"text":"A malicious actor is trying to access sensitive financial information from a company's database by intercepting and reusing log-in credentials. Which of the following attacks is the malicious actor attempting?","options":[["A","SQL injection"],["B","On-path"],["C","Brute-force"],["D","Password spraying"]],"correct":"B","explanation":"An \"on-path\" attack, previously known as a man-in-the-middle (MITM) attack, occurs when a malicious actor intercepts communication between two parties (such as a user and a server). In this scenario, the attacker is trying to access sensitive financial information by intercepting and reusing login credentials. The malicious actor can capture the credentials and then use them to gain unauthorized access to the system or data."},{"num":253,"text":"A new employee accessed an unauthorized website. An investigation found that the employee violated the company's rules. Which of the following did the employee violate?","options":[["A","MOU"],["B","AUP"],["C","NDA"],["D","MOA"]],"correct":"B","explanation":"An Acceptable Use Policy (AUP) is a set of rules that define what is acceptable behavior regarding the use of company resources, including the internet. If the employee accessed an unauthorized website, this action would likely violate the company's AUP, which outlines the proper and prohibited uses of the company's network, devices, and other resources."},{"num":254,"text":"A systems administrator is reviewing the VPN logs and notices that during non-working hours a user is accessing the company file server and information is being transferred to a suspicious IP address. Which of the following threats is most likely occurring?","options":[["A","Typosquatting"],["B","Root or trust"],["C","Data exfiltration"],["D","Blackmail"]],"correct":"C","explanation":"Data exfiltration refers to the unauthorized transfer of sensitive data from a company's systems to an external location, often by a malicious actor. In this case, the VPN logs indicate that a user is accessing the company file server and transferring information to a suspicious IP address during non-working hours. This behavior strongly suggests that sensitive data is being stolen or transferred without authorization, which is the essence of data exfiltration."},{"num":256,"text":"A company discovers suspicious transactions that were entered into the company's database and attached to a user account that was created as a trap for malicious activity. Which of the following is the user account an example of?","options":[["A","Honeytoken"],["B","Honeynet"],["C","Honeypot"],["D","Honeyfile"]],"correct":"A","explanation":"A honeytoken is a piece of data or a user account intentionally created to act as a trap for malicious activity. It is designed to attract and detect unauthorized access or suspicious transactions, as in this scenario where suspicious transactions were linked to a user account set up as a trap. When an attacker interacts with the honeytoken, it can alert administrators to potential malicious activity."},{"num":257,"text":"A network engineer is increasing the overall security of network devices and needs to harden the devices. Which of the following will best accomplish this task?","options":[["A","Configuring centralized logging"],["B","Generating local administrator accounts"],["C","Replacing Telnet with SSH"],["D","Enabling HTTP administration"]],"correct":"C","explanation":"Replacing Telnet with SSH (Secure Shell) is one of the best practices for hardening network devices. Telnet sends data, including passwords, in plaintext, making it vulnerable to interception. SSH, on the other hand, encrypts the communication between devices, providing a more secure way to manage network devices remotely."},{"num":258,"text":"A company's accounting department receives an urgent payment message from the company's bank domain with instructions to wire transfer funds. The sender requests that the transfer be completed as soon as possible. Which of the following attacks is described?","options":[["A","Business email compromise"],["B","Vishing"],["C","Spear phishing"],["D","Impersonation"]],"correct":"A","explanation":"Business email compromise (BEC) is a type of attack in which a hacker impersonates an executive, business partner, or trusted entity within the company (often via email) to trick employees into performing unauthorized financial transactions, such as wire transfers. In this case, the attacker uses a fraudulent message from what appears to be the company's bank, urgently requesting a wire transfer, which is a hallmark of a BEC attack."},{"num":259,"text":"A company filed a complaint with its IT service provider after the company discovered the service provider's external audit team had access to some of the company's confidential information. Which of the following is the most likely reason the company filed the complaint?","options":[["A","The MOU had basic clauses from a template."],["B","A SOW had not been agreed to by the client."],["C","A WO had not been mutually approved."],["D","A required NDA had not been signed."]],"correct":"D","explanation":"A Non-Disclosure Agreement (NDA) is a legally binding contract that ensures confidential information shared between two parties is not disclosed to unauthorized third parties. In this case, the company likely filed a complaint because the external audit team, which was part of the service provider, had access to the company's confidential information without the proper NDA in place, potentially violating confidentiality agreements."},{"num":260,"text":"Which of the following aspects of the data management life cycle is most directly impacted by local and international regulations?","options":[["A","Destruction"],["B","Certification"],["C","Retention"],["D","Sanitization"]],"correct":"C","explanation":"Data retention refers to the period of time that data must be kept by an organization. Local and international regulations (such as GDPR, HIPAA, or other data protection laws) often define how long specific types of data must be retained for legal, regulatory, or business purposes. These regulations can directly impact how long data should be stored and when it must be deleted or anonymized."},{"num":261,"text":"An analyst is reviewing job postings to ensure sensitive company information is not being shared with the general public. Which of the following is the analyst most likely looking for?","options":[["A","Office addresses"],["B","Software versions"],["C","List of board members"],["D","Government identification numbers"]],"correct":"B","explanation":"When reviewing job postings, an analyst would be most concerned with software versions being shared, as this can potentially expose vulnerabilities in the company's systems. If the version of software being used by the company is disclosed, attackers could target known vulnerabilities in those specific versions. Therefore, job postings should not contain such sensitive details."},{"num":262,"text":"An engineer has ensured that the switches are using the latest OS, the servers have the latest patches, and the endpoints' definitions are up to date. Which of the following will these actions most effectively prevent?","options":[["A","Zero-day attacks"],["B","Insider threats"],["C","End-of-life support"],["D","Known exploits"]],"correct":"D","explanation":"By ensuring that switches are using the latest OS, servers have the latest patches, and endpoints' definitions are up to date, the engineer is most effectively protecting against known exploits. Exploits are typically vulnerabilities in software or systems that attackers use to gain unauthorized access or control. Patching systems and updating definitions helps close these known vulnerabilities, making it more difficult for attackers to exploit them."},{"num":263,"text":"Which of the following is most likely a security concern when installing and using low-cost IoT devices in infrastructure environments?","options":[["A","Country of origin"],["B","Device responsiveness"],["C","Ease of deployment"],["D","Storage of data"]],"correct":"D","explanation":"Storage of data is a significant security concern when installing and using low-cost IoT (Internet of Things) devices in infrastructure environments. Many low-cost IoT devices may not have robust security measures in place to protect the data they collect or transmit. This data could be sensitive, such as operational metrics or user data, and if not properly secured, it could be vulnerable to theft, unauthorized access, or misuse."},{"num":264,"text":"A company captures log-in details and reviews them each week to identify conditions such as excessive log-in attempts and frequent lockouts. Which of the following should a security analyst recommend to improve security compliance monitoring?","options":[["A","Including the date and person who reviewed the information in a report"],["B","Adding automated alerting when anomalies occur"],["C","Requiring a statement each week that no exceptions were noted"],["D","Masking the username in a report to protect privacy"]],"correct":"B","explanation":"Automated alerting when anomalies occur is a crucial recommendation for improving security compliance monitoring. This approach ensures that suspicious activities, such as excessive login attempts and frequent lockouts, are immediately detected and flagged for further investigation, reducing the risk of undetected security threats. Automated alerts improve response times and reduce the need for manual monitoring, enhancing overall security posture."},{"num":265,"text":"A security team is in the process of hardening the network against externally crafted malicious packets. Which of the following is the most secure method to protect the internal network?","options":[["A","Anti-malware solutions"],["B","Host-based firewalls"],["C","Intrusion prevention systems"],["D","Network access control"],["E","Network allow list"]],"correct":"C","explanation":"An Intrusion Prevention System (IPS) is the most secure method for protecting the internal network against externally crafted malicious packets. IPS can monitor network traffic in real-time, detect, and block malicious packets or suspicious activity, which is critical for defending against external threats. An IPS actively analyzes traffic and can take action (such as blocking traffic or alerting administrators) to prevent attacks, making it highly effective in hardening the network against malicious packets."},{"num":266,"text":"Which of the following is the best way to prevent an unauthorized user from plugging a laptop into an employee's phone network port and then using tools to scan for database servers?","options":[["A","MAC filtering"],["B","Segmentation"],["C","Certification"],["D","Isolation"]],"correct":"B","explanation":"Segmentation is the best way to prevent unauthorized users from accessing sensitive parts of the network. By segmenting the network into different zones, such as isolating employee phone network ports from areas containing critical resources (like database servers), you can ensure that unauthorized devices plugged into less secure network segments cannot scan or access more secure areas. This method helps limit the scope of potential attacks and ensures that devices can only communicate with the portions of the network they are authorized to access."},{"num":267,"text":"Which of the following should a systems administrator use to decrease the company's hardware attack surface?","options":[["A","Replication"],["B","Isolation"],["C","Centralization"],["D","Virtualization"]],"correct":"B","explanation":"Isolation is the most effective method to decrease a company's hardware attack surface. By isolating critical systems or components from less secure parts of the network, an organization can prevent attackers from gaining easy access to sensitive areas. For example, using network segmentation or isolated environments for different tasks can limit the exposure of hardware resources to external threats."},{"num":268,"text":"A company wants to add an MFA solution for all employees who access the corporate network remotely. Log-in requirements include something you know, are, and have. The company wants a solution that does not require purchasing third-party applications or specialized hardware. Which of the following MFA solutions would best meet the company's requirements?","options":[["A","Smart card with PIN and password"],["B","Security questions and a one-time passcode sent via email"],["C","Voice and fingerprint verification with an SMS one-time passcode"],["D","Mobile application-generated, one-time passcode with facial recognition"]],"correct":"B","explanation":"The company requires a multi-factor authentication (MFA) solution that includes \"something you know, are, and have\" without purchasing third-party applications or specialized hardware. Option B meets this requirement, as it incorporates: Something you know: Security questions (e.g., mother's maiden name, pet\u2019s name). Something you are: Biometric verification could be used as a secondary factor, but this option focuses more on the knowledge factor. Something you have: A one-time passcode (OTP) sent via email, which users can access on their devices. This solution does not require additional hardware or third-party applications and meets the criteria for a three-factor authentication solution."},{"num":269,"text":"A company is using a legacy FTP server to transfer financial data to a third party. The legacy system does not support SFTP, so a compensating control is needed to protect the sensitive, financial data in transit. Which of the following would be the most appropriate for the company to use?","options":[["A","Telnet connection"],["B","SSH tunneling"],["C","Patch installation"],["D","Full disk encryption"]],"correct":"B","explanation":"Since the legacy FTP server does not support SFTP (which would provide secure file transfer), SSH tunneling is a compensating control that can help protect sensitive financial data in transit. SSH tunneling involves creating a secure, encrypted tunnel between the FTP server and the third party, ensuring that the data transferred through FTP is encrypted and protected from eavesdropping or tampering."},{"num":270,"text":"A security manager wants to reduce the number of steps required to identify and contain basic threats. Which of the following will help achieve this goal?","options":[["A","SOAR"],["B","SIEM"],["C","DMARC"],["D","NIDS"]],"correct":"A","explanation":"SOAR (Security Orchestration, Automation, and Response) is designed to automate and streamline security operations, including threat identification and containment. SOAR platforms integrate with existing security tools to automate repetitive tasks, facilitate faster decision-making, and reduce the number of manual steps required to respond to basic threats. This helps improve response times and operational efficiency by orchestrating workflows and automating incident handling."},{"num":271,"text":"The Chief Information Officer (CIO) asked a vendor to provide documentation detailing the specific objectives within the compliance framework that the vendor's services meet. The vendor provided a report and a signed letter stating that the services meet 17 of the 21 objectives. Which of the following did the vendor provide to the CIO?","options":[["A","Penetration test results"],["B","Self-assessment findings"],["C","Attestation of compliance"],["D","Third-party audit report"]],"correct":"C","explanation":"An attestation of compliance is a statement or document, often signed by a third party or the vendor themselves, confirming that specific objectives within a compliance framework are being met. In this case, the vendor provided a report and a signed letter stating that their services meet 17 of the 21 objectives, which aligns with an attestation of compliance. This document typically summarizes the vendor's compliance status and is used to assure customers that the vendor adheres to certain standards or regulations."},{"num":272,"text":"Which of the following describes the most effective way to address OS vulnerabilities after they are identified?","options":[["A","Endpoint protection"],["B","Removal of unnecessary software"],["C","Configuration enforcement"],["D","Patching"]],"correct":"D","explanation":"Patching is the most effective way to address operating system vulnerabilities once they are identified. Patches are updates released by software vendors to fix known vulnerabilities, including security holes, bugs, or other issues that could be exploited by attackers. Applying patches promptly ensures that vulnerabilities are mitigated, reducing the risk of an attack."},{"num":273,"text":"The management team reports that employees are missing features on company-provided tablets, which is causing productivity issues. The management team directs the IT team to resolve the issue within 48 hours. Which of the following would be the best solution for the IT team to leverage in this scenario?","options":[["A","EDR"],["B","COPE"],["C","MDM"],["D","FDE"]],"correct":"C","explanation":"MDM (Mobile Device Management) is the best solution in this scenario. MDM allows IT teams to manage, configure, and secure mobile devices remotely. It can be used to ensure that company-provided tablets are properly configured, with all necessary features and updates, and to resolve issues such as missing features or software inconsistencies. Additionally, MDM can help enforce company policies, deploy apps, and track device compliance, making it an efficient way to address the problem within the 48-hour time frame."},{"num":274,"text":"A company is implementing a policy to allow employees to use their personal equipment for work. However, the company wants to ensure that only company-approved applications can be installed. Which of the following addresses this concern?","options":[["A","MDM"],["B","Containerization"],["C","DLP"],["D","FIM"]],"correct":"A","explanation":"MDM (Mobile Device Management) is the most appropriate solution for this scenario. MDM allows companies to manage and secure mobile devices, including personal devices used for work (BYOD - Bring Your Own Device). With MDM, the company can enforce policies such as restricting the installation of unauthorized applications and ensuring that only company-approved applications are installed on the devices. MDM also allows remote management, configuration, and monitoring of devices to ensure compliance with company policies."},{"num":275,"text":"An alert references attacks associated with a zero-day exploit. An analyst places a bastion host in the network to reduce the risk of the exploit. Which of the following types of controls is the analyst implementing?","options":[["A","Compensating"],["B","Detective"],["C","Operational"],["D","Physical"]],"correct":"A","explanation":"A compensating control is a security measure implemented to mitigate risks when the primary control (e.g., patching the vulnerability) is not immediately feasible. In this case, placing a bastion host in the network to reduce the risk of a zero-day exploit is a compensating control. It provides an additional layer of security, helping to protect the network from exploitation until the vulnerability can be properly addressed (e.g., through a patch or fix)."},{"num":276,"text":"A penetration test has demonstrated that domain administrator accounts were vulnerable to pass-the-hash attacks. Which of the following would have been the best strategy to prevent the threat actor from using domain administrator accounts?","options":[["A","Audit each domain administrator account weekly for password compliance."],["B","Implement a privileged access management solution."],["C","Create IDS policies to monitor domain controller access."],["D","Use Group Policy to enforce password expiration."]],"correct":"B","explanation":"A privileged access management (PAM) solution is the best strategy to prevent the threat actor from using domain administrator accounts in a pass-the-hash attack. PAM solutions are designed to secure, control, and monitor the access to critical accounts (like domain administrator accounts) by enforcing least privilege access, ensuring strong authentication methods, and reducing the exposure of credentials. These solutions often include features such as vaulting and rotating privileged credentials, which mitigate the risk of pass-the-hash attacks."},{"num":277,"text":"Which of the following is an example of memory injection?","options":[["A","Two processes access the same variable, allowing one to cause a privilege escalation."],["B","A process receives an unexpected amount of data, which causes malicious code to be executed."],["C","Malicious code is copied to the allocated space of an already running process."],["D","An executable is overwritten on the disk, and malicious code runs the next time it is executed."]],"correct":"C","explanation":"Memory injection is a type of attack where malicious code is injected into the memory space of an already running process. This allows the attacker to control or manipulate the process's behavior by executing the injected code. This technique is commonly used in exploits such as code injection attacks, where the attacker injects malicious code into a process's memory, causing it to execute and perform malicious actions."},{"num":278,"text":"A security administrator is implementing encryption on all hard drives in an organization. Which of the following security concepts is the administrator applying?","options":[["A","Integrity"],["B","Authentication"],["C","Zero Trust"],["D","Confidentiality"]],"correct":"D","explanation":"When the security administrator implements encryption on all hard drives, the primary goal is to protect the confidentiality of the data. Encryption ensures that only authorized users can access the data, as it is transformed into an unreadable format without the proper decryption key. This protects sensitive information from unauthorized access, even if the physical hard drive is lost or stolen."},{"num":279,"text":"An administrator has configured a quarantine subnet for all guest devices that connect to the network. Which of the following would be best for the security team to perform before allowing access to corporate resources?","options":[["A","Device fingerprinting"],["B","Compliance attestation"],["C","Penetration test"],["D","Application vulnerability test"]],"correct":"B","explanation":"Before allowing guest devices to access corporate resources, the security team should perform compliance attestation. This involves ensuring that the guest devices meet specific security and configuration requirements, such as up-to-date antivirus software, the latest security patches, and proper configurations. Compliance attestation helps verify that the devices are safe to connect to the corporate network and reduces the risk of introducing vulnerabilities."},{"num":280,"text":"A customer has a contract with a CSP and wants to identify which controls should be implemented in the IaaS enclave. Which of the following is most likely to contain this information?","options":[["A","Statement of work"],["B","Responsibility matrix"],["C","Service-level agreement"],["D","Master service agreement"]],"correct":"B","explanation":"A responsibility matrix (also known as a RACI matrix) is the most likely document to contain information about which security controls should be implemented in the IaaS (Infrastructure as a Service) enclave. It outlines the specific responsibilities of the customer and the cloud service provider (CSP) regarding security and compliance, helping to clarify which party is responsible for various controls and tasks within the environment."},{"num":281,"text":"A Chief Information Security Officer is developing procedures to guide detective and corrective activities associated with common threats, including phishing, social engineering, and business email compromise. Which of the following documents would be most relevant to revise as part of this process?","options":[["A","SDLC"],["B","IRP"],["C","BCP"],["D","AUP"]],"correct":"B","explanation":"An Incident Response Plan (IRP) is the most relevant document to revise when developing procedures for detective and corrective activities related to common threats such as phishing, social engineering, and business email compromise. The IRP outlines the steps to be taken when a security incident occurs, including detection, containment, eradication, and recovery. It ensures that the organization is prepared to respond to and mitigate the effects of these types of threats."},{"num":282,"text":"Which of the following testing techniques uses both defensive and offensive testing methodologies with developers to securely build key applications and software?","options":[["A","Blue"],["B","Yellow"],["C","Red"],["D","Green"]],"correct":"B","explanation":"Yellow team testing is a security testing technique that combines both defensive and offensive methodologies with developers to ensure secure coding practices and the identification of vulnerabilities early in the development process. This collaborative approach helps developers understand both how to defend against attacks and how attackers might exploit weaknesses, leading to more secure applications."},{"num":283,"text":"An administrator wants to automate an account permissions update for a large number of accounts. Which of the following would best accomplish this task?","options":[["A","Security groups"],["B","Federation"],["C","User provisioning"],["D","Vertical scaling"]],"correct":"A","explanation":"Security groups are the best solution for automating account permission updates for a large number of accounts. By organizing users into security groups based on roles, departments, or other criteria, an administrator can apply permissions to the entire group rather than individually modifying each user's account. This is efficient and scalable, especially in environments with many users. When an account is added to or removed from a group, its permissions are automatically updated according to the group's settings."},{"num":284,"text":"Which of the following is the fastest and most cost-effective way to confirm a third-party supplier's compliance with security obligations?","options":[["A","Attestation report"],["B","Third-party audit"],["C","Vulnerability assessment"],["D","Penetration testing"]],"correct":"A","explanation":"An attestation report is the fastest and most cost-effective way to confirm a third-party supplier's compliance with security obligations. An attestation report is a document provided by the third party (or a third-party auditor) that confirms their adherence to specific security frameworks, policies, or regulatory standards. This report is often based on industry standards such as SOC 2, ISO 27001, or similar certifications, and provides assurance without the need for an in-depth audit or testing process."},{"num":285,"text":"Various company stakeholders meet to discuss roles and responsibilities in the event of a security breach that would affect offshore offices. Which of the following is this an example of?","options":[["A","Tabletop exercise"],["B","Penetration test"],["C","Geographic dispersion"],["D","Incident response"]],"correct":"A","explanation":"A tabletop exercise is a type of simulation where stakeholders discuss their roles, responsibilities, and procedures in response to a hypothetical situation, such as a security breach. The goal of this exercise is to test how well the team coordinates and responds to the incident without actually executing the actions in a real environment. It helps ensure that everyone understands their responsibilities and can react effectively when an actual breach occurs."},{"num":286,"text":"Which of the following is an example of a data protection strategy that uses tokenization?","options":[["A","Encrypting databases containing sensitive data"],["B","Replacing sensitive data with surrogate values"],["C","Removing sensitive data from production systems"],["D","Hashing sensitive data in critical systems"]],"correct":"B","explanation":"Tokenization is a data protection strategy that involves replacing sensitive data with surrogate values, or \"tokens,\" which have no meaningful value outside the specific context in which they are used. These tokens are used in place of the original sensitive data to protect it, and the actual sensitive data is stored securely in a separate system or vault. Tokenization is commonly used to protect payment card information, personal identification details, and other sensitive data."},{"num":287,"text":"Which of the following is a type of vulnerability that refers to the unauthorized installation of applications on a device through means other than the official application store?","options":[["A","Cross-site scripting"],["B","Buffer overflow"],["C","Jailbreaking"],["D","Side loading"]],"correct":"D","explanation":"Side loading refers to the process of installing applications on a device through means other than the official application store (such as downloading apps from third-party sources). This can introduce security risks because apps from unofficial sources may not undergo the same vetting process as those from the official app store, potentially allowing malicious software to be installed."},{"num":288,"text":"Which of the following types of identification methods can be performed on a deployed application during runtime?","options":[["A","Dynamic analysis"],["B","Code review"],["C","Package monitoring"],["D","Bug bounty"]],"correct":"A","explanation":"Dynamic analysis involves evaluating an application while it is running (during runtime) to identify potential vulnerabilities, performance issues, or other security risks. This type of analysis allows security professionals to observe the application's behavior in real-world conditions and to identify issues that may not be apparent from static code inspection alone."},{"num":289,"text":"Which of the following cryptographic solutions is used to hide the fact that communication is occurring?","options":[["A","Steganography"],["B","Data masking"],["C","Tokenization"],["D","Private key"]],"correct":"A","explanation":"Steganography is the cryptographic technique used to hide the fact that communication is occurring. It involves embedding secret data within other non-suspicious data, such as images, audio, or video files, so that the presence of the hidden message is not detectable. Unlike encryption, which transforms data into unreadable formats, steganography hides the very existence of the communication."},{"num":290,"text":"Which of the following steps should be taken before mitigating a vulnerability in a production server?","options":[["A","Escalate the issue to the SDLC team."],["B","Use the IR plan to evaluate the changes."],["C","Perform a risk assessment to classify the vulnerability."],["D","Refer to the change management policy."]],"correct":"D","explanation":"Before mitigating a vulnerability in a production server, it is important to refer to the change management policy. This policy outlines the necessary procedures for making changes to production systems, ensuring that changes are thoroughly reviewed, tested, and approved. Following this policy helps mitigate the risk of introducing additional issues or downtime when applying patches or updates to the server."},{"num":291,"text":"A security engineer needs to quickly identify a signature from a known malicious file. Which of the following analysis methods would the security engineer most likely use?","options":[["A","Static"],["B","Sandbox"],["C","Network traffic"],["D","Package monitoring"]],"correct":"A","explanation":"Static analysis is the method most likely to be used by a security engineer to quickly identify a signature from a known malicious file. In static analysis, the file is examined without being executed, typically by analyzing its binary or code structure. This allows for the identification of known malicious patterns, signatures, or characteristics within the file, enabling a quick assessment of whether the file is malicious."},{"num":292,"text":"Which of the following should a company use to provide proof of external network security testing?","options":[["A","Business impact analysis"],["B","Supply chain analysis"],["C","Vulnerability assessment"],["D","Third-party attestation"]],"correct":"D","explanation":"A third-party attestation is the most appropriate way to provide proof of external network security testing. This attestation is typically performed by an independent, external party (e.g., an audit firm or security vendor) that assesses and verifies the security measures of an organization's network. The attestation provides official confirmation that external security testing, such as vulnerability assessments or penetration tests, has been conducted and that the organization meets the required security standards."},{"num":293,"text":"A security administrator is addressing an issue with a legacy system that communicates data using an unencrypted protocol to transfer sensitive data to a third party. No software updates that use an encrypted protocol are available, so a compensating control is needed. Which of the following are the most appropriate for the administrator to suggest? (Choose two.)","options":[["A","Tokenization"],["B","Cryptographic downgrade"],["C","SSH tunneling"],["D","Segmentation"],["E","Patch installation"],["F","Data masking"]],"correct":"AC","explanation":"Tokenization: Tokenization replaces sensitive data with surrogate values (tokens), which helps to protect the original data during transfer, especially when the original data cannot be encrypted directly due to limitations in the legacy system. Tokenization ensures that even if the data is intercepted, it is meaningless to the attacker. SSH tunneling: This is a compensating control that can secure an unencrypted protocol by encapsulating the data in an encrypted tunnel. By using SSH tunneling, the administrator can encrypt the communication between the legacy system and the third party, protecting the sensitive data from being transmitted in plaintext over the network."},{"num":294,"text":"Which of the following steps in the risk management process involves establishing the scope and potential risks involved with a project?","options":[["A","Risk assessment"],["B","Risk identification"],["C","Risk treatment"],["D","Risk monitoring and review"]],"correct":"B","explanation":"Risk identification is the step in the risk management process where the scope of the project is defined, and potential risks are identified. This step involves gathering information to understand the environment and context of the project, as well as the risks that could affect its success or security. It helps to outline what can go wrong and what risks need to be considered in subsequent stages of the risk management process."},{"num":295,"text":"A company's website is www.company.com. Attackers purchased the domain www.c0mpany.com. Which of the following types of attacks describes this example?","options":[["A","Typosquatting"],["B","Brand impersonation"],["C","On-path"],["D","Watering-hole"]],"correct":"A","explanation":"Typosquatting is a type of attack where attackers register a domain that is very similar to a legitimate one, often differing by only a small change, such as replacing a letter with a number or character. In this example, attackers purchased www.c0mpany.com, which is a slight variation of the legitimate domain www.company.com. Typosquatting relies on users making typographical errors when entering a web address, leading them to the malicious site instead of the legitimate one."},{"num":296,"text":"Which of the following allows a systems administrator to tune permissions for a file?","options":[["A","Patching"],["B","Access control list"],["C","Configuration enforcement"],["D","Least privilege"]],"correct":"B","explanation":"An Access Control List (ACL) allows a systems administrator to specify and fine-tune the permissions for a file or directory. It defines which users or groups have permission to access the resource and what level of access (e.g., read, write, execute) they have. ACLs provide a granular way to manage permissions and ensure that users can only access resources according to their roles or needs."},{"num":297,"text":"Which of the following would be the greatest concern for a company that is aware of the consequences of non-compliance with government regulations?","options":[["A","Right to be forgotten"],["B","Sanctions"],["C","External compliance reporting"],["D","Attestation"]],"correct":"B","explanation":"Sanctions would be the greatest concern for a company that is aware of the consequences of noncompliance with government regulations. Sanctions can include financial penalties, restrictions on business operations, or other legal consequences that can significantly impact the company's ability to operate and its financial stability. Companies that fail to comply with government regulations, especially those related to data protection, financial reporting, or industry-specific laws, can face severe sanctions from regulatory bodies."},{"num":298,"text":"Which of the following security concepts is accomplished when granting access after an individual has logged into a computer network?","options":[["A","Authorization"],["B","Identification"],["C","Non-repudiation"],["D","Authentication"]],"correct":"A","explanation":"Authorization occurs after an individual has successfully logged into a computer network and is granted access to specific resources or services based on their privileges or roles. It defines what the authenticated user is allowed to do on the network (e.g., access files, use certain applications, etc.)."},{"num":299,"text":"A growing organization, which hosts an externally accessible application, adds multiple virtual servers to improve application performance and decrease the resource usage on individual servers. Which of the following solutions is the organization most likely to employ to further increase performance and availability?","options":[["A","Load balancer"],["B","Jump server"],["C","Proxy server"],["D","SD-WAN"]],"correct":"A","explanation":"A load balancer is the most likely solution the organization would employ to further increase the performance and availability of their application. A load balancer distributes incoming network traffic across multiple servers, ensuring that no single server becomes overwhelmed with requests. This helps improve performance by optimizing resource utilization and increases availability by ensuring that if one server fails, others can continue to handle the traffic."},{"num":300,"text":"A systems administrator is concerned users are accessing emails through a duplicate site that is not run by the company. Which of the following is used in this scenario?","options":[["A","Impersonation"],["B","Replication"],["C","Phishing"],["D","Smishing"]],"correct":"C","explanation":"Phishing is the most likely scenario in which users are tricked into accessing emails through a duplicate site that is not run by the company. In a phishing attack, an attacker creates a fraudulent website that looks like the legitimate one (e.g., a fake email login page) to deceive users into entering their credentials, which are then stolen."},{"num":301,"text":"A security engineer at a large company needs to enhance IAM in order to ensure that employees can only access corporate systems during their shifts. Which of the following access controls should the security engineer implement?","options":[["A","Role-based"],["B","Time-of-day restrictions"],["C","Least privilege"],["D","Biometric authentication"]],"correct":"B","explanation":"Time-of-day restrictions are the most appropriate access control for ensuring that employees can only access corporate systems during their shifts. By setting specific time windows during which access is allowed (e.g., only during working hours or assigned shifts), the security engineer can limit when users are able to log in and access corporate resources."},{"num":302,"text":"A company wants to ensure employees are allowed to copy files from a virtual desktop during the workday but are restricted during non-working hours. Which of the following security measures should the company set up?","options":[["A","Digital rights management"],["B","Role-based access control"],["C","Time-based access control"],["D","Network access control"]],"correct":"C","explanation":"Time-based access control is the most suitable measure for restricting employees from copying files during non-working hours. It allows access to resources based on the time of day, ensuring that employees can copy files during the workday, but are restricted from doing so outside of those hours. This ensures that the company's policy is enforced based on time-specific criteria."},{"num":303,"text":"Employees sign an agreement that restricts specific activities when leaving the company. Violating the agreement can result in legal consequences. Which of the following agreements does this best describe?","options":[["A","SLA"],["B","BPA"],["C","NDA"],["D","MOA"]],"correct":"C","explanation":"An NDA (Non-Disclosure Agreement) is a legal document that restricts individuals from sharing proprietary or confidential information they have access to during their employment. Employees sign this agreement to prevent the disclosure of sensitive company information after leaving the organization. Violation of an NDA can result in legal consequences, including lawsuits."},{"num":304,"text":"A systems administrator just purchased multiple network devices. Which of the following should the systems administrator perform to prevent attackers from accessing the devices by using publicly available information?","options":[["A","Install endpoint protection."],["B","Disable ports/protocols."],["C","Change default passwords."],["D","Remove unnecessary software."]],"correct":"C","explanation":"Changing default passwords is a critical step in securing network devices. Default credentials are often publicly available and widely known by attackers, making devices vulnerable to unauthorized access. By replacing these defaults with strong, unique passwords, the systems administrator can significantly reduce the risk of compromise."},{"num":305,"text":"A CVE in a key back-end component of an application has been disclosed. The systems administrator is identifying all of the systems in the environment that are susceptible to this risk. Which of the following should the systems administrator perform?","options":[["A","Packet capture"],["B","Vulnerability scan"],["C","Metadata analysis"],["D","Automated reporting"]],"correct":"B","explanation":"A vulnerability scan is used to identify systems and components in an environment that are susceptible to known vulnerabilities, such as those disclosed through CVEs (Common Vulnerabilities and Exposures). This process involves scanning systems for software versions and configurations to determine if they match the affected criteria of the disclosed vulnerability. This allows the systems administrator to take corrective actions, such as patching or mitigating the vulnerability."},{"num":306,"text":"Which of the following activities uses OSINT?","options":[["A","Social engineering testing"],["B","Data analysis of logs"],["C","Collecting evidence of malicious activity"],["D","Producing IOC for malicious artifacts"]],"correct":"A","explanation":"OSINT (Open-Source Intelligence) refers to the collection and analysis of publicly available information from various sources, such as social media, websites, and public records. In social engineering testing, OSINT is used to gather information about a target, such as employee names, roles, and behaviors, which can then be exploited during the test to assess the organization's vulnerability to social engineering attacks."},{"num":307,"text":"Which of the following are the best security controls for controlling on-premises access? (Choose two.)","options":[["A","Swipe card"],["B","Picture ID"],["C","Phone authentication application"],["D","Biometric scanner"],["E","Camera"],["F","Memorable question"]],"correct":"AD","explanation":"Swipe Card: Swipe cards are a common physical security measure that allows controlled access to specific areas. They are assigned to authorized individuals and can be tracked or deactivated if lost or stolen. Biometric Scanner: Biometric scanners, such as fingerprint or iris scanners, provide robust security by verifying unique physical characteristics of a person. They are highly effective in preventing unauthorized access as biometric data is difficult to replicate."},{"num":308,"text":"A company is considering an expansion of access controls for an application that contractors and internal employees use to reduce costs. Which of the following risk elements should the implementation team understand before granting access to the application?","options":[["A","Threshold"],["B","Appetite"],["C","Avoidance"],["D","Register"]],"correct":"B","explanation":"Risk appetite refers to the level of risk an organization is willing to accept in pursuit of its objectives. When granting access to an application, especially to both contractors and internal employees, the implementation team needs to assess how much risk the organization is willing to tolerate regarding potential unauthorized access, data breaches, or misuse of the application. Understanding the company's risk appetite helps in designing access controls that align with its risk management strategy."},{"num":309,"text":"Which of the following is the act of proving to a customer that software developers are trained on secure coding?","options":[["A","Assurance"],["B","Contract"],["C","Due diligence"],["D","Attestation"]],"correct":"D","explanation":"Attestation is the act of formally declaring or providing evidence that certain conditions or requirements have been met. In this context, it involves proving to a customer that software developers are trained on secure coding practices. This can be achieved through documentation, certifications, or other official declarations demonstrating compliance with secure coding standards."},{"num":310,"text":"An administrator is creating a secure method for a contractor to access a test environment. Which of the following would provide the contractor with the best access to the test environment?","options":[["A","Application server"],["B","Jump server"],["C","RDP server"],["D","Proxy server"]],"correct":"B","explanation":"A jump server (also known as a jump box) is a secure system designed to serve as a controlled entry point for accessing servers and environments. It is commonly used to provide external contractors or administrators with access to a specific environment, such as a test environment, while minimizing the risk of unauthorized access to other parts of the network. Jump servers typically include additional security measures like multi-factor authentication and logging to enhance control and monitoring."},{"num":311,"text":"A security analyst notices unusual behavior on the network. The IDS on the network was not able to detect the activities. Which of the following should the security analyst use to help the IDS detect such attacks in the future?","options":[["A","Signatures"],["B","Trends"],["C","Honeypot"],["D","Reputation"]],"correct":"A","explanation":"Signatures are predefined patterns or rules used by an Intrusion Detection System (IDS) to identify known malicious activities or attacks. If the IDS was unable to detect unusual behavior, the security analyst can create or update signatures based on the characteristics of the observed activity. This ensures the IDS can recognize and flag similar activities in the future, improving its effectiveness in detecting such attacks."},{"num":312,"text":"To which of the following security categories does an EDR solution belong?","options":[["A","Physical"],["B","Operational"],["C","Managerial"],["D","Technical"]],"correct":"D","explanation":"An EDR (Endpoint Detection and Response) solution is a technical security control that focuses on monitoring, detecting, and responding to threats on endpoint devices such as desktops, laptops, and servers. It provides real-time visibility, threat detection, and automated responses to mitigate security incidents, making it a part of the technical security category."},{"num":313,"text":"A company relies on open-source software libraries to build the software used by its customers. Which of the following vulnerability types would be the most difficult to remediate due to the company\u2019s reliance on open-source libraries?","options":[["A","Buffer overflow"],["B","SQL injection"],["C","Cross-site scripting"],["D","Zero-day"]],"correct":"D","explanation":"A zero-day vulnerability is a security flaw that is unknown to the vendor or developer and has no available fix at the time of its discovery. When relying on open-source libraries, addressing zero-day vulnerabilities can be particularly challenging because the company depends on the open-source community or the library's maintainers to identify and patch the issue. The company often has limited control over the development and update process for these libraries, making remediation more difficult compared to other vulnerability types where known fixes or mitigations are available."},{"num":314,"text":"An organization has a new regulatory requirement to implement corrective controls on a financial system. Which of the following is the most likely reason for the new requirement?","options":[["A","To defend against insider threats altering banking details"],["B","To ensure that errors are not passed to other systems"],["C","To allow for business insurance to be purchased"],["D","To prevent unauthorized changes to financial data"]],"correct":"B","explanation":"Corrective controls are designed to identify and fix issues that arise in a system to prevent further propagation of errors. In a financial system, implementing corrective controls ensures that errors, such as data inaccuracies or processing mistakes, are identified and corrected before they can affect other interconnected systems. Regulatory requirements often mandate such controls to maintain data integrity and reliability across financial operations."},{"num":315,"text":"Which of the following is the stage in an investigating when forensic images are obtained?","options":[["A","Acquisition"],["B","Preservation"],["C","Reporting"],["D","E-discovery"]],"correct":"A","explanation":"The acquisition stage in an investigation involves obtaining forensic images of digital evidence. This process includes creating exact copies of data from storage devices (e.g., hard drives, USB drives) or systems while maintaining the integrity of the original evidence. These forensic images are then used for analysis in subsequent stages of the investigation, ensuring that the original evidence remains unaltered."},{"num":316,"text":"Which of the following describes the difference between encryption and hashing?","options":[["A","Encryption protects data in transit, while hashing protects data at rest."],["B","Encryption replaces cleartext with ciphertext, while hashing calculates a checksum."],["C","Encryption ensures data integrity, while hashing ensures data confidentiality."],["D","Encryption uses a public-key exchange, while hashing uses a private key."]],"correct":"B","explanation":"Encryption transforms cleartext into ciphertext using an algorithm and a key to protect the data's confidentiality. The ciphertext can be decrypted back into the original cleartext with the correct key. Hashing is a one-way process that generates a fixed-size hash value (checksum) from input data. Hashing is typically used to ensure data integrity by detecting changes in the data, as even a small alteration results in a completely different hash value."},{"num":317,"text":"A security report shows that during a two-week test period, 80% of employees unwittingly disclosed their SSO credentials when accessing an external website. The organization purposely created the website to simulate a cost-free password complexity test. Which of the following would best help reduce the number of visits to similar websites in the future?","options":[["A","Block all outbound traffic from the intranet."],["B","Introduce a campaign to recognize phishing attempts."],["C","Restrict internet access for the employees who disclosed credentials."],["D","Implement a deny list of websites."]],"correct":"B","explanation":"A phishing awareness campaign is the best way to address this issue by educating employees about recognizing and avoiding phishing attempts. The campaign can include training sessions, simulated phishing exercises, and guidelines for safely handling requests for sensitive information. By increasing awareness and understanding, employees will be less likely to fall for similar schemes in the future, significantly reducing the risk of credential disclosure."},{"num":318,"text":"A Chief Information Security Officer (CISO) has developed information security policies that relate to the software development methodology. Which of the following would the CISO most likely include in the organization\u2019s documentation?","options":[["A","Peer review requirements"],["B","Multifactor authentication"],["C","Branch protection tests"],["D","Secrets management configurations"]],"correct":"A","explanation":"Peer review requirements are often included in information security policies related to the software development methodology. Peer reviews help ensure that code is reviewed for quality, security vulnerabilities, and adherence to best practices before it is merged or deployed. This process reduces the likelihood of introducing security flaws into the software and aligns with secure development lifecycle practices."},{"num":319,"text":"An organization is developing a security program that conveys the responsibilities associated with the general operation of systems and software within the organization. Which of the following documents would most likely communicate these expectations?","options":[["A","Business continuity plan"],["B","Change management procedure"],["C","Acceptable use policy"],["D","Software development life cycle policy"]],"correct":"C","explanation":"An Acceptable Use Policy (AUP) outlines the responsibilities and expectations for employees and users regarding the use of systems, software, and other organizational resources. It specifies the appropriate and prohibited behaviors to ensure secure and proper operation of these systems. This policy communicates general operational responsibilities and helps enforce compliance with organizational security standards."},{"num":320,"text":"A security analyst created a fake account and saved the password in a non-readily accessible directory in a spreadsheet. An alert was also configured to notify the security team if the spreadsheet is opened. Which of the following best describes the deception method being deployed?","options":[["A","Honeypot"],["B","Honeyfile"],["C","Honeytoken"],["D","Honeynet"]],"correct":"B","explanation":"A honeyfile is a decoy file created to detect unauthorized access or suspicious activities. In this case, the security analyst set up a fake account and saved its password in a hidden spreadsheet, configuring an alert to trigger if the file is accessed. This approach aims to deceive potential attackers and monitor their behavior, making it a clear example of using a honeyfile."},{"num":321,"text":"Which of the following is the best way to provide secure, remote access for employees while minimizing the exposure of a company\u2019s internal network?","options":[["A","VPN"],["B","LDAP"],["C","FTP"],["D","RADIUS"]],"correct":"A","explanation":"A VPN (Virtual Private Network) provides secure, encrypted remote access to an organization's internal network. It ensures that data transmitted between remote employees and the internal network is protected from interception and minimizes the exposure of the internal network by controlling access through secure tunnels. VPNs are a widely used and effective solution for enabling secure remote work."},{"num":322,"text":"A company wants to track modifications to the code that is used to build new virtual servers. Which of the following will the company most likely deploy?","options":[["A","Change management ticketing system"],["B","Behavioral analyzer"],["C","Collaboration platform"],["D","Version control tool"]],"correct":"D","explanation":"A version control tool is specifically designed to track changes to code, configurations, and other files. It allows teams to monitor modifications, revert to previous versions if needed, and collaborate effectively while maintaining a history of changes. For tracking modifications to code used in building new virtual servers, tools like Git or Subversion would be the most appropriate choice."},{"num":323,"text":"Which of the following documents details how to accomplish a technical security task?","options":[["A","Standard"],["B","Policy"],["C","Guideline"],["D","Procedure"]],"correct":"D","explanation":"A procedure is a document that provides step-by-step instructions on how to accomplish a specific technical security task. It is detailed and actionable, ensuring consistency and clarity in task execution. Procedures are essential for tasks like configuring firewalls, applying patches, or implementing encryption."},{"num":324,"text":"While conducting a business continuity tabletop exercise, the security team becomes concerned by potential impact if a generator was to develop a fault during failover. Which of the following is the team most likely to consider in regard to risk management activities?","options":[["A","RPO"],["B","ARO"],["C","BIA"],["D","MTTR"]],"correct":"C","explanation":"A Business Impact Analysis (BIA) is used to identify and evaluate the potential effects of disruptions to critical business operations. During a business continuity exercise, concerns about the impact of a generator fault during failover would prompt the team to assess the associated risks and impacts on business functions, which are key components of a BIA. This helps in prioritizing recovery strategies and understanding the consequences of such failures."},{"num":325,"text":"Which of the following is prevented by proper data sanitization?","options":[["A","Hackers\u2019 ability to obtain data from used hard drives"],["B","Devices reaching end-of-life and losing support"],["C","Disclosure of sensitive data through incorrect classification"],["D","Incorrect inventory data leading to a laptop shortage"]],"correct":"A","explanation":"Proper data sanitization ensures that sensitive or confidential information is irreversibly removed from storage devices before disposal, reuse, or transfer. This process prevents hackers or unauthorized individuals from recovering data from used hard drives or other storage media, thereby mitigating the risk of data breaches."},{"num":326,"text":"A certificate authority needs to post information about expired certificates. Which of the following would accomplish this task?","options":[["A","TPM"],["B","CRL"],["C","PKI"],["D","CSR"]],"correct":"B","explanation":"A CRL (Certificate Revocation List) is a list published by a Certificate Authority (CA) that contains information about certificates that have been revoked or are no longer valid. This list helps systems verify the status of a certificate and ensures that expired or compromised certificates are not trusted."},{"num":327,"text":"Which of the following can best contribute to prioritizing patch applications?","options":[["A","CVSS"],["B","SCAP"],["C","OSINT"],["D","CVE"]],"correct":"A","explanation":"The Common Vulnerability Scoring System (CVSS) provides a standardized way to assess and prioritize the severity of vulnerabilities. By assigning a numerical score to each vulnerability based on factors like exploitability and impact, CVSS helps organizations determine the urgency of applying patches, enabling efficient risk management and prioritization of remediation efforts."},{"num":328,"text":"A systems administrator creates a script that validates OS version, patch levels, and installed applications when users log in. Which of the following examples best describes the purpose of this script?","options":[["A","Resource scaling"],["B","Policy enumeration"],["C","Baseline enforcement"],["D","Guard rails implementation"]],"correct":"C","explanation":"The script ensures that systems meet specific requirements such as the OS version, patch levels, and installed applications when users log in. This process is an example of baseline enforcement, where a predefined standard or configuration (baseline) is enforced to maintain system security, compliance, and stability."},{"num":329,"text":"A security analyst learns that an attack vector, which was used as a part of a recent incident, was a wellknown IoT device exploit. The analyst needs to review logs to identify the time of initial exploit. Which of the following logs should the analyst review first?","options":[["A","Endpoint"],["B","Application"],["C","Firewall"],["D","NAC"]],"correct":"C","explanation":"A firewall log is the most relevant log to review first when investigating the initial exploit of an IoT device. Firewalls monitor and log network traffic, including incoming and outgoing connections, which can reveal suspicious activity or unauthorized access attempts targeting the IoT device. By analyzing these logs, the security analyst can pinpoint the time and source of the initial exploit."},{"num":330,"text":"A company\u2019s gate access logs show multiple entries from an employee\u2019s ID badge within a two-minute period. Which of the following is this an example of?","options":[["A","RFID cloning"],["B","Side-channel attack"],["C","Shoulder surfing"],["D","Tailgating"]],"correct":"A","explanation":"RFID cloning occurs when an attacker duplicates the data from an RFID badge, allowing them to simulate multiple entries using the same badge ID. The multiple entries within a short period in the gate access logs indicate that the RFID badge data might have been copied and used illegitimately."},{"num":331,"text":"Which of the following most accurately describes the order in which a security engineer should implement secure baselines?","options":[["A","Deploy, maintain, establish"],["B","Establish, maintain, deploy"],["C","Establish, deploy, maintain"],["D","Deploy, establish, maintain"]],"correct":"C","explanation":"Establish: Create the secure baseline by defining the standard configurations, security settings, and policies required for systems and applications. Deploy: Apply the secure baseline to the systems and environments to ensure compliance with the defined standards. Maintain: Continuously monitor and update the baseline as needed to adapt to new threats, vulnerabilities, or changes in requirements."},{"num":332,"text":"A SOC analyst establishes a remote control session on an end user\u2019s machine and discovers the following in a file: gmail.com[ENT]my.name@gmail.com[ENT]NoOneCanGuessThis123! [ENT]Hello Susan, it was great to see you the other day! Let's plan a followup[BACKSPACE]follow-up meeting soon. Here is the link to register. [RTN][CTRL]c [CTRL]v [RTN]after [BACKSPACE]After you register give me a call on my cellphone. Which of the following actions should the SOC analyst perform first?","options":[["A","Advise the user to change passwords."],["B","Reimage the end user\u2019s machine."],["C","Check the policy on personal email at work."],["D","Check host firewall logs."]],"correct":"A","explanation":"The content in the file suggests that sensitive information, such as a Gmail password, may have been captured, likely by a keylogger or malicious software. Advising the user to change their passwords immediately is the first priority to secure their accounts, particularly since the password for a personal email account has already been compromised. Once this is done, further actions like investigating the cause of the breach and remediating the system (e.g., reimaging the machine or analyzing logs) can follow."},{"num":333,"text":"Which of the following is a reason environmental variables are a concern when reviewing potential system vulnerabilities?","options":[["A","The contents of environmental variables could affect the scope and impact of an exploited vulnerability."],["B","In-memory environmental variable values can be overwritten and used by attackers to insert malicious code."],["C","Environmental variables define cryptographic standards for the system and could create vulnerabilities if deprecated algorithms are used."],["D","Environmental variables will determine when updates are run and could mitigate the likelihood of vulnerability exploitation."]],"correct":"A","explanation":"Environmental variables store system-specific information such as paths, user-specific settings, or authentication tokens. If improperly managed or exposed, they can significantly increase the scope and impact of a vulnerability. For instance, leaked credentials or sensitive data stored in environmental variables can provide attackers with additional access or escalate their capabilities during an exploit. Therefore, careful management of these variables is crucial for system security."},{"num":334,"text":"A company evaluates several options that would allow employees to have remote access to the network. The security team wants to ensure the solution includes AAA to comply with internal security policies. Which of the following should the security team recommend?","options":[["A","IPSec with RADIUS"],["B","RDP connection with LDAPS"],["C","Web proxy for all remote traffic"],["D","Jump server with 802.1X"]],"correct":"A","explanation":"IPSec with RADIUS supports the AAA (Authentication, Authorization, and Accounting) framework, which is required to comply with internal security policies. IPSec provides secure communication over the network, and RADIUS handles AAA functionalities by authenticating users, authorizing access levels, and keeping logs for accounting purposes. This combination ensures robust security for remote access."},{"num":335,"text":"An administrator must replace an expired SSL certificate. Which of the following does the administrator need to create the new SSL certificate?","options":[["A","CSR"],["B","OCSP"],["C","Key"],["D","CRL"]],"correct":"A","explanation":"A CSR (Certificate Signing Request) is required to create a new SSL certificate. It is a file that contains the public key and identifying information (such as domain name and organization details) that the administrator submits to a Certificate Authority (CA). The CA uses this information to generate and issue a new SSL certificate."},{"num":336,"text":"A systems administrator receives a text message from an unknown number claiming to be the Chief Executive Officer of the company. The message states an emergency situation requires a password reset. Which of the following threat vectors is being used?","options":[["A","Typosquatting"],["B","Smishing"],["C","Pretexting"],["D","Impersonation"]],"correct":"B","explanation":"Smishing (SMS phishing) is a type of social engineering attack where attackers use text messages to deceive individuals into revealing sensitive information or performing actions like a password reset. In this case, the unknown sender pretending to be the CEO and requesting a password reset via text exemplifies smishing."},{"num":337,"text":"A Chief Information Security Officer (CISO) wants to: Prevent employees from downloading malicious content. Establish controls based on departments and users. Map internet access for business applications to specific service accounts. Restrict content based on categorization. Which of the following should the CSO implement?","options":[["A","Web application firewall"],["B","Secure DNS server"],["C","Jump server"],["D","Next-generation firewall"]],"correct":"D","explanation":"A Next-Generation Firewall (NGFW) offers advanced capabilities such as: Preventing malicious content downloads through deep packet inspection and intrusion prevention systems (IPS). Establishing controls based on departments and users by integrating with directory services like Active Directory for user-based policies. Mapping internet access to business applications through application-level control and service account integration. Restricting content based on categorization using URL filtering and content categorization features."},{"num":338,"text":"A company is aware of a given security risk related to a specific market segment. The business chooses not to accept responsibility and target their services to a different market segment. Which of the following describes this risk management strategy?","options":[["A","Exemption"],["B","Exception"],["C","Avoid"],["D","Transfer"]],"correct":"C","explanation":"The company's decision to change its target market to eliminate exposure to a specific security risk is an example of risk avoidance. This strategy involves modifying plans, processes, or business models to eliminate the potential for a particular risk to occur, rather than mitigating or transferring it. By targeting a different market segment, the company effectively avoids the identified risk."},{"num":339,"text":"A security analyst needs to improve the company\u2019s authentication policy following a password audit. Which of the following should be included in the policy? (Choose two.)","options":[["A","Length"],["B","Complexity"],["C","Least privilege"],["D","Something you have"],["E","Security keys"],["F","Biometrics"]],"correct":"AB","explanation":"Length: Longer passwords are more resistant to brute-force attacks. Requiring a minimum length (e.g., 1216 characters) significantly improves password security. Complexity: Ensuring passwords include a mix of uppercase letters, lowercase letters, numbers, and special characters makes them harder to guess or crack using dictionary attacks. Including both length and complexity in the authentication policy helps to enhance overall password strength and security."},{"num":340,"text":"Which of the following is an example of a treatment strategy for a continuous risk?","options":[["A","Email gateway to block phishing attempts"],["B","Background checks for new employees"],["C","Dual control requirements for wire transfers"],["D","Branch protection as part of the CI/CD pipeline"]],"correct":"A","explanation":"A continuous risk is an ongoing threat that requires ongoing mitigation and monitoring efforts. Phishing attempts are a continuous risk to organizations as attackers frequently target users via emails. An email gateway acts as a treatment strategy by actively filtering out malicious emails, thereby reducing the likelihood of successful phishing attacks. This proactive approach addresses the ongoing nature of the threat."},{"num":341,"text":"An organization wants to deploy software in a container environment to increase security. Which of the following would limit the organization's ability to achieve this goal?","options":[["A","Regulatory compliance"],["B","Patch availability"],["C","Kernel version"],["D","Monolithic code"]],"correct":"D","explanation":"A monolithic codebase can limit the deployment of software in a container environment because containers are designed to run lightweight, modular, and independent services. Monolithic applications are large, tightly coupled, and difficult to break into smaller components, which conflicts with the principles of containerization. This makes it harder to achieve the scalability, security, and isolation benefits of containers."},{"num":342,"text":"Prior to implementing a design change, the change must go through multiple steps to ensure that it does not cause any security issues. Which of the following is most likely to be one of those steps?","options":[["A","Board review"],["B","Service restart"],["C","Backout planning"],["D","Maintenance"]],"correct":"C","explanation":"Before implementing a design change, backout planning is crucial to ensure the organization can quickly revert to a stable state if the change causes issues, including security vulnerabilities. Backout planning involves identifying the steps and resources needed to undo the change safely and efficiently, minimizing disruptions and maintaining security."},{"num":343,"text":"The internal audit team determines a software application is no longer in scope for external reporting requirements. Which of the following will confirm that the application is no longer applicable?","options":[["A","Data inventory and retention"],["B","Right to be forgotten"],["C","Due care and due diligence"],["D","Acknowledgement and attestation"]],"correct":"A","explanation":"A data inventory and retention process helps confirm whether an application is still holding or processing data relevant to external reporting requirements. By reviewing the inventory and retention policies, the organization can determine if the application processes, stores, or retains data that falls under compliance or regulatory scope. If not, it can be formally excluded."},{"num":344,"text":"Which of the following are the first steps an analyst should perform when developing a heat map? (Choose two.)","options":[["A","Methodically walk around the office noting Wi-Fi signal strength."],["B","Log in to each access point and check the settings."],["C","Create or obtain a layout of the office."],["D","Measure cable lengths between access points."],["E","Review access logs to determine the most active devices."],["F","Remove possible impediments to radio transmissions."]],"correct":"AC","explanation":"Methodically walk around the office noting Wi-Fi signal strength: This is essential for identifying areas with weak or strong signals and understanding the coverage gaps or interference points, which are crucial for developing an accurate heat map. Create or obtain a layout of the office: A layout is necessary to map the signal strength data against the physical environment, enabling proper visualization of signal coverage and pinpointing issues. These two steps provide the foundation for creating a meaningful heat map to analyze wireless network performance."},{"num":345,"text":"Which of the following is used to improve security and overall functionality without losing critical application data?","options":[["A","Reformatting"],["B","Decommissioning"],["C","Patching"],["D","Encryption"]],"correct":"C","explanation":"Patching is used to improve both security and functionality by updating software to fix vulnerabilities, improve performance, or add features. This process ensures that critical application data is preserved while addressing issues that could compromise the application's security or functionality. Regular patching is a key part of maintaining a secure and efficient system."},{"num":346,"text":"An organization is preparing to export proprietary software to a customer. Which of the following would be the best way to prevent the loss of intellectual property?","options":[["A","Code signing"],["B","Obfuscation"],["C","Tokenization"],["D","Blockchain"]],"correct":"B","explanation":"Obfuscation is the process of making software code intentionally difficult to understand or reverseengineer. By obfuscating the proprietary software before exporting it, the organization can protect its intellectual property from being analyzed, copied, or exploited by unauthorized parties. This method is commonly used to safeguard the core logic and algorithms of the software."},{"num":347,"text":"Which of the following should be used to ensure a device is inaccessible to a network-connected resource?","options":[["A","Disablement of unused services"],["B","Web application firewall"],["C","Host isolation"],["D","Network-based IDS"]],"correct":"C","explanation":"Host isolation ensures that a device is inaccessible to network-connected resources by isolating it from the rest of the network. This can be achieved through techniques such as placing the device in a quarantine VLAN or blocking its communications entirely. It is a key security measure when dealing with potentially compromised or non-compliant devices."},{"num":348,"text":"In which of the following will unencrypted network traffic most likely be found?","options":[["A","SDN"],["B","IoT"],["C","VPN"],["D","SCADA"]],"correct":"D","explanation":"SCADA (Supervisory Control and Data Acquisition) systems often use legacy protocols that do not include encryption. As a result, unencrypted network traffic is more likely to be found in SCADA environments, making them vulnerable to interception and attacks unless additional security measures are implemented."},{"num":349,"text":"Which of the following is the best reason to perform a tabletop exercise?","options":[["A","To address audit findings"],["B","To collect remediation response times"],["C","To update the IRP"],["D","To calculate the ROI"]],"correct":"C","explanation":"The primary reason to perform a tabletop exercise is to test and validate the Incident Response Plan (IRP) in a simulated environment. This helps identify gaps, refine procedures, and ensure that the plan is up-to-date and effective in addressing current threats and scenarios. Regular tabletop exercises improve organizational preparedness for real-world incidents."},{"num":350,"text":"Which of the following is a use of CVSS?","options":[["A","To determine the cost associated with patching systems"],["B","To identify unused ports and services that should be closed"],["C","To analyze code for defects that could be exploited"],["D","To prioritize the remediation of vulnerabilities"]],"correct":"D","explanation":"The Common Vulnerability Scoring System (CVSS) is a standardized framework for assessing the severity of vulnerabilities. It assigns a numerical score that helps organizations determine the criticality of vulnerabilities and prioritize their remediation efforts based on the risk they pose. This ensures efficient use of resources to address the most severe issues first."},{"num":351,"text":"For an upcoming product launch, a company hires a marketing agency whose owner is a close relative of the Chief Executive Officer. Which of the following did the company violate?","options":[["A","Independent assessments"],["B","Supply chain analysis"],["C","Right-to-audit clause"],["D","Conflict of interest policy"]],"correct":"D","explanation":"A conflict of interest policy ensures that decisions are made in the best interests of the company and not influenced by personal relationships or benefits. Hiring a marketing agency owned by a close relative of the CEO without appropriate disclosures or procedures would violate such a policy, as it creates a potential bias or unfair advantage."},{"num":352,"text":"An organization designs an inbound firewall with a fail-open configuration while implementing a website. Which of the following would the organization consider to be the highest priority?","options":[["A","Confidentiality"],["B","Non-repudiation"],["C","Availability"],["D","Integrity"]],"correct":"C","explanation":"A fail-open configuration prioritizes availability, ensuring that services remain accessible even if the firewall encounters an issue. This approach minimizes downtime for critical resources, such as a website, but may temporarily compromise other aspects of security like confidentiality or integrity. This configuration is often chosen when maintaining access is of utmost importance."},{"num":353,"text":"An engineer needs to ensure that a script has not been modified before it is launched. Which of the following best provides this functionality?","options":[["A","Masking"],["B","Obfuscation"],["C","Hashing"],["D","Encryption"]],"correct":"C","explanation":"Hashing generates a unique fixed-size value (hash) based on the contents of a file or script. By comparing the current hash of the script with a previously calculated hash, the engineer can verify that the script has not been modified. Hashing ensures the integrity of the script without encrypting or altering it."},{"num":354,"text":"Which of the following is the most important element when defining effective security governance?","options":[["A","Discovering and documenting external considerations"],["B","Developing procedures for employee onboarding and offboarding"],["C","Assigning roles and responsibilities for owners, controllers, and custodians"],["D","Defining and monitoring change management procedures"]],"correct":"C","explanation":"Effective security governance requires clear assignment of roles and responsibilities to ensure accountability and proper management of security controls. Defining roles such as data owners (who make decisions), controllers (who implement decisions), and custodians (who handle day-to-day operations) is essential for ensuring security policies and procedures are effectively managed and enforced. This alignment is critical for a cohesive security framework."},{"num":355,"text":"A contractor is required to visually inspect the motherboards of all new servers that are purchased to determine whether the servers were tampered with. Which of the following risks is the contractor attempting to mitigate?","options":[["A","Embedded rootkit"],["B","Supply chain"],["C","Firmware failure"],["D","RFID keylogger"]],"correct":"B","explanation":"By visually inspecting the motherboards of new servers, the contractor is mitigating supply chain risks, which include the possibility of tampering or malicious components being introduced during manufacturing or transit. Such inspections help ensure the integrity of hardware and reduce the likelihood of compromised devices entering the organization."},{"num":356,"text":"Which of the following could potentially be introduced at the time of side loading?","options":[["A","User impersonation"],["B","Rootkit"],["C","On-path attack"],["D","Buffer overflow"]],"correct":"B","explanation":"Side loading involves installing software or applications from sources outside official or trusted repositories. This process can potentially introduce malicious software, such as a rootkit, which embeds itself deeply into a system to maintain privileged access and evade detection. Rootkits are often a significant threat when using unverified or non-trusted installation sources."},{"num":357,"text":"While a school district is performing state testing, a security analyst notices all internet services are unavailable. The analyst discovers that ARP poisoning is occurring on the network and then terminates access for the host. Which of the following is most likely responsible for this malicious activity?","options":[["A","Unskilled attacker"],["B","Shadow IT"],["C","Insider threat"],["D","Nation-state"]],"correct":"C","explanation":"The malicious activity involving ARP poisoning in a school district during state testing suggests deliberate and targeted action, likely from someone with internal access and knowledge of the network. This aligns with an insider threat, where an individual within the organization, such as a student or staff member, intentionally disrupts network operations. Insiders often have the access and opportunity required to carry out such attacks."},{"num":358,"text":"A user needs to complete training at https://comptiatraining.com. After manually entering the URL, the user sees that the accessed website is noticeably different from the standard company website. Which of the following is the most likely explanation for the difference?","options":[["A","Cross-site scripting"],["B","Pretexting"],["C","Typosquatting"],["D","Vishing"]],"correct":"C","explanation":"Typosquatting occurs when an attacker registers a domain name that is very similar to a legitimate website, often exploiting common typographical errors (e.g., \"comptiatrainning.com\" instead of \"comptiatraining.com\"). If a user manually enters an incorrect URL and lands on a fraudulent website, it is most likely a typosquatting attempt. This is commonly used for phishing or distributing malware."},{"num":359,"text":"A company has yearly engagements with a service provider. The general terms and conditions are the same for all engagements. The company wants to simplify the process and revisit the general terms every three years. Which of the following documents would provide the best way to set the general terms?","options":[["A","MSA"],["B","NDA"],["C","MOU"],["D","SLA"]],"correct":"A","explanation":"A Master Service Agreement (MSA) establishes the general terms and conditions governing the relationship between a company and a service provider. It is designed for long-term use, allowing individual engagements (e.g., statements of work) to reference the MSA instead of redefining the terms repeatedly. Revisiting the MSA every three years simplifies the process while maintaining flexibility for yearly engagements."},{"num":360,"text":"While updating the security awareness training, a security analyst wants to address issues created if vendors' email accounts are compromised. Which of the following recommendations should the security analyst include in the training?","options":[["A","Refrain from clicking on images included in emails from new vendors"],["B","Delete emails from unknown service provider partners."],["C","Require that invoices be sent as attachments"],["D","Be alert to unexpected requests from familiar email addresses"]],"correct":"D","explanation":"Compromised vendor email accounts can be used to send phishing emails or fraudulent requests that appear legitimate. Employees should be trained to recognize and scrutinize unexpected requests even when they come from familiar email addresses, as this is a common tactic in phishing and business email compromise (BEC) attacks. This recommendation directly addresses the risk posed by compromised vendor accounts."},{"num":361,"text":"A new corporate policy requires all staff to use multifactor authentication to access company resources. Which of the following can be utilized to set up this form of identity and access management? (Choose two.)","options":[["A","Authentication tokens"],["B","Least privilege"],["C","Biometrics"],["D","LDAP"],["E","Password vaulting"],["F","SAML"]],"correct":"AC","explanation":"Authentication tokens: Tokens, such as hardware or software-based one-time password (OTP) generators, are commonly used as one factor in multifactor authentication (MFA). They provide an additional layer of security beyond just a password. Biometrics: Biometric factors, such as fingerprint scans or facial recognition, are another common component of MFA, providing a \"something you are\" factor for identity verification. These factors, when combined with something the user knows (e.g., a password), fulfill the requirements for MFA by incorporating multiple layers of authentication."},{"num":362,"text":"A help desk employee receives a call from someone impersonating the Chief Executive Officer. The caller asks for assistance with resetting a password. Which of the following best describes this event?","options":[["A","Vishing"],["B","Hacktivism"],["C","Blackmail"],["D","Misinformation"]],"correct":"A","explanation":"Vishing (voice phishing) is a social engineering attack conducted over the phone. In this scenario, the attacker impersonates the CEO to manipulate the help desk employee into resetting a password, which is a classic example of a vishing attempt."},{"num":363,"text":"The number of tickets the help desk has been receiving has increased recently due to numerous falsepositive phishing reports. Which of the following would be best to help to reduce the false positives?","options":[["A","Performing more phishing simulation campaigns"],["B","Improving security awareness training"],["C","Hiring more help desk staff"],["D","Implementing an incident reporting web page"]],"correct":"B","explanation":"Improving security awareness training helps employees better understand and identify legitimate phishing attempts, reducing the number of false-positive reports. Enhanced training can teach staff to recognize key indicators of phishing emails and report only those that warrant investigation, decreasing the workload for the help desk."},{"num":364,"text":"A systems administrator needs to encrypt all data on employee laptops. Which of the following encryption levels should be implemented?","options":[["A","Volume"],["B","Partition"],["C","Full disk"],["D","File"]],"correct":"C","explanation":"Full disk encryption (FDE) encrypts the entire disk, including the operating system, applications, and user data. This ensures that all data on the laptop is encrypted, providing strong security against data theft or unauthorized access if the laptop is lost or stolen. It's the most comprehensive method for securing all information stored on the device."},{"num":365,"text":"Which of the following actions best addresses a vulnerability found on a company's web server?","options":[["A","Patching"],["B","Segmentation"],["C","Decommissioning"],["D","Monitoring"]],"correct":"A","explanation":"Patching involves applying updates or fixes to software to address known vulnerabilities. If a vulnerability is found on a web server, applying a patch is the most effective and direct way to resolve the issue and protect the system from exploitation. This action fixes the security holes in the software, making it secure against known threats."},{"num":366,"text":"A company is changing its mobile device policy. The company has the following requirements: Company-owned devices Ability to harden the devices Reduced security risk Compatibility with company resources Which of the following would best meet these requirements?","options":[["A","BYOD"],["B","CYOD"],["C","COPE"],["D","COBO"]],"correct":"C","explanation":"COPE (Corporate-Owned, Personally Enabled) allows the company to own the devices, ensuring they can be hardened and managed. This policy provides a balance between security and employee flexibility, as employees can use the devices for personal purposes within controlled limits. COPE reduces security risks by allowing the company to enforce security controls while still offering some level of personal use, making it compatible with company resources."},{"num":367,"text":"A company is concerned about employees unintentionally introducing malware into the network. The company identified fifty employees who clicked on a link embedded in an email sent by the internal IT department. Which of the following should the company implement to best improve its security posture?","options":[["A","Social engineering training"],["B","SPF configuration"],["C","Simulated phishing campaign"],["D","Insider threat awareness"]],"correct":"C","explanation":"A simulated phishing campaign involves sending fake phishing emails to employees to assess their susceptibility and raise awareness. By conducting such simulations, the company can identify vulnerable users, provide targeted training, and improve employees' ability to recognize phishing attempts. This approach directly addresses the risk of employees unintentionally introducing malware through malicious links in emails."},{"num":368,"text":"A penetration test identifies that an SMBv1 is enabled on multiple servers across an organization. The organization wants to remediate this vulnerability in the most efficient way possible. Which of the following should the organization use for this purpose?","options":[["A","GPO"],["B","ACL"],["C","SFTP"],["D","DLP"]],"correct":"A","explanation":"A Group Policy Object (GPO) can be used to efficiently disable SMBv1 across multiple servers within an organization. By configuring a GPO to disable the outdated and vulnerable SMBv1 protocol, the organization can ensure that the change is applied consistently across all affected systems. This is a centralized and efficient method for remediation, reducing the potential attack surface related to SMBv1."},{"num":369,"text":"Which of the following best protects sensitive data in transit across a geographically dispersed infrastructure?","options":[["A","Encryption"],["B","Masking"],["C","Tokenization"],["D","Obfuscation"]],"correct":"A","explanation":"Encryption ensures that sensitive data is protected while it is being transmitted across networks, especially over long distances or between geographically dispersed infrastructures. By encrypting data, it becomes unreadable to unauthorized parties, even if intercepted, ensuring confidentiality and integrity during transmission. Encryption is the most effective method for protecting data in transit."},{"num":370,"text":"As part of new compliance audit requirements, multiple servers need to be segmented on different networks and should be reachable only from authorized internal systems. Which of the following would meet the requirements?","options":[["A","Configure firewall rules to block external access to Internal resources."],["B","Set up a WAP to allow internal access from public networks."],["C","Implement a new IPSec tunnel from internal resources."],["D","Deploy an internal jump server to access resources."]],"correct":"A","explanation":"Configuring firewall rules to block external access ensures that only authorized internal systems can reach the segmented servers. This approach restricts access to the internal network and meets compliance requirements for segmentation and secure communication. By controlling access at the firewall level, you can enforce strict internal-only access policies, effectively isolating the servers from external threats."},{"num":371,"text":"Which of the following activities should be performed first to compile a list of vulnerabilities in an environment?","options":[["A","Automated scanning"],["B","Penetration testing"],["C","Threat hunting"],["D","Log aggregation"],["E","Adversarial emulation"]],"correct":"A","explanation":"Automated scanning is the first step in identifying vulnerabilities in an environment. Tools that perform automated vulnerability scanning scan systems and networks for known vulnerabilities, missing patches, misconfigurations, and other security weaknesses. This helps create an initial list of vulnerabilities that can then be prioritized and addressed, often serving as the foundation for further in-depth activities like penetration testing or threat hunting."},{"num":372,"text":"Which of the following can be used to mitigate attacks from high-risk regions?","options":[["A","Obfuscation"],["B","Data sovereignty"],["C","IP geolocation"],["D","Encryption"]],"correct":"C","explanation":"IP geolocation allows you to identify the geographical location of an IP address, enabling you to block or limit access from high-risk regions. By using IP geolocation, you can restrict or monitor traffic coming from certain geographic areas that are known to be sources of frequent cyberattacks. This is an effective way to mitigate risks associated with unwanted or malicious traffic from those regions."},{"num":373,"text":"An organization that handles sensitive information wants to protect the information by using a reversible technology. Which of the following best satisfies this requirement?","options":[["A","Hardware security module"],["B","Hashing algorithm"],["C","Tokenization"],["D","Steganography"]],"correct":"C","explanation":"Tokenization is a reversible technology that replaces sensitive information (such as credit card numbers or personal data) with a non-sensitive placeholder (a token). The original data can be retrieved from the token through a secure process, making tokenization ideal for situations where sensitive data needs to be protected but still be recoverable in a controlled manner. Unlike hashing, which is irreversible, tokenization provides a way to securely protect and retrieve sensitive information when necessary."},{"num":374,"text":"After a series of account compromises and credential misuse, a company hires a security manager to develop a security program. Which of the following steps should the security manager take first to increase security awareness?","options":[["A","Evaluate tools that identify risky behavior and distribute reports on the findings."],["B","Send quarterly newsletters that explain the importance of password management."],["C","Develop phishing campaigns and notify the management team of any successes."],["D","Update policies and handbooks to ensure all employees are informed of the new procedures."]],"correct":"D","explanation":"The first step in increasing security awareness should be to update policies and handbooks to ensure that all employees are aware of the new procedures and security expectations. Clear, documented policies provide a foundation for employees to understand their roles and responsibilities regarding security. Once the policies are in place, the company can implement additional strategies like training, newsletters, or phishing campaigns to reinforce these practices."},{"num":375,"text":"A program manager wants to ensure contract employees can only access the company's computers Monday through Friday from 9 a m. to 5 p.m. Which of the following would best enforce this access control?","options":[["A","Creating a GPO for all contract employees and setting time-of-day log-in restrictions"],["B","Creating a discretionary access policy and setting rule-based access for contract employees"],["C","Implementing an OAuth server and then setting least privilege for contract employees"],["D","Implementing SAML with federation to the contract employees\u2019 authentication server"]],"correct":"A","explanation":"Group Policy Objects (GPOs) in a Windows environment allow administrators to enforce access control policies, including restricting user logins based on time-of-day. By applying a GPO to contract employees and configuring logon hours from Monday through Friday, 9 a.m. to 5 p.m., the organization can ensure that these users cannot log in outside of the specified hours. This is the most effective way to enforce access control based on time."},{"num":376,"text":"A recent power outage halted operations at a company's only data center. Which of the following solutions would best prevent an event like this one in the future?","options":[["A","Platform diversity"],["B","Generator"],["C","Snapshots"],["D","Load balancing"]],"correct":"B","explanation":"A generator provides backup power in the event of a power outage, ensuring that critical systems remain operational. Since the company's only data center was halted due to the outage, installing a generator would help prevent downtime in the future by supplying power when the main power source fails. Other options, such as snapshots and load balancing, do not directly address power failure issues."},{"num":377,"text":"Which of the following analysis methods allows an organization to measure the exposure factor associated with organizational assets?","options":[["A","Heuristic"],["B","Quantitative"],["C","User-driven"],["D","Trend-based"]],"correct":"B","explanation":"Quantitative analysis is a risk assessment method that assigns numerical values to risk factors, including the Exposure Factor (EF) - which represents the percentage of an asset's value that would be lost if a specific threat were realized. This approach helps organizations calculate the Single Loss Expectancy (SLE) and Annualized Loss Expectancy (ALE), providing a data-driven method for risk management."},{"num":378,"text":"A security analyst notices an increase in port scans on the edge of the corporate network. Which of the following logs should the analyst check to obtain the attacker\u2019s source IP address?","options":[["A","OS security"],["B","Firewall"],["C","Application"],["D","Endpoint"]],"correct":"B","explanation":"A firewall log records inbound and outbound network traffic, including source and destination IP addresses, port numbers, and connection attempts. Since port scans involve probing various ports on a network, the firewall logs will provide visibility into the attacker's source IP address and help the analyst assess the nature of the scanning activity."},{"num":379,"text":"A security team receives reports about high latency and complete network unavailability throughout most of the office building. Flow logs from the campus switches show high traffic on TCP 445. Which of the following is most likely the root cause of this incident?","options":[["A","Buffer overflow"],["B","NTP amplification attack"],["C","Worm"],["D","DoS attack"]],"correct":"C","explanation":"TCP port 445 is commonly used for Microsoft SMB (Server Message Block) protocol, which is often targeted by worms like WannaCry and NotPetya to spread rapidly across a network. The symptoms described - high traffic on TCP 445, high latency, and network unavailability - suggest a selfreplicating worm is propagating, overwhelming network resources and disrupting normal operations."},{"num":380,"text":"A security analyst is examining a penetration test report and notices that the tester pivoted to critical internal systems with the same local user ID and password. Which of the following would help prevent this in the future?","options":[["A","Implement centralized authentication with proper password policies"],["B","Add password complexity rules and increase password history limits"],["C","Connect the systems to an external authentication server"],["D","Limit the ability of user accounts to change passwords"]],"correct":"A","explanation":"The penetration tester was able to pivot using the same local user ID and password, indicating that systems were using local authentication rather than a centralized authentication mechanism. Implementing centralized authentication (such as Active Directory, LDAP, or RADIUS) with strong password policies would ensure that credentials are managed centrally, reducing the risk of credential reuse and lateral movement across systems. This approach also enables better monitoring and enforcement of security policies."},{"num":381,"text":"When used with an access control vestibule which of the following would provide the best prevention against tailgating?","options":[["A","PIN"],["B","Access card"],["C","Security guard"],["D","CCTV"]],"correct":"C","explanation":"A security guard actively monitors and enforces access control policies in an access control vestibule (mantrap), ensuring that only authorized individuals enter. Unlike PINs, access cards, or CCTV (which only record events), a security guard can physically intervene to prevent tailgating - where an unauthorized person follows an authorized individual into a restricted area."},{"num":382,"text":"A security professional discovers a folder that contains an employee's personal information located on the enterprise\u2019s shared drive. Which of the following best describes the data type the security professional should use to identify organizational policies and standards concerning the storage of employees' personal information?","options":[["A","Legal"],["B","Financial"],["C","Privacy"],["D","Intellectual property"]],"correct":"C","explanation":"Privacy data classification includes Personally Identifiable Information (PII), which consists of an employee\u2019s personal details such as name, address, Social Security number, or other sensitive information. Organizational policies and standards concerning the storage and protection of such data fall under privacy regulations (e.g., GDPR, CCPA, or HIPAA). Ensuring compliance with these policies helps prevent unauthorized access and data breaches."},{"num":383,"text":"A site reliability engineer is designing a recovery strategy that requires quick failover to an identical site if the primary facility goes down. Which of the following types of sites should the engineer consider?","options":[["A","Recovery site"],["B","Hot site"],["C","Cold site"],["D","Warm site"]],"correct":"B","explanation":"A hot site is a fully operational, identical backup site that can take over immediately in case the primary facility goes down. It includes up-to-date data, active servers, and network configurations, allowing for quick failover with minimal downtime. This makes it the best choice for high availability and business continuity requirements."},{"num":384,"text":"Which of the following would an organization most likely use to minimize the loss of data on a file server in the event data needs to be restored?","options":[["A","Snapshots"],["B","Journaling"],["C","Obfuscation"],["D","Tokenization"]],"correct":"A","explanation":"Snapshots capture the state of a file server at a specific point in time, allowing for quick recovery of lost or corrupted data. They provide an efficient way to restore files without relying solely on full backups, minimizing data loss and downtime. This makes snapshots an ideal solution for data recovery and protection on a file server."},{"num":385,"text":"Which of the following solutions would most likely be used in the financial industry to mask sensitive data?","options":[["A","Tokenization"],["B","Hashing"],["C","Salting"],["D","Steganography"]],"correct":"A","explanation":"Tokenization replaces sensitive data, such as credit card numbers, with non-sensitive equivalents (tokens) that have no exploitable value outside the system. It is widely used in the financial industry to protect data while maintaining functionality for processing and analysis."},{"num":386,"text":"Which of the following is a type of vulnerability that may result from outdated algorithms or keys?","options":[["A","Hash collision"],["B","Cryptographic"],["C","Buffer overflow"],["D","Input validation"]],"correct":"B","explanation":"Cryptographic vulnerabilities occur when outdated algorithms or weak encryption keys are used, making systems susceptible to attacks such as brute force or cryptanalysis. These issues undermine the confidentiality and integrity of encrypted data."},{"num":387,"text":"A company wants to prevent proprietary and confidential company information from being shared to outsiders. Which of the following would this best describe?","options":[["A","MOA"],["B","SLA"],["C","MSA"],["D","NDA"]],"correct":"D","explanation":"A Non-Disclosure Agreement (NDA) is a legal contract that restricts parties from disclosing proprietary or confidential information to unauthorized individuals or organizations, making it the most suitable option for protecting sensitive company data."},{"num":388,"text":"A security administrator needs to reduce the attack surface in the company's data centers. Which of the following should the security administrator do to complete this task?","options":[["A","Implement a honeynet."],["B","Define Group Policy on the servers."],["C","Configure the servers for high availability."],["D","Upgrade end-of-support operating systems."]],"correct":"D","explanation":"Upgrading end-of-support operating systems ensures that the servers receive security patches and updates, significantly reducing vulnerabilities and thereby the overall attack surface."},{"num":389,"text":"Which of the following is a prerequisite for a DLP solution?","options":[["A","Data destruction"],["B","Data sanitization"],["C","Data classification"],["D","Data masking"]],"correct":"C","explanation":"Data classification is essential for a Data Loss Prevention (DLP) solution to function effectively. It identifies and labels data based on sensitivity and importance, enabling the DLP system to apply appropriate policies to protect it."},{"num":390,"text":"A business provides long-term cold storage services to banks that are required to follow regulator-imposed data retention guidelines. Banks that use these services require that data is disposed of in a specific manner at the conclusion of the regulatory threshold for data retention. Which of the following aspects of data management is the most important to the bank in the destruction of this data?","options":[["A","Encryption"],["B","Classification"],["C","Certification"],["D","Procurement"]],"correct":"C","explanation":"Certification provides documented proof that data was destroyed in compliance with regulatory requirements. This is critical for banks to demonstrate adherence to data retention and disposal mandates imposed by regulators."},{"num":391,"text":"The physical security team at a company receives reports that employees are not displaying their badges. The team also observes employees tailgating at controlled entrances. Which of the following topics will the security team most likely emphasize in upcoming security training?","options":[["A","Social engineering"],["B","Situational awareness"],["C","Phishing"],["D","Acceptable use policy"]],"correct":"B","explanation":"Situational awareness training helps employees recognize and respond appropriately to physical security threats, such as tailgating and failure to display ID badges, promoting adherence to security protocols in controlled areas."},{"num":392,"text":"Which of the following would most likely be a hacktivist's motive?","options":[["A","Financial gain"],["B","Espionage"],["C","Philosophical beliefs"],["D","Revenge"]],"correct":"C","explanation":"Hacktivists are typically driven by ideological or political motivations, using hacking to promote or protest specific philosophical beliefs or causes."},{"num":393,"text":"During a recent log review, an analyst discovers evidence of successful injection attacks. Which of the following will best address this issue?","options":[["A","Authentication"],["B","Secure cookies"],["C","Static code analysis"],["D","Input validation"]],"correct":"D","explanation":"Input validation ensures that user-supplied data is properly checked before processing, effectively preventing injection attacks such as SQL or command injections by rejecting malicious input."},{"num":394,"text":"Which of the following is the first step to secure a newly deployed server?","options":[["A","Close unnecessary service ports."],["B","Update the current version of the software."],["C","Add the device to the ACL."],["D","Upgrade the OS version."]],"correct":"B","explanation":"Updating the software ensures the server is protected against known vulnerabilities from the start. This is a critical first step before applying further hardening measures like closing ports or configuring access controls."},{"num":395,"text":"A security analyst receives an alert that there was an attempt to download known malware. Which of the following actions would allow the best chance to analyze the malware?","options":[["A","Review the IPS logs and determine which command-and-control IPs were blocked."],["B","Analyze application logs to see how the malware attempted to maintain persistence."],["C","Run vulnerability scans to check for systems and applications that are vulnerable to the malware"],["D","Obtain and execute the malware in a sandbox environment and perform packet captures."]],"correct":"D","explanation":"Running the malware in a controlled sandbox environment allows the analyst to safely observe its behavior, including communication, persistence mechanisms, and payload delivery, providing the most comprehensive analysis."},{"num":396,"text":"Which of the following should be used to ensure a user has the permissions needed to effectively do an assigned job role?","options":[["A","Changing default passwords"],["B","Implementing least privilege"],["C","Enforcing baseline configurations"],["D","Applying network segmentation"]],"correct":"B","explanation":"The principle of least privilege ensures users are granted only the permissions necessary to perform their specific job functions, minimizing the risk of unauthorized access or actions."},{"num":397,"text":"An employee receives a text message from an unrecognized number claiming to be the Chief Executive Officer and asking the employee to purchase gift cards. Which of the following types of attacks describes this example?","options":[["A","Watering-hole"],["B","Disinformation"],["C","Phishing"],["D","Impersonation"]],"correct":"D","explanation":"Impersonation involves an attacker pretending to be a trusted individual, such as a CEO, to trick someone into taking an action - in this case, purchasing gift cards - often seen in social engineering attacks via text or email."},{"num":398,"text":"An unexpected and out-of-character email message from a Chief Executive Officer's corporate account asked an employee to provide financial information and to change the recipient's contact number. Which of the following attack vectors is most likely being used?","options":[["A","Business email compromise"],["B","Phishing"],["C","Brand impersonation"],["D","Pretexting"]],"correct":"A","explanation":"Business email compromise (BEC) involves the use of a legitimate or spoofed business email account, often from executives, to trick employees into performing unauthorized actions like transferring funds or revealing sensitive information."},{"num":399,"text":"Which of the following should an organization use to ensure that it can review the controls and performance of a service provider or vendor?","options":[["A","Service-level agreement"],["B","Memorandum of agreement"],["C","Right-to-audit clause"],["D","Supply chain analysis"]],"correct":"C","explanation":"A right-to-audit clause gives an organization the legal ability to inspect and verify a service provider's or vendor\u2019s controls, processes, and compliance with contractual obligations, ensuring transparency and accountability."},{"num":400,"text":"Which of the following is used to calculate the impact to an organization per cybersecurity incident?","options":[["A","SLE"],["B","ALE"],["C","ARO"],["D","SLA"]],"correct":"A","explanation":"Single Loss Expectancy (SLE) represents the monetary loss an organization expects from a single cybersecurity incident, helping quantify the financial impact of individual events."},{"num":401,"text":"A retail company receives a request to remove a customer's data. Which of the following is the retail company considered under GDPR legislation?","options":[["A","Data processor"],["B","Data controller"],["C","Data subject"],["D","Data custodian"]],"correct":"B","explanation":"Under GDPR, the data controller determines the purposes and means of processing personal data. The retail company, which collects and manages customer data, is responsible for complying with data deletion requests and thus acts as the data controller."},{"num":402,"text":"An administrator implements web-filtering products but still sees that users are visiting malicious links. Which of the following configuration items does the security administrator need to review?","options":[["A","Intrusion prevention system"],["B","Content categorization"],["C","Encryption"],["D","DNS service"]],"correct":"B","explanation":"Content categorization defines how websites are classified (e.g., gambling, malicious, social media) within the web-filtering product. If users are still accessing malicious links, it likely means the categorization settings need to be reviewed or updated to block those sites effectively."},{"num":403,"text":"A security analyst is reviewing the following logs about a suspicious activity alert for a user's VPN log-ins: Which of the following malicious activity indicators triggered the alert?","options":[["A","Impossible travel"],["B","Account lockout"],["C","Blocked content"],["D","Concurrent session usage"]],"correct":"A","explanation":"The logs show successful logins from Chicago, IL, and then within minutes, logins from Rome, Italy, followed again by logins from Chicago. The time between these geographically distant logins is too short for physical travel, triggering the \"impossible travel\" alert\u2014an indication of potential credential compromise.","image":"q403.jpg"},{"num":404,"text":"Which of the following phases of the incident response process attempts to minimize disruption?","options":[["A","Recovery"],["B","Containment"],["C","Preparation"],["D","Analysis"]],"correct":"B","explanation":"The containment phase focuses on limiting the scope and impact of an incident to prevent further damage or disruption, thereby helping to maintain business continuity during the response process."},{"num":405,"text":"Which of the following security principles most likely requires validation before allowing traffic between systems?","options":[["A","Policy enforcement"],["B","Authentication"],["C","Zero Trust architecture"],["D","Confidentiality"]],"correct":"C","explanation":"Zero Trust architecture is built on the principle of \u201cnever trust, always verify,\u201d meaning that every request for resource access must be validated - regardless of where it originates - before any traffic is allowed between systems. This continuous validation requirement distinguishes Zero Trust from other models."},{"num":406,"text":"Company A jointly develops a product with Company B, which is located in a different country. Company A finds out that their intellectual property is being shared with unauthorized companies. Which of the following has been breached?","options":[["A","SLA"],["B","AUP"],["C","SOW"],["D","MOA"]],"correct":"D","explanation":"A Memorandum of Agreement establishes the formal terms of collaboration between parties, including confidentiality and intellectual property rights. Unauthorized sharing of jointly developed IP constitutes a breach of that agreement."},{"num":407,"text":"An accounting employee recently used software that was not approved by the company. Which of the following risks does this most likely represent?","options":[["A","Unskilled attacker"],["B","Hacktivist"],["C","Shadow IT"],["D","Supply chain"]],"correct":"C","explanation":"The use of unauthorized software by an internal employee is a classic example of Shadow IT, where unsanctioned applications introduce unvetted security and compliance risks."},{"num":408,"text":"Which of the following activities is used to determine the reason an incident occurred, prior to closing the incident?","options":[["A","Root cause analysis"],["B","Detection"],["C","E-discovery"],["D","Lessons learned"]],"correct":"A","explanation":"Root cause analysis is the process of identifying the fundamental reason an incident occurred, ensuring that underlying issues are addressed before the incident is closed."},{"num":409,"text":"Which of the following is the greatest advantage that network segmentation provides?","options":[["A","End-to-end encryption"],["B","Decreased resource utilization"],["C","Enhanced endpoint protection"],["D","Configuration enforcement"],["E","Security zones"]],"correct":"E","explanation":"By dividing a network into distinct security zones, segmentation isolates traffic flows and contains breaches, preventing attackers from moving laterally across the entire environment."},{"num":410,"text":"Which of the following is a directive managerial control?","options":[["A","Acceptable use policy"],["B","Log-in warning banner"],["C","Master service agreement"],["D","No trespassing sign"]],"correct":"A","explanation":"An acceptable use policy is a managerial directive that formally defines required behaviors and rules for system use. It directs employees on what is and isn\u2019t allowed, making it a classic example of a directive control."},{"num":411,"text":"Which of the following is the best way to prevent data from being leaked from a secure network that does not need to communicate externally?","options":[["A","Air gap"],["B","Containerization"],["C","Virtualization"],["D","Decentralization"]],"correct":"A","explanation":"Physically isolating a network (air gapping) ensures there is no direct or indirect external connection, effectively preventing any data leakage from the secure environment."},{"num":412,"text":"Which of the following activities identifies but does not exploit vulnerabilities?","options":[["A","Penetration test"],["B","Static analysis"],["C","Dynamic analysis"],["D","Bug bounty"]],"correct":"B","explanation":"Static analysis examines code in a non-running state to uncover vulnerabilities without executing or exploiting them, ensuring you identify issues without actively attacking the system."},{"num":413,"text":"A penetration tester was able to gain unauthorized access to a hypervisor platform. Which of the following vulnerabilities was most likely exploited?","options":[["A","Cross-site scripting"],["B","SQL injection"],["C","Race condition"],["D","VM escape"]],"correct":"D","explanation":"VM escape occurs when an attacker breaks out of a virtual machine\u2019s sandbox to interact directly with the underlying hypervisor, granting unauthorized access to the host platform. This is the vulnerability exploited when compromising a hypervisor."},{"num":414,"text":"An attacker defaces a company's website and refuses to relinquish control until the company removes specific harmful chemicals from its products. Which of the following best describes this type of threat actor?","options":[["A","Unskilled attacker"],["B","Hacktivist"],["C","Organized crime"],["D","Espionage"]],"correct":"B","explanation":"A hacktivist uses cyberattacks, such as website defacement, to advance a political or social agenda. In this case, the attacker\u2019s demand to remove harmful chemicals reflects an ideological motive, characteristic of hacktivism."},{"num":415,"text":"A company uses a cloud-based server for file storage and wants to ensure the security of its data in transit. Which of the following should the company use to secure this type of communication? (Choose two.)","options":[["A","TLS certificates"],["B","WPA2 encryption"],["C","HTTPS"],["D","Virtual private network"],["E","Encryption key management"],["F","Digital signatures"]],"correct":"AD","explanation":"TLS certificates establish an encrypted channel (SSL/TLS) between clients and the cloud server, ensuring all file transfer traffic is protected in transit. A VPN creates a secure, encrypted tunnel over the Internet, adding an additional layer of protection for all network communications with the cloud environment."},{"num":416,"text":"An organization found gaps in its software development environment and is implementing compensating controls to better protect its systems from external threats. Which of the following would be most effective? (Choose two.)","options":[["A","Platform hardening"],["B","Expanded logging"],["C","Network segmentation"],["D","Access control"],["E","Data encryption"],["F","Application allow list"]],"correct":"AF","explanation":"Platform hardening locks down development hosts, removing unnecessary services and closing unused ports, so attackers have fewer vulnerabilities to exploit. An application allow list ensures only approved, vetted software can run in the environment, preventing malicious or untested code from executing."},{"num":417,"text":"Which of the following is a qualitative approach to risk analysis?","options":[["A","Including the MTTR and MTBF as part of the risk assessment"],["B","Tracking and documenting network risks using a risk register"],["C","Assigning a level of high, medium, or low to the risk rating"],["D","Using ALE and ARO to help determine whether a risk should be mitigated"]],"correct":"C","explanation":"A qualitative risk analysis uses descriptive scales (e.g., high, medium, low) to prioritize risks based on their likelihood and impact, rather than numeric calculations."},{"num":418,"text":"Which of the following provides resilience by hosting critical VMs within different IaaS providers while being maintained by internal application owners?","options":[["A","Multicloud architectures"],["B","SaaS provider diversity"],["C","On-premises server load balancing"],["D","Corporate-owned, off-site locations"]],"correct":"A","explanation":"By distributing critical virtual machines across multiple IaaS providers, a multicloud architecture removes single points of failure and ensures continuity even if one provider experiences an outage, while allowing internal teams to maintain control over deployment and configuration."},{"num":419,"text":"While a user reviews their email, a host gets infected by malware that came from an external hard drive plugged into the host. The malware steals all the user's credentials stored in the browser. Which of the following training topics should the user review to prevent this situation from reoccurring?","options":[["A","Operational security"],["B","Removable media and cables"],["C","Password management"],["D","Social engineering"]],"correct":"B","explanation":"Training on removable media security teaches users how to safely handle USB drives and external storage, including scanning for malware and using company approved devices, directly addressing the infection vector in this scenario."},{"num":420,"text":"An organization keeps servers with confidential information in the same network as workstations. An attacker compromises a workstation and moves laterally to a server. Which of the following could have prevented the attacker from accessing the server?","options":[["A","Load balancers"],["B","Security zones"],["C","Virtual private networks"],["D","Proxy servers"]],"correct":"B","explanation":"By placing servers and workstations into separate security zones (network segments) with controlled access between them, the organization would prevent a compromised workstation from directly reaching the confidential servers. This isolation stops lateral movement without needing VPNs, proxies, or load balancers."},{"num":421,"text":"An administrator needs to ensure all emails sent and received by a specific address are stored in a nonalterable format. Which of the following best describes this forensic concept?","options":[["A","E-discovery"],["B","Acquisition"],["C","Legal hold"],["D","Chain of custody"]],"correct":"B","explanation":"Acquisition refers to the process of capturing and preserving digital evidence in a forensically sound, nonalterable format (e.g., bit-for-bit imaging or write-once storage), ensuring the integrity of the emails for later analysis."},{"num":422,"text":"A company recently purchased a new building that does not have an existing wireless or wired infrastructure. A network engineer at the company needs to determine the placement of the access points in the new building. Which of the following accurately describes the task the network engineer will be performing?","options":[["A","Heat map"],["B","Internal assessment"],["C","Corporate reconnaissance"],["D","Site survey"]],"correct":"D","explanation":"A site survey involves evaluating the physical environment, measuring building materials, interference sources, and coverage requirements, to determine optimal access-point placement."},{"num":423,"text":"Which of the following should a systems administrator do after performing remediation activities?","options":[["A","Classify"],["B","Archive"],["C","Rescan"],["D","Isolate"]],"correct":"C","explanation":"After applying patches or other remediation steps, rescanning verifies that the vulnerabilities have been effectively resolved and ensures no residual issues remain."},{"num":424,"text":"An organization wants to increase an application's resiliency by configuring access to multiple servers in the organization's geographically dispersed environment. Which of the following best describes this architecture?","options":[["A","Containerized"],["B","Multitenant"],["C","Load balanced"],["D","Virtualized"]],"correct":"C","explanation":"A load-balanced architecture distributes incoming application traffic across multiple servers, potentially in different geographic locations, to optimize resource use, improve response times, and provide redundancy if any single server fails."},{"num":425,"text":"A user attempts to send an invoice to a customer. When the user follows up with the customer to see if the invoice was received, the customer informs the user that it went to the spam folder. The management team has asked the systems administrator to implement measures to reduce the likelihood of this happening again by implementing server authentication. Which of the following should the systems administrator implement?","options":[["A","SPF"],["B","DMARC"],["C","XDR"],["D","DNSSEC"]],"correct":"A","explanation":"SPF (Sender Policy Framework) lets the domain owner specify which mail servers are authorized to send email on its behalf. Publishing an SPF record in DNS helps recipient mail systems verify the sending server\u2019s legitimacy, reducing the chance that legitimate messages are marked as spam."},{"num":426,"text":"A database engineer needs sample customer data for testing purposes. Which of the following can prevent unauthorized viewing or disclosure of PII?","options":[["A","Masking"],["B","RBAC"],["C","Tokenization"],["D","Filtering"]],"correct":"A","explanation":"Data masking replaces real PII with realistic but fictional values in non-production environments, ensuring testers can\u2019t view or disclose actual sensitive information."},{"num":427,"text":"A user sends an email that includes a digital signature for validation. Which of the following security concepts would ensure a user cannot deny they sent the email?","options":[["A","Non-repudiation"],["B","Confidentiality"],["C","Integrity"],["D","Authentication"]],"correct":"A","explanation":"A digital signature provides cryptographic proof of origin, preventing the sender from denying they authored and sent the email - this is the essence of non-repudiation."},{"num":428,"text":"A company's leadership team wants to ensure employees only print business-related documents on company printers. Which of the following documents should the company add this directive to?","options":[["A","Information security policy"],["B","Data classification policy"],["C","Business continuity plan"],["D","Acceptable use policy"]],"correct":"D","explanation":"An acceptable use policy defines permitted and prohibited activities for using organizational resources, such as specifying that company printers may only be used for business-related documents. This ensures employees understand and agree to the printing restriction."},{"num":429,"text":"An employee receives from a vendor a marketing communication email that includes an attachment. When the employee opens the attachment, the employee's screen displays odd text requesting payment in order to recover data. Within moments, a company-wide email is sent to employees requesting that employees disconnect their computers from the internet and shut them down. Which of the following describes this type of malware?","options":[["A","Trojan"],["B","Worm"],["C","Ransomware"],["D","Virus"]],"correct":"C","explanation":"Ransomware encrypts a user\u2019s files (displaying garbled text) and demands payment to restore access, matching the behavior described."},{"num":430,"text":"Which of the following is a technical security control?","options":[["A","Security guard"],["B","Policy"],["C","Fence"],["D","Firewall"]],"correct":"D","explanation":"A firewall is a technical control enforced by hardware or software to monitor and filter network traffic, distinguishing it from physical (e.g., fence, security guard) or administrative (e.g., policy) controls."},{"num":431,"text":"An organization decides that most employees will work remotely. The existing VPN solution does not have adequate bandwidth, and the content filtering proxy is on premises. Which of the following strategies will enable the business to securely achieve its objective while also being prepared to quickly scale for growth?","options":[["A","Integrate with an SASE platform, and deploy the agent to all laptops."],["B","Purchase a larger internet circuit, and create a NAT policy for the proxy."],["C","Purchase a SOAR solution to decrease response times for remote workers."],["D","Install a secondary VPN and proxy at the disaster recovery site, and automate failover."]],"correct":"A","explanation":"A Secure Access Service Edge (SASE) solution delivers VPN, firewall, and content filtering functions from the cloud, eliminating on-premises bottlenecks and easily scaling as remote usage grows when agents are deployed to endpoints."},{"num":432,"text":"Which of the following is the most likely reason a security analyst would review SIEM logs?","options":[["A","To check for recent password reset attempts"],["B","To monitor for potential DDoS attacks"],["C","To assess the scope of a privacy breach"],["D","To see correlations across multiple hosts"]],"correct":"D","explanation":"A SIEM\u2019s primary value is aggregating and correlating log data from numerous systems to identify patterns or anomalies that span multiple hosts, enabling detection of coordinated or sophisticated attacks."},{"num":433,"text":"Which of the following would help reduce alert fatigue?","options":[["A","Penetration testing"],["B","Compensating controls"],["C","Rule tuning"],["D","Log aggregation"]],"correct":"C","explanation":"Adjusting and refining detection rules reduces false positives and irrelevant alerts, ensuring that security teams receive only meaningful notifications and thereby minimizing alert fatigue."},{"num":434,"text":"Which of the following options most efficiently maintains a system state in the event of a system failure?","options":[["A","Hybrid cloud"],["B","Cold site"],["C","Full backup"],["D","Load balancing"]],"correct":"D","explanation":"A load balancer distributes traffic across multiple, redundant systems and can automatically detect and reroute around a failed node. This active\u2013active approach preserves the running system state and minimizes downtime far more efficiently than standby sites or periodic backups."},{"num":435,"text":"During a SQL update of a database, a temporary field used as part of the update sequence was modified by an attacker before the update completed in order to allow access to the system. Which of the following best describes this type of vulnerability?","options":[["A","Race condition"],["B","Memory injection"],["C","Malicious update"],["D","Side loading"]],"correct":"A","explanation":"A race condition occurs when an attacker exploits the timing window between operations, modifying the temporary field before the update completes, to alter the intended logic and gain unauthorized access."},{"num":436,"text":"A company's accounts payable clerk receives a message from a vendor asking to change their bank account before paying an invoice. The clerk makes the change and sends the payment to the new account. Days later, the clerk receives another message from the same vendor with a request for a missing payment to the original bank account. Which of the following has most likely occurred?","options":[["A","Phishing campaign"],["B","Data exfiltration"],["C","Pretext calling"],["D","Business email compromise"]],"correct":"D","explanation":"The attacker impersonated a trusted vendor via email to redirect funds to their own account, a hallmark of business email compromise. This social engineering tactic exploits legitimate business processes to fraudulently transfer money."},{"num":437,"text":"A vendor salesperson is a personal friend of a company's Chief Financial Officer (CFO). The company recently made a large purchase from the vendor, which was directly approved by the CFO. Which of the following best describes this situation?","options":[["A","Rules of engagement"],["B","Conflict of interest"],["C","Due diligence"],["D","Contractual impact"],["E","Reputational damage"]],"correct":"B","explanation":"When the CFO\u2019s personal relationship with the vendor could improperly influence (or appear to influence) company purchasing decisions, it creates a conflict of interest. The CFO should disclose the relationship and recuse themselves from the approval process."},{"num":438,"text":"The board of a company needs to tell the leadership team which activities are too risky to undertake during business operations. Which of the following risk management strategies does the board need to explain to the leadership team?","options":[["A","The company's risk assessment"],["B","The company's risk acceptance"],["C","The company's risk register"],["D","The company's risk tolerance"]],"correct":"D","explanation":"Risk tolerance defines the threshold of risk the organization is willing to accept. Activities that exceed this threshold are deemed too risky to pursue during normal operations."},{"num":439,"text":"A systems administrator wants to use a technical solution to explicitly define file permissions for the entire team. Which of the following should the administrator implement?","options":[["A","ACL"],["B","Monitoring"],["C","Isolation"],["D","HIPS"]],"correct":"A","explanation":"An Access Control List (ACL) is a technical mechanism that explicitly assigns read, write, and execute permissions to specific users or groups for each file, providing granular control over file access."},{"num":440,"text":"A company is concerned with supply chain compromise of new servers and wants to limit this risk. Which of the following should the company review first?","options":[["A","Sanitization procedure"],["B","Acquisition process"],["C","Change management"],["D","Asset tracking"]],"correct":"B","explanation":"Reviewing the acquisition process allows the company to vet vendors, enforce secure procurement controls, and verify hardware integrity before servers enter the environment, directly mitigating supply chain compromise risks."},{"num":441,"text":"A security analyst receives an alert from a front-end web server connected to a database back end. The alert contains the following logs: Which of the following attacks is occurring?","options":[["A","Buffer overflow"],["B","Brute-force"],["C","Injection"],["D","Replay"]],"correct":"C","explanation":"The log shows classic SQL injection techniques\u2014tautology (1=1), comment injection ('--), and a time based payload (dbms_lock.sleep(20)), all indicative of an SQL injection attack.","image":"q441.jpg"},{"num":442,"text":"Which of the following control types involves restricting IP connectivity to a router's web management interface to protect it from being exploited by a vulnerability?","options":[["A","Corrective"],["B","Physical"],["C","Preventive"],["D","Managerial"]],"correct":"C","explanation":"Restricting IP access to the router\u2019s management interface proactively blocks unauthorized attempts to exploit vulnerabilities, making it a preventive control."},{"num":443,"text":"Which of the following data types relates to data sovereignty?","options":[["A","Data classified as public in other countries"],["B","Personally identifiable data while traveling"],["C","Health data shared between doctors in other nations"],["D","Data at rest outside of a country's borders"]],"correct":"D","explanation":"Data sovereignty concerns the legal and regulatory requirements governing data where it physically resides. Storing data at rest outside a country\u2019s borders subjects it to the foreign jurisdiction\u2019s laws, making this the key data sovereignty issue."},{"num":444,"text":"A software developer wishes to implement an application security technique that will provide assurance of the application\u2019s integrity. Which of the following techniques will achieve this?","options":[["A","Secure cookies"],["B","Input validation"],["C","Static analysis"],["D","Code signing"]],"correct":"D","explanation":"Code signing uses digital signatures to verify that an application\u2019s binaries haven\u2019t been altered since they were signed, providing cryptographic assurance of the software\u2019s integrity."},{"num":445,"text":"A penetration test reveals that users can easily access internal VLANs from the company's guest Wi-Fi. Which of the following security principles would remediate this vulnerability by improving network authentication mechanisms?","options":[["A","VLAN ACLs"],["B","Captive portal"],["C","DNSSEC"],["D","802.1X"]],"correct":"D","explanation":"802.1X enforces port-based authentication before assigning a device to a VLAN, ensuring only authorized users can join internal networks and preventing guests from accessing protected segments."},{"num":446,"text":"A company recently set up a system for employees to access their files remotely. However, the IT team has noticed that some employees are using personal devices to access the system. Which of the following security techniques could help mitigate the risk of unauthorized connections by personal devices?","options":[["A","Multifactor Authentication"],["B","Conditional Access Policies"],["C","Cloud Access Security Broker"],["D","Data Loss Prevention"]],"correct":"B","explanation":"Conditional Access lets you enforce device-based requirements, such as requiring devices to be enrolled, compliant, or managed, before granting access. By blocking or limiting connections from unmanaged personal devices, it prevents unauthorized endpoints from reaching the company\u2019s remote file system."},{"num":447,"text":"Which of the following security controls is a company implementing by deploying HIPS? (Choose two.)","options":[["A","Directive"],["B","Preventive"],["C","Physical"],["D","Corrective"],["E","Compensating"],["F","Detective"]],"correct":"BF","explanation":"A host-based intrusion prevention system actively monitors and blocks malicious behavior on the endpoint (preventive control) while also alerting or logging suspicious events (detective control)."},{"num":448,"text":"Which of the following is the best physical security measure that prevents unauthorized vehicles from entering a data center while still allowing foot traffic?","options":[["A","Access control vestibules"],["B","Fencing"],["C","Video surveillance"],["D","Retractable bollards"]],"correct":"D","explanation":"Retractable bollards provide a strong physical barrier to stop unauthorized vehicles while remaining low enough (or lowered) to let pedestrians pass freely, making them ideal for controlling vehicle access without impeding foot traffic."},{"num":449,"text":"Which of the following are the best methods for hardening end user devices? (Choose two.)","options":[["A","Full disk encryption"],["B","Group-level permissions"],["C","Account lockout"],["D","Endpoint protection"],["E","Proxy server"],["F","Segmentation"]],"correct":"AD","explanation":"Full disk encryption ensures that all data on the device remains confidential if the device is lost or stolen. Endpoint protection (antivirus/EDR) continuously defends against malware, exploits, and other active threats, directly hardening the device against attacks."},{"num":450,"text":"Which of the following policies outlines what employees can and cannot do on company-issued devices?","options":[["A","Acceptable use"],["B","Data classification"],["C","Change management"],["D","Business continuity"]],"correct":"A","explanation":"An acceptable use policy defines the permitted and prohibited behaviors for employees when using company-issued devices, ensuring clear guidelines on what activities are allowed."},{"num":451,"text":"A developer receives this message when testing a new external website: This site cannot be reached. Which of the following logs would most likely help identify the root cause?","options":[["A","Firewall"],["B","IDS"],["C","Application"],["D","System"]],"correct":"A","explanation":"When a site is unreachable, the first step is to verify whether network traffic is being blocked. Firewall logs will show if connection attempts to the external site are being denied or dropped, pinpointing whether the firewall is preventing access."},{"num":452,"text":"Which of the following methods to secure data is most often used to protect data in transit?","options":[["A","Encryption"],["B","Obfuscation"],["C","Permission restrictions"],["D","Hashing"]],"correct":"A","explanation":"Encryption transforms data into ciphertext before transmission, ensuring that intercepted information remains unreadable to unauthorized parties and thus securing data in transit."},{"num":453,"text":"Which of the following does a user often agree to when logging in to a domain?","options":[["A","AUP"],["B","MAC"],["C","EULA"],["D","EAP"]],"correct":"A","explanation":"When users log in to a corporate domain, they\u2019re typically presented with an acceptable use policy outlining the rules and responsibilities for system use before gaining access. This ensures they agree to organizational guidelines up front."},{"num":454,"text":"A Chief Information Security Officer wants to enhance security capabilities to block PH from being emailed or downloaded to unapproved external media. Which of the following solutions will accomplish this goal?","options":[["A","Deploying DLP software on servers and endpoints"],["B","Configuring servers and endpoints to use a centralized web proxy"],["C","Implementing secure protocols on servers and endpoints"],["D","Installing EDR software on servers and endpoints"]],"correct":"A","explanation":"Data Loss Prevention (DLP) solutions inspect content in motion and at rest, across email, web uploads, removable media, and more, and enforce policies to block or quarantine protected health information (PHI) from being transmitted to unapproved destinations. By deploying DLP agents on both servers and endpoints, the organization gains granular control over where sensitive data can flow, effectively preventing PH from being emailed or copied to unauthorized external media."},{"num":455,"text":"After a breach at a data processing center, an administrator receives a notification that administrative passwords were leaked online. Which of the following should be used to prevent this incident from occurring in the future?","options":[["A","Password management"],["B","Password complexity"],["C","Password policy"],["D","Password vault"]],"correct":"D","explanation":"A centralized password vault securely stores and manages privileged credentials, encrypting them at rest, controlling access, and enabling strong rotation policies, so administrative passwords are never exposed in plaintext and can\u2019t be leaked online."},{"num":456,"text":"A systems administrator has overwritten all of the supervisor's permissions in order to perform malicious activities. Which of the following does this describe?","options":[["A","Shadow IT"],["B","Unskilled attacker"],["C","Insider threat"],["D","Hacktivist"]],"correct":"C","explanation":"An insider threat involves a trusted individual within the organization, such as a systems administrator, misusing their legitimate access to carry out malicious actions, like overwriting a supervisor\u2019s permissions."},{"num":457,"text":"Which of the following would best prepare a security team for a specific incident response scenario?","options":[["A","Situational awareness"],["B","Risk assessment"],["C","Root cause analysis"],["D","Tabletop exercise"]],"correct":"D","explanation":"A tabletop exercise walks the security team through a realistic incident scenario in a low-stakes environment, allowing them to practice roles, decisions, and coordination before a real event occurs."},{"num":458,"text":"Which of the following would best ensure a controlled version release of a new software application?","options":[["A","Business continuity planning"],["B","Quantified risk analysis"],["C","Static code analysis"],["D","Change management procedures"]],"correct":"D","explanation":"Change management procedures establish formal processes for planning, approving, testing, and documenting software releases, ensuring new versions are deployed in a controlled, auditable manner."},{"num":459,"text":"Several employees download a productivity program that is useful but also leaks contact information and corporate organizational structure details. Which of the following is the best way to prevent this issue?","options":[["A","Application allow list"],["B","Workstation hardening"],["C","Refusal of unsigned code"],["D","IP blocklist"],["E","Standard user accounts"]],"correct":"A","explanation":"An application allow list ensures only approved software can be installed or run on corporate endpoints, blocking any unapproved programs that might leak sensitive information."},{"num":460,"text":"The Chief Executive Officer has requested that a vendor conduct a penetration test without engaging the internal IT team to validate the company's investment in security tools, awareness training, and SOC personnel. Which of the following penetration testing methods is most likely being used?","options":[["A","Unknown"],["B","Known"],["C","Integrated"],["D","Partially known"]],"correct":"A","explanation":"An \u201cunknown\u201d (black-box) test gives the testers no prior information or coordination with internal teams, mimicking an external attacker and validating defenses without internal assistance."},{"num":461,"text":"A user receives an aggressive text from an unknown sender who is demanding money. Which of the following attacks is this an example of?","options":[["A","Impersonation"],["B","Typosquatting"],["C","Smishing"],["D","Scareware"]],"correct":"C","explanation":"Smishing is a form of phishing conducted via SMS or text messages. An unsolicited, threatening text demanding money exemplifies a smishing attack."},{"num":462,"text":"Employees receive a text message containing a link to a web page that prompts the user to enter their ID and a work phone number. The text message appears to come from the Chief Executive Officer, but it is later discovered that the message is not legitimate. Which of the following does this best represent? (Choose two.)","options":[["A","Misinformation"],["B","Smishing"],["C","Impersonation"],["D","Typosquatting"],["E","Pretexting"],["F","Phishing"]],"correct":"BC","explanation":"Smishing is phishing via SMS/text messages, exactly as seen when users receive a malicious link by text. Impersonation occurs when the attacker poses as the CEO to lend credibility to the request and trick employees into divulging sensitive information."},{"num":463,"text":"A security engineer needs to patch an OS vulnerability that impacts all corporate laptops. Which of the following is necessary to ensure all corporate laptops are patched?","options":[["A","Ownership"],["B","Inventory"],["C","Classification"],["D","Enumeration"]],"correct":"B","explanation":"An accurate inventory of corporate laptops is essential to ensure that every affected device is identified and included in the patch deployment process. Without a complete asset inventory, some laptops could be missed and remain vulnerable."},{"num":464,"text":"Which of the following threat vectors would a user be vulnerable to when using a smartphone to scan a twodimensional matrix barcode?","options":[["A","Quishing"],["B","Smishing"],["C","Vishing"],["D","Phishing"]],"correct":"A","explanation":"Malicious QR codes can embed phishing URLs or commands that execute when scanned. Attacks using QR codes to phish users are known as \u201cquishing.\u201d"},{"num":465,"text":"Which of the following is most likely a security concern when installing and using low-cost IoT devices in infrastructure environments?","options":[["A","Counterfeit products"],["B","Device responsiveness"],["C","Ease of deployment"],["D","Data remanence"]],"correct":"A","explanation":"Low-cost IoT devices often come from unvetted or knock-off manufacturers, introducing counterfeit or tampered hardware and firmware that can embed backdoors or malicious components, posing a major supply-chain security risk."},{"num":466,"text":"Which of the following are activities that should be completed during the containment and eradication phases of the incident response process? (Choose two.)","options":[["A","Notifying stakeholders"],["B","Restoring the system"],["C","Identifying the threat"],["D","Removing the malicious threat"],["E","Developing a recovery plan"],["F","Analyzing the incident"]],"correct":"CD","explanation":"During containment, you first pinpoint exactly what malware or attack vector is in play and how far it has spread - i.e. identifying the threat. Then, in the eradication phase, you eliminate the root cause by removing the malicious threat (malware, backdoors, unauthorized accounts, etc.) before moving on to system recovery."},{"num":467,"text":"All clients who connect to the switchports are required to complete a posture analysis before accessing the internet. Which of the following should the IT team configure to help secure the enterprise infrastructure?","options":[["A","VPN"],["B","WAF"],["C","IPS"],["D","NAC"]],"correct":"D","explanation":"Network Access Control (NAC) enforces endpoint posture checks, such as antivirus status, patch levels, and configuration, before allowing devices on switchports to access the network or internet."},{"num":468,"text":"An attorney prints confidential documents to a copier in an office space near multiple workstations and a reception desk. When the attorney goes to the copier to retrieve the documents, the documents are missing. Which of the following would best prevent this from reoccurring?","options":[["A","Place the copier in the legal department."],["B","Configure DLP on the attorney's workstation."],["C","Set up LDAP authentication on the printer."],["D","Conduct a physical penetration test."]],"correct":"C","explanation":"Requiring users to authenticate at the copier before a print job is released (often called pull-printing) ensures that confidential documents are only printed when the authorized person is physically present preventing documents from being left unattended."},{"num":469,"text":"Which of the following activities should a systems administrator perform to quarantine a potentially infected system?","options":[["A","Move the device into an air-gapped environment."],["B","Disable remote log-in through Group Policy."],["C","Convert the device into a sandbox."],["D","Remote wipe the device using the MDM platform."]],"correct":"A","explanation":"Quarantining an infected host means isolating it from the rest of the network to prevent malware from spreading. Physically or logically placing the device into an air-gapped (isolated) environment severs its connectivity, effectively containing the threat."},{"num":470,"text":"Which of the following can be deployed in data centers as a protection against an undervoltage event?","options":[["A","Resource management"],["B","Load balancer"],["C","Surge protector"],["D","Uninterruptable power supply"]],"correct":"D","explanation":"A UPS provides battery-backed power and voltage regulation, protecting equipment from undervoltage (brownout) conditions by supplying stable power until normal levels are restored or a generator comes online. Surge protectors, by contrast, guard against overvoltage, and the other options don\u2019t address voltage dips."},{"num":471,"text":"According to various privacy rules and regulations, users have the power to request that all data pertaining to them is deleted. This is known as:","options":[["A","right to be forgotten."],["B","attestation and acknowledgement."],["C","data retention."],["D","information deletion."]],"correct":"A","explanation":"Privacy regulations such as the EU\u2019s GDPR grant individuals the \u201cright to be forgotten\u201d (also called the right of erasure), enabling them to request deletion of all personal data that an organization holds about them."},{"num":472,"text":"An analyst identifies that multiple users have the same passwords, but the hashes appear to be completely different. Which of the following most likely explains this issue?","options":[["A","Data masking"],["B","Salting"],["C","Key escrow"],["D","Tokenization"]],"correct":"B","explanation":"Salting appends a unique random value to each user\u2019s password before hashing, so identical passwords produce different hash values and resist rainbow-table attacks."},{"num":473,"text":"An employee receives a work phone. Instead of starting up with the normal operating system, the phone loads to a gaming platform using administrative credentials. Which of the following issues occurred?","options":[["A","Misconfiguration"],["B","Side loading"],["C","Malicious update"],["D","Jailbreaking"]],"correct":"D","explanation":"Jailbreaking a device removes manufacturer, or carrier imposed restrictions, granting administrative control and allowing it to boot into unauthorized software (in this case, a gaming platform) instead of the standard operating system."},{"num":474,"text":"A university uses two different cloud solutions for storing student data. Which of the following does this represent?","options":[["A","Load balancer"],["B","Parallel processing"],["C","Platform diversity"],["D","Clustering"]],"correct":"C","explanation":"By employing multiple cloud providers for the same workloads, the university reduces reliance on a single vendor and mitigates risks like outages or vendor-specific vulnerabilities."},{"num":475,"text":"An employee clicked a malicious link in an email and downloaded malware onto the company's computer network. The malicious program exfiltrated thousands of customer records. Which of the following should the company implement to best prevent this in the future?","options":[["A","User awareness training"],["B","Network monitoring"],["C","Endpoint protection"],["D","Data loss prevention"]],"correct":"C","explanation":"Deploying modern endpoint protection (antivirus/EDR) on each workstation can detect and block malicious payloads downloaded via phishing links, stopping the malware before it can install and exfiltrate customer data. This directly prevents the root cause (malware infection), whereas other controls (like DLP) act later in the attack chain."},{"num":476,"text":"A forensic engineer determines that the root cause of a compromise is a SQL injection attack. Which of the following should the engineer review to identify the command used by the threat actor?","options":[["A","Metadata"],["B","Application log"],["C","System log"],["D","Netflow log"]],"correct":"B","explanation":"Application logs capture the SQL statements executed (including user inputs and errors). Reviewing the application log will reveal the exact injection payload and commands the attacker used, whereas system or network logs do not record SQL query details."},{"num":477,"text":"In which of the following will unencrypted PLC management traffic most likely be found?","options":[["A","SDN"],["B","IoT"],["C","VPN"],["D","SCADA"]],"correct":"D","explanation":"SCADA systems orchestrate and manage PLCs in industrial environments, and their native management protocols (e.g., Modbus, DNP3) are often sent unencrypted."},{"num":478,"text":"An administrator must implement a solution that provides security and network connectivity between two companies. Which of the following infrastructure solutions is the best for this purpose?","options":[["A","UTM"],["B","VPN"],["C","NAC"],["D","NGFW"]],"correct":"B","explanation":"A VPN establishes an encrypted tunnel over the Internet (or other untrusted networks), securely linking two separate corporate networks so they can communicate as if on a private network."},{"num":479,"text":"A software engineering manager wants to scan the code for security vulnerabilities before it is pushed into production. Which of the following types of analysis should the manager select?","options":[["A","Static"],["B","Threat"],["C","Packet"],["D","Dynamic"],["E","Package"]],"correct":"A","explanation":"Static analysis inspects source code at rest, prior to execution, to identify security vulnerabilities, coding errors, and insecure patterns before the software is deployed."},{"num":480,"text":"A security team purchases a tool for cloud security posture management. The team is quickly overwhelmed by the number of misconfigurations the tool detects. Which of the following should the security team configure to establish secure baselines for cloud resource usage?","options":[["A","CASB"],["B","IAM"],["C","Guardrails"],["D","XDR"]],"correct":"C","explanation":"Guardrails define and enforce organization-specific policies and secure configuration baselines in cloud environments, automatically detecting and preventing deviations from approved settings."},{"num":481,"text":"Which of the following is a social engineering attack in which a bad actor impersonates a web URL?","options":[["A","Pretexting"],["B","Misinformation"],["C","Typosquatting"],["D","Watering-hole"]],"correct":"C","explanation":"Typosquatting involves registering a look-alike domain (e.g., exampl\u0435.com instead of example.com) to trick users who mistype URLs into visiting a malicious site."},{"num":482,"text":"A company is in the process of cutting jobs to manage costs. The Chief Information Security Officer is concerned about the increased risk of an insider threat. Which of the following would most likely help the security awareness team address this potential threat?","options":[["A","Immediately disable the accounts of staff who are likely to be terminated."],["B","Train supervisors to identify and manage disgruntled employees."],["C","Configure DLP to monitor staff who will be terminated."],["D","Raise awareness for business leaders on social engineering techniques."]],"correct":"B","explanation":"Equipping supervisors to recognize signs of dissatisfaction and potential insider threats enables early intervention, addressing the human factors that awareness programs are designed to influence."},{"num":483,"text":"A security analyst is prioritizing vulnerability scan results using a risk-based approach. Which of the following is the most efficient resource for the analyst to use?","options":[["A","Business impact analysis"],["B","Common Vulnerability Scoring System"],["C","Risk register"],["D","Exposure factor"]],"correct":"B","explanation":"CVSS provides a standardized, numerical severity rating for each vulnerability, enabling an analyst to efficiently rank and prioritize scan findings based on objective risk metrics."},{"num":484,"text":"A penetration tester visits a client's website and downloads the site's content. Which of the following actions is the penetration tester performing?","options":[["A","Unknown environment testing"],["B","Vulnerability scan"],["C","Due diligence"],["D","Passive reconnaissance"]],"correct":"D","explanation":"Downloading publicly available website content without exploiting vulnerabilities or interacting with private systems is passive reconnaissance - collecting information from external sources without direct intrusion."},{"num":485,"text":"Which of the following actions must an organization take to comply with a person's request for the right to be forgotten?","options":[["A","Purge all personally identifiable attributes."],["B","Encrypt ail of the person's data."],["C","Remove all of the person's data."],["D","Obfuscate all of the person's data."]],"correct":"C","explanation":"The \u201cright to be forgotten\u201d (right of erasure) requires that organizations delete or permanently remove all personal data related to the individual from their systems and backups, not merely obfuscate or encrypt it."},{"num":486,"text":"An administrator must authenticate users to systems using credentials already authenticated by a business partner's LDAP system. Which of the following should the administrator deploy to enable this functionality?","options":[["A","Media access control"],["B","Interoperability"],["C","OAUTH"],["D","Federation"]],"correct":"D","explanation":"Federation allows users authenticated by an external identity provider (such as a partner\u2019s LDAP directory) to access your systems without reentering credentials, by trusting and exchanging authentication assertions between domains."},{"num":487,"text":"The help desk receives multiple calls indicating machines with an outdated OS version are running slowly. Several users report seeing virus detection alerts. Which of the following mitigation techniques should be reviewed first?","options":[["A","Patching"],["B","Segmentation"],["C","Monitoring"],["D","Isolation"]],"correct":"A","explanation":"Outdated operating systems are a primary vector for malware and performance issues. Ensuring that all machines are fully patched closes known vulnerabilities that attackers exploit - reducing infections and restoring system stability."},{"num":488,"text":"Which of the following actions should be performed on end-of-life equipment before it is discarded?","options":[["A","Isolation"],["B","Patching"],["C","Decommissioning"],["D","Monitoring"]],"correct":"C","explanation":"Decommissioning formally retires the equipment by removing it from operational use, securely wiping or destroying any stored data, and updating asset inventories - ensuring sensitive information isn\u2019t left on discarded hardware."},{"num":489,"text":"Which of the following actions would reduce the number of false positives for an analyst to manually review?","options":[["A","Create playbooks as part of a SOAR platform."],["B","Redefine the patch management process."],["C","Replace an EDR tool with an XDR solution."],["D","Disable AV heuristics scanning."]],"correct":"A","explanation":"By automating the triage and handling of routine or known-false alerts through SOAR playbooks, you filter out those false positives before they reach an analyst, significantly reducing manual review workload."},{"num":490,"text":"A government agency requires publicly traded organizations to report cyber breaches within a designated time period. By law, these reports are made public. Which of the following could cause loss of existing and future business for an organization after reports are published?","options":[["A","Fines and penalties"],["B","Reputational damage"],["C","Board oversight"],["D","Conflicts of interest"]],"correct":"B","explanation":"Public disclosure of a breach can undermine customer and partner trust in an organization\u2019s ability to protect data - directly leading to loss of existing contracts and deterring future business. Reputational damage persists long after fines or oversight actions and most impacts revenue relationships."},{"num":491,"text":"Which of the following would a service provider supply as an assurance for a disposal service as part of a disposal process?","options":[["A","Insurance"],["B","Certification"],["C","Classification"],["D","Retention"]],"correct":"B","explanation":"As part of secure disposal, a service provider issues a certificate of destruction (a form of certification) to formally attest that media or documents were disposed of in accordance with agreed procedures and compliance requirements."},{"num":492,"text":"The security department is remediating vulnerabilities that were found during an audit of newly deployed systems. Which of the following must be done to ensure compliance?","options":[["A","Confirm false positives."],["B","Review the attack surface."],["C","Conduct a rescan."],["D","Report the remediations."]],"correct":"C","explanation":"After applying fixes, rescanning is essential to verify that the remediated systems no longer exhibit the previously detected vulnerabilities, ensuring true compliance with the audit findings."},{"num":493,"text":"A company with a high-availability website is looking to harden its controls at any cost. The company wants to ensure that the site is secure by finding any possible issues. Which of the following would most likely achieve this goal?","options":[["A","Permission restrictions"],["B","Bug bounty program"],["C","Vulnerability scan"],["D","Reconnaissance"]],"correct":"B","explanation":"A bug bounty program leverages a large, diverse community of security researchers who use a wide range of testing methods to uncover vulnerabilities. This crowd-sourced approach maximizes the chances of finding any possible issue, far beyond what a single scan or internal team could achieve."},{"num":494,"text":"A human resources (HR) employee working from home leaves their company laptop open on the kitchen table. A family member walking through the kitchen reads an email from the Chief Financial Officer addressed to the HR department. The email contains information referencing company layoffs. The family member posts the content of the email to social media. Which of the following policies will the HR employee most likely need to review after this incident?","options":[["A","Hybrid work environment"],["B","Operation security"],["C","Data loss prevention"],["D","Social engineering"]],"correct":"B","explanation":"Operational security (OPSEC) governs how employees protect sensitive information in their day-to-day activities, such as ensuring screens are locked and confidential emails aren\u2019t left exposed in shared spaces. Reviewing OPSEC best practices would help the HR employee prevent accidental disclosure in a home environment."},{"num":495,"text":"A government worker secretly copies classified files that contain defense tactics information to an external drive. The government worker then gives the external drive to a corrupt organization. Which of the following best describes the motivation of the worker?","options":[["A","Espionage"],["B","Data exfiltration"],["C","Financial gain"],["D","Blackmail"]],"correct":"A","explanation":"When an insider steals classified defense information and passes it to a hostile organization, their primary motivation is intelligence gathering on behalf of that organization - classic espionage."},{"num":496,"text":"A Chief Security Officer signs off on a request to allow inbound SMB and RDP from the internet to a single VLAN. Which of the following is the most likely explanation for this activity?","options":[["A","The company built a new file-sharing site."],["B","The IT team requested a new jump host."],["C","The security team is integrating with an SASE platform."],["D","The security team created a honeynet."]],"correct":"D","explanation":"Opening both SMB and RDP from the Internet into a dedicated VLAN is not a standard practice for production services or a simple jump host (which would only require RDP/SSH). Instead, exposing these services in a controlled network segment is characteristic of a honeynet, designed to lure, observe, and analyze attacker behavior against file-sharing and remote-access services."},{"num":497,"text":"A systems administrator discovers a guest user gained access to classified reports. Upon further investigation, the logs indicate that the user was added to the administrator group. Which of the following best describes this attack?","options":[["A","Credential replay"],["B","Privilege escalation"],["C","Directory traversal"],["D","Brute-force"]],"correct":"B","explanation":"Privilege escalation occurs when an attacker, the guest user, gains higher-level permissions than originally assigned (being added to the administrator group), allowing access to classified resources."},{"num":498,"text":"Which of the following sites offers immediate service restoration following a disaster?","options":[["A","Cloud-based"],["B","Hot"],["C","Warm"],["D","Cold"]],"correct":"B","explanation":"A hot site is a fully configured, operational environment that mirrors the primary site, allowing immediate failover and near-instant service restoration after a disaster."},{"num":499,"text":"Which of the following is an example of a certificate that is generated by an internal source?","options":[["A","Digital signature"],["B","Asymmetric key"],["C","Self-signed"],["D","Symmetric key"]],"correct":"C","explanation":"A self-signed certificate is created and signed by the issuing organization itself rather than by an external Certificate Authority, making it an internally generated certificate."},{"num":500,"text":"Which of the following is a benefit of an RTO when conducting a business impact analysis?","options":[["A","It determines the likelihood of an incident and its cost."],["B","It determines the roles and responsibilities for incident responders."],["C","It determines the state that systems should be restored to following an incident."],["D","It determines how long an organization can tolerate downtime after an incident."]],"correct":"D","explanation":"The Recovery Time Objective (RTO) specifies the maximum acceptable duration that a system or service can be unavailable following a disruption, directly defining tolerated downtime limits."},{"num":501,"text":"A recent review of logs indicates many attempts to join an internal wireless network from external devices. The connections appear to be originating from surrounding buildings. Which of the following would best help minimize the visibility of the wireless network?","options":[["A","Mobile device management"],["B","Pre-shared keys"],["C","Heat maps"],["D","Site survey"]],"correct":"D","explanation":"Performing a wireless site survey lets you identify where your signal is spilling outside the building so you can adjust access point placement, transmit power, and antenna orientation to reduce coverage and thus visibility in surrounding areas."},{"num":502,"text":"Which of the following data protection strategies can be used to confirm file integrity?","options":[["A","Masking"],["B","Encryption"],["C","Hashing"],["D","Obfuscation"]],"correct":"C","explanation":"Hashing is used to confirm file integrity by generating a unique fixed-length value for the file; any change in the file alters the hash value, indicating integrity has been compromised."},{"num":503,"text":"An organization discovers that its cold site does not have enough storage and computers available. Which of the following was most likely the cause of this failure?","options":[["A","Capacity planning"],["B","Load balancing"],["C","Backups"],["D","Platform diversity"]],"correct":"A","explanation":"Capacity planning ensures that a disaster recovery site, such as a cold site, has sufficient resources like storage and computers. A failure in capacity planning likely led to the shortfall."},{"num":504,"text":"The security team notices that the Always On VPN solution sometimes fails to connect. This leaves remote users unprotected because they cannot connect to the on-premises web proxy. Which of the following changes will best provide web protection in this scenario?","options":[["A","Implement network access control."],["B","Configure the local gateway to point to the VPN."],["C","Create a public NAT to the on-premises proxy."],["D","Install a host-based content filtering solution."]],"correct":"D","explanation":"Installing a host-based content filtering solution ensures web protection for remote users even when the VPN is down, as filtering and protection occur directly on the user's device regardless of connection to the corporate network."},{"num":505,"text":"A security analyst wants to automate a task that shares data between programs. Which of the following is the best option for the analyst to use?","options":[["A","SOAR"],["B","API"],["C","SFTP"],["D","RDP"]],"correct":"B","explanation":"An API (Application Programming Interface) is the best option for automating tasks and enabling seamless data sharing between different programs, allowing for programmatic interaction and automation."},{"num":506,"text":"An auditor notices that, before logging into the firewall, an employee opens a document in a shared folder that contains administrative credentials. Which of the following should the auditor recommend implementing?","options":[["A","Situational awareness"],["B","Operational security"],["C","Password management"],["D","Acceptable use policy"]],"correct":"C","explanation":"Password management solutions securely store and manage credentials, preventing risky practices like keeping administrative credentials in shared folders, which can lead to unauthorized access."},{"num":507,"text":"Which of the following attacks uses a website to collectively target a group of developers within an organization?","options":[["A","Typosquatting"],["B","Watering hole"],["C","Denial of service"],["D","Credential replay"]],"correct":"B","explanation":"A watering hole attack compromises a website commonly visited by a specific group, such as developers, so when they visit the site, they are collectively targeted and potentially infected."},{"num":508,"text":"Which of the following is the best reason to complete an audit in a banking environment?","options":[["A","Regulatory requirement"],["B","Organizational change"],["C","Self-assessment requirement"],["D","Service-level requirement"]],"correct":"A","explanation":"Completing audits in a banking environment is primarily driven by regulatory requirements to ensure compliance with laws and financial regulations."},{"num":509,"text":"Which of the following is the most likely benefit of conducting an internal audit?","options":[["A","Findings are reported to shareholders"],["B","Reports are not formal and can be reassigned"],["C","Control gaps are identified for remediation"],["D","The need for external audits is eliminated"]],"correct":"C","explanation":"The most likely benefit of conducting an internal audit is the identification of control gaps, allowing the organization to remediate weaknesses before they can be exploited."},{"num":510,"text":"A security analyst identifies an employee who added an unauthorized wireless router to an office branch. After an investigation, the router is removed, and the employee is given mandatory retraining. Which of the following best describes this incident?","options":[["A","Unskilled attacker"],["B","Hacktivist"],["C","Nation-state"],["D","Shadow IT"]],"correct":"D","explanation":"Shadow IT refers to the use of unauthorized devices, software, or systems, such as an employee adding a wireless router without approval, outside of official IT processes."},{"num":511,"text":"Which of the following is the best safeguard to protect against an extended power failure?","options":[["A","Off-site backups"],["B","Batteries"],["C","Uninterruptible power supplies"],["D","Generators"]],"correct":"D","explanation":"Generators are the best safeguard against extended power failures, as they can provide power for long durations, unlike batteries or uninterruptible power supplies, which are intended for short-term use."},{"num":512,"text":"Users see a certificate warning on their browsers when connecting to the server over HTTPS. Which of the following is the most likely cause?","options":[["A","The server is using a wildcard certificate"],["B","The server is using a root certificate"],["C","The server is using no certificate at all"],["D","The server is using a self-signed certificate"]],"correct":"D","explanation":"A self-signed certificate is not trusted by browsers because it is not issued by a recognized certificate authority, leading to certificate warnings when users connect over HTTPS."},{"num":513,"text":"Prior to implementing a design change, the change must go through multiple steps to ensure that it does not cause any security issues. Which of the following is most likely to be one of those steps?","options":[["A","Management review"],["B","Load testing"],["C","Maintenance notifications"],["D","Procedure updates"]],"correct":"A","explanation":"Management review is a key step in the change management process, ensuring that proposed changes are properly evaluated for security and business impact before implementation."},{"num":514,"text":"Which of the following is a benefit of launching a bug bounty program? (Choose two.)","options":[["A","Improved reputation for the organization"],["B","Reduction in the number of zero-day vulnerabilities"],["C","Increased security awareness for the workforce"],["D","Reduced cost of managing the program"],["E","Quicker discovery of vulnerabilities"],["F","Improved patch management process"]],"correct":"AE","explanation":"A bug bounty program can improve an organization\u2019s reputation by demonstrating a proactive approach to security. It enables quicker discovery of vulnerabilities by leveraging external researchers to identify issues faster than internal teams alone."},{"num":515,"text":"Which of the following best explains a concern with OS-based vulnerabilities?","options":[["A","An exploit would give an attacker access to system functions that span multiple applications"],["B","The OS vendor's patch cycle Is not frequent enough to mitigate the large number of threats"],["C","Most users trust the core operating system features and may not notice if the system has been compromised"],["D","Exploitation of an operating system vulnerability is typically easier than any other vulnerability"]],"correct":"A","explanation":"OS-based vulnerabilities are a significant concern because exploiting them can give an attacker access to core system functions, potentially impacting all applications and users on that system."},{"num":516,"text":"During a penetration test in a hypervisor, the security engineer is able to use a script to inject a malicious payload and access the host filesystem. Which of the following best describes this vulnerability?","options":[["A","VM escape"],["B","Cross-site scripting"],["C","Malicious update"],["D","SQL injection"]],"correct":"A","explanation":"VM escape occurs when an attacker exploits a vulnerability in the hypervisor, allowing them to break out of the virtual machine and access the underlying host system\u2019s resources."},{"num":517,"text":"Which of the following security controls are a company implementing by deploying HIPS? (Choose two.)","options":[["A","Directive"],["B","Preventive"],["C","Physical"],["D","Corrective"],["E","Compensating"],["F","Detective"]],"correct":"BF","explanation":"HIPS (Host-based Intrusion Prevention System) is a preventive control because it actively blocks or prevents malicious activities on a host. It is also a detective control, as it monitors and detects suspicious activities or policy violations on the host system."},{"num":518,"text":"Which of the following describes effective change management procedures?","options":[["A","Approving the change after a successful deployment"],["B","Having a backout plan when a patch fails"],["C","Using a spreadsheet for tracking changes"],["D","Using an automatic change control bypass for security updates"]],"correct":"B","explanation":"Effective change management includes having a backout plan, so that if a patch or change fails, systems can be restored to their previous, stable state."},{"num":519,"text":"A company is experiencing a high number of users who are clicking on email-based attacks even though those users have completed annual training. The company's Chief Security Officer wants to identify and reduce which users are phished the most often. Which of the following will best achieve this result?","options":[["A","Begin a semiannual in-person training course with mandatory attendance. The users would perform exercises that simulate answering phone calls from attackers performing social engineering attacks."],["B","Deploy a product that would occasionally send users emails to simulate an attack. The product would alert the security team whenever a user dicks links in the product\u2019s emails."],["C","Hire a security consultant to give a personalized seminar at the company. The consultant would share stones of famous companies that had breaches and explain the ramifications of those events."],["D","Require an MFA when signing in to the email client. Users would need to authenticate once a week at a minimum and daily when working remotely."]],"correct":"B","explanation":"Deploying a simulated phishing product allows the company to directly measure which users are susceptible to phishing attacks by tracking who clicks on simulated malicious links, enabling targeted awareness and training efforts."},{"num":520,"text":"Which of the following mitigation techniques would a security analyst most likely use to avoid bloatware on devices?","options":[["A","Disabled ports/protocols"],["B","Application allow list"],["C","Default password changes"],["D","Access control permissions"]],"correct":"B","explanation":"An application allow list ensures that only approved applications can be installed or run on a device, effectively preventing the installation of unwanted bloatware."},{"num":521,"text":"A company decides to purchase an insurance policy. Which of the following risk management strategies is this company implementing?","options":[["A","Mitigate"],["B","Accept"],["C","Avoid"],["D","Transfer"]],"correct":"D","explanation":"Purchasing an insurance policy is a risk transfer strategy, as the financial impact of a risk is shifted from the company to the insurance provider."},{"num":522,"text":"Which of the following principles requires that a company must keep files or records for a prescribed period of time before it disposes of those files or records?","options":[["A","Data verification"],["B","Data backups"],["C","Data archiving"],["D","Data retention"]],"correct":"D","explanation":"Data retention is the principle that mandates an organization to keep files or records for a specified period before disposing of them, often to meet legal or regulatory requirements."},{"num":523,"text":"A security analyst is monitoring logs from the organization's SIEM and identifies logs related to one of their salespeople: Which of the following is being displayed in the logs?","options":[["A","Impossible travel"],["B","SMTP replay"],["C","Directory traversal"],["D","Cross-site request forgery"]],"correct":"A","explanation":"The logs show the same employee account accessing services from geographically distant locations (Atlanta and Beijing) within a short time frame, which is not physically possible, this is known as impossible travel.","image":"q523.jpg"},{"num":524,"text":"A company wants to update its disaster recovery plan to include a dedicated location for immediate continued operations if a catastrophic event occurs. Which of the following options is best to include in the disaster recovery plan?","options":[["A","Hot site"],["B","Warm site"],["C","Geolocation"],["D","Cold site"]],"correct":"A","explanation":"A hot site is a fully equipped, dedicated location that allows immediate continuation of business operations after a disaster, making it the best choice for minimal downtime."},{"num":525,"text":"Which of the following attacks exploits a potential vulnerability as a result of direct access to a system using weak cryptographic algorithms?","options":[["A","Password cracking"],["B","On-path"],["C","Digital signing"],["D","Side-channel"]],"correct":"A","explanation":"Password cracking attacks exploit weak cryptographic algorithms by attempting to guess or decrypt passwords through direct access to systems or password hashes, making use of vulnerabilities in the cryptography."},{"num":527,"text":"Which of the following describes the reason for using an MDM solution to prevent jailbreaking?","options":[["A","To secure end-of-life devices from incompatible firmware updates"],["B","To avoid hypervisor attacks through VM escape"],["C","To eliminate buffer overflows at the application layer"],["D","To prevent users from changing the OS of mobile devices"]],"correct":"D","explanation":"An MDM solution can enforce device policies that block attempts to modify or replace the mobile OS, preventing users from jailbreaking their devices."},{"num":528,"text":"Which of the following is the best mitigation for a zero-day vulnerability found in mission-critical production servers that must be highly available?","options":[["A","Virtualizing and migrating to a containerized instance"],["B","Removing and sandboxing to an isolated network"],["C","Monitoring and implementing compensating controls"],["D","Patching and redeploying to production as quickly as possible"]],"correct":"C","explanation":"With no patch available for a zero-day, deploying compensating controls, such as enhanced monitoring, intrusion prevention, and strict access restrictions, reduces risk while keeping critical servers online."},{"num":529,"text":"An administrator has configured a quarantine subnet for all guest devices that connect to the network. Which of the following would be best for the security team to configure on the MDM before allowing access to corporate resources?","options":[["A","Device fingerprinting"],["B","Compliance attestation"],["C","NAC"],["D","802.1X"]],"correct":"B","explanation":"Compliance attestation via MDM verifies device posture (OS version, policies, certificates) before granting access, ensuring only compliant devices leave the quarantine subnet and reach corporate resources."},{"num":530,"text":"A security team receives reports about high latency and complete network unavailability throughout most of the office building. Flow logs from the campus switches show high traffic on TCP 445. Which of the following is most likely the root cause of this incident?","options":[["A","Buffer overflow"],["B","NTP amplification attack"],["C","Worm"],["D","Kerberoasting attack"]],"correct":"C","explanation":"A worm exploiting SMB will flood TCP 445 with propagation traffic, overwhelming the network and causing high latency and outages."},{"num":531,"text":"A company executive connects to various networks, such as hotel guest Wi-Fi. while traveling. A security analyst needs to provide a solution that will allow the executive to securely access the corporate internal resources. Which of the following would best meet this requirement?","options":[["A","EAP"],["B","Jump server"],["C","Perimeter network"],["D","VPN"]],"correct":"D","explanation":"A VPN establishes an encrypted tunnel over untrusted networks, ensuring the executive can securely access corporate internal resources from any location."},{"num":532,"text":"Which of the following architecture models ensures that critical systems are physically isolated on the network to prevent access from users with remote access privileges?","options":[["A","Segmentation"],["B","Virtualized"],["C","Air-gapped"],["D","Serverless"]],"correct":"C","explanation":"An air-gapped architecture physically isolates critical systems from all other networks, ensuring they cannot be accessed remotely."},{"num":533,"text":"A security team installs an IPS on an organization's network and needs to configure the system to detect and prevent specific network attacks. Which of the following settings should the team configure first within the IPS?","options":[["A","Allow list policies"],["B","Packet inspection"],["C","Logging and reporting"],["D","Firewall rules"]],"correct":"B","explanation":"Packet inspection is the core functionality of an IPS, as it enables the system to analyze network traffic against signatures and anomalies to detect and prevent specific attacks."},{"num":534,"text":"A security analyst must prevent remote users from accessing malicious URLs. The sites need to be checked inline for reputation, content, or categorization. Which of the following technologies will help secure the enterprise?","options":[["A","VPN"],["B","SASE"],["C","NGFW"],["D","SD-WAN"]],"correct":"B","explanation":"SASE provides a cloud-delivered, inline secure web gateway with URL reputation, content inspection, and categorization for remote users without backhauling traffic through on-premises firewalls."},{"num":535,"text":"A systems administrator needs to provide traveling employees with a security measure that will protect company devices regardless of where they are working. Which of the following should the administrator implement?","options":[["A","Isolation"],["B","Segmentation"],["C","ACL"],["D","HIPS"]],"correct":"D","explanation":"A Host-based Intrusion Prevention System (HIPS) runs directly on each device, monitoring and blocking malicious activity locally, ensuring protection regardless of the network the traveling employee uses."},{"num":536,"text":"Which of the following is used to monitor suspicious traffic in real time between multiple systems within an organization?","options":[["A","NetFlow"],["B","Infrared sensors"],["C","Development network"],["D","Honeynet"]],"correct":"A","explanation":"NetFlow captures and analyzes real-time traffic flow data across multiple systems, enabling detection of suspicious patterns and anomalies."},{"num":537,"text":"A remote employee navigates to a shopping website on their company-owned computer. The employee clicks a link that contains a malicious file. Which of the following would prevent this file from downloading?","options":[["A","DLP"],["B","FIM"],["C","NAC"],["D","EDR"]],"correct":"D","explanation":"An EDR solution actively monitors and blocks malicious behaviors at the endpoint, including intercepting and preventing unauthorized or malicious file downloads, before they can reach the system."},{"num":538,"text":"A security analyst is reviewing the security of a SaaS application that the company intends to purchase. Which of the following documentations should the security analyst request from the SaaS application vendor?","options":[["A","Service-level agreement"],["B","Third-party audit"],["C","Statement of work"],["D","Data privacy agreement"]],"correct":"B","explanation":"A third-party audit report (such as a SOC 2 or ISO 27001 certification) provides independent validation of the vendor\u2019s security controls and assurance of its security posture."},{"num":539,"text":"A security administrator protects passwords by using hashing. Which of the following best describes what the administrator is doing?","options":[["A","Adding extra characters at the end to increase password length"],["B","Generating a token to make the passwords temporal"],["C","Using mathematical algorithms to make passwords unique"],["D","Creating a rainbow table to protect passwords in a list"]],"correct":"C","explanation":"Hashing applies mathematical algorithms to transform passwords into unique, fixed-length values, ensuring the original password cannot be reversed from the hash."},{"num":540,"text":"A customer changes the underlying file structure of a new mobile phone to install a keylogger with administrator permissions. Which of the following does this best describe?","options":[["A","Resource reuse"],["B","Bloatware installation"],["C","Side loading"],["D","Jailbreaking"]],"correct":"D","explanation":"Modifying the device\u2019s file structure to gain root access and install unauthorized software describes jailbreaking."},{"num":541,"text":"Which of the following digital forensics activities would a security team perform when responding to legal requests in a pending investigation?","options":[["A","E-discovery"],["B","User provisioning"],["C","Firewall log export"],["D","Root cause analysis"]],"correct":"A","explanation":"E-discovery involves identifying, preserving, and collecting electronically stored information to comply with legal requests during investigations."},{"num":542,"text":"A security analyst is reviewing the security or a SaaS application that the company intends to purchase. Which of the following documentations should the security analyst request from the SaaS application vendor?","options":[["A","Service-level agreement"],["B","Third-party audit"],["C","Statement or work"],["D","Data privacy agreement"]],"correct":"B","explanation":"A third-party audit provides independent verification that the SaaS vendor\u2019s security controls and processes meet industry standards, which helps the security analyst assess the actual security posture of the application before purchase."},{"num":543,"text":"While a school district is performing state testing, a security analyst notices all internet services are unavailable. The analyst discovers that ARP poisoning is occurring on the network ana then terminates access for the host. Which of the following is most likely responsive for this malicious activity?","options":[["A","Unskilled attacker"],["B","Shadow IT"],["C","Credential stuffing"],["D","DMARC failure"]],"correct":"A","explanation":"ARP poisoning is a basic attack that does not require advanced skills or tools, making it a common method used by unskilled attackers (also known as \"script kiddies\") to disrupt network operations."},{"num":544,"text":"Which of the following hardening techniques must be applied on a container image before deploying it to a production environment? (Choose two.)","options":[["A","Remove default applications."],["B","Install a NIPS."],["C","Disable Telnet."],["D","Reconfigure the DNS."],["E","Add an SFTP server."],["F","Delete the public certificate."]],"correct":"AC","explanation":"Removing default applications reduces the attack surface by eliminating unnecessary software that could be exploited. Disabling Telnet is essential because it is an insecure protocol, and leaving it enabled can create vulnerabilities within the container."},{"num":545,"text":"Which of the following would best explain why a security analyst is running daily vulnerability scans on all corporate endpoints?","options":[["A","To track the status of patching installations"],["B","To find shadow IT cloud deployments"],["C","To continuously monitor hardware inventory"],["D","To hunt for active attackers in the network"]],"correct":"A","explanation":"Daily vulnerability scans help identify unpatched vulnerabilities on corporate endpoints, allowing the security analyst to verify that patches are being installed and to track the effectiveness and status of patch management."},{"num":546,"text":"A security patch is applied to a server. Which of the following will validate this remediation?","options":[["A","Rescanning"],["B","Dynamic analysis"],["C","Reporting"],["D","Static analysis"]],"correct":"A","explanation":"Rescanning the server after applying a security patch confirms whether the vulnerability has been successfully remediated and is no longer detected."},{"num":547,"text":"The internal security team is investigating a suspicious attachment and wants to perform a behavior analysis in an isolated environment. Which of the following will the security team most likely use?","options":[["A","Sandbox"],["B","Jump server"],["C","Work computer"],["D","Container"]],"correct":"A","explanation":"A sandbox provides an isolated environment where suspicious files can be safely executed and monitored for malicious behavior without risking the security of the production network or systems."},{"num":548,"text":"A company is required to use certified hardware when building networks. Which of the following best addresses the risks associated with procuring counterfeit hardware?","options":[["A","A thorough analysis of the supply chain"],["B","A legally enforceable corporate acquisition policy"],["C","A right to audit clause in vendor contracts and SOWs"],["D","An in-depth penetration test of all suppliers and vendors"]],"correct":"A","explanation":"A thorough analysis of the supply chain helps ensure that all hardware is sourced from legitimate, certified vendors, reducing the risk of acquiring counterfeit equipment."},{"num":549,"text":"An analyst discovers a suspicious item in the SQL server logs. Which of the following could be evidence of an attempted SQL injection?","options":[["A","cat /etc/shadow"],["B","dig 25.36.99.11"],["C","cd ../../../"],["D","UserId \u2013 10 OR 1-1"]],"correct":"D","explanation":"The input \"10 OR 1=1\" is a common SQL injection technique designed to manipulate SQL queries, allowing unauthorized access or retrieval of data by altering the logic of the query."},{"num":550,"text":"A company identified the potential for malicious insiders to harm the organization. Which of the following measures should the organization implement to reduce this risk?","options":[["A","Unified threat management"],["B","Web application firewall"],["C","User behavior analytics"],["D","Intrusion detection system"]],"correct":"C","explanation":"User behavior analytics monitors and analyzes user activities to detect anomalies or suspicious behavior, making it effective in identifying and reducing the risk posed by malicious insiders."},{"num":551,"text":"After completing onboarding at a company and reviewing the company\u2019s handbooks and AUP an employee downloads an unapproved application on a company desktop. Which of the following is the best course of action tor the company to take?","options":[["A","Educate the employee's manager."],["B","Silently uninstall the software."],["C","Ensure the employee completes focused training."],["D","Terminate the employee."]],"correct":"C","explanation":"Focused training helps the employee understand the risks and policies regarding software installation, reinforcing compliance and reducing the likelihood of future violations without being overly punitive."},{"num":552,"text":"An organization has experienced a breach because a hacker utilized a standard users two-year-old password that the hacker found on the dark web. Which of the following would have prevented this attack?","options":[["A","Privileged access management"],["B","Account lockout"],["C","Reuse policy"],["D","Complexity requirements"]],"correct":"C","explanation":"A reuse policy prevents users from using old passwords, which helps protect accounts even if previous passwords are compromised and available on the dark web."},{"num":553,"text":"An organization has published a list of domains that end users are not authorized to visit on company devices in order to mitigate data loss or installation or malicious code. A security analyst observes multiple successful attempts to reach a new suspicious domain from an end user\u2019s workstation. Which of the following options can best prevent future access to unauthorized domains?","options":[["A","Assign user awareness training."],["B","Modify the unauthorized content policy."],["C","Deploy an allow list."],["D","Update the proxy filters."]],"correct":"D","explanation":"Updating the proxy filters will block access to the new suspicious domain at the network level, effectively preventing users from reaching unauthorized or malicious websites in the future."},{"num":554,"text":"Users report that certain processes from a batch job are not working correctly and various resources are unavailable. An application owner provides the source and destination address information, and the errors are replicated for troubleshooting purposes. Which of the following should the security team perform next to help isolate the ongoing issue?","options":[["A","Penetration testing"],["B","Packet capture"],["C","Vulnerability scan"],["D","Firewall rues analysis"]],"correct":"B","explanation":"Packet capture allows the security team to analyze network traffic between the source and destination addresses, helping to identify communication issues or resource availability problems in real time."},{"num":555,"text":"A company is experiencing loss of availability due to excessive traffic to their front-end web servers. The company hires a digital forensics expert to investigate the incident. Which of the following logs should the digital forensics expert review first to diagnose the details of this incident?","options":[["A","Router"],["B","Load balancer"],["C","Switch"],["D","Firewall"]],"correct":"B","explanation":"Load balancer logs provide detailed information about incoming web traffic and distribution to the front-end servers, making them the most relevant source to diagnose excessive traffic and availability issues."},{"num":556,"text":"An employee decides to collect PII data from the company\u2019s system for personal use. The employee compresses the data into a single encrypted file before sending the file to their personal email. The security department becomes aware of the attempted misuse and blocks the attachment from leaving the corporate environment. Which of the following types of employee training would most likely reduce the occurrence of this type of issue? (Choose two.)","options":[["A","Privacy legislation"],["B","Social engineering"],["C","Risk management"],["D","Company compliance"],["E","Phishing"],["F","Remote work"]],"correct":"AD","explanation":"Privacy legislation - Teaching employees the legal obligations for handling PII (e.g., GDPR, HIPAA) makes them aware that personal use/transfer is prohibited and punishable. Company compliance - Training on internal policies and acceptable-use rules reinforces exactly what the organization allows or forbids with company data, reducing intentional misuse."},{"num":557,"text":"Which of the following is the best way to remove personal data from a social media account that is no longer being used?","options":[["A","Exercise the right to be forgotten."],["B","Uninstall the social media application."],["C","Perform a factory reset."],["D","Terminate the social media account."]],"correct":"A","explanation":"Exercising the right to be forgotten compels the provider to erase your stored personal data from its systems; simply deleting the app, resetting a device, or even closing the account may leave data retained in backups or archives."},{"num":558,"text":"A Chief Information Security Officer (CISO) of an enterprise environment wants to ensure that users cannot navigate to known malicious domains. The CISO also wants web traffic on the network inspected for malicious activity. Which of the following actions should the CISO take?","options":[["A","Place the intrusion system into IPS mode to block incoming malicious domains, and ensure secure protocol selection is enforced on all network segments."],["B","Deploy EDR software on all company systems, and perform user behavior analytics to detect users going to anomalous domains."],["C","Ensure the company\u2019s name servers use DNS filtering, and configure systems to use a centralized TLS proxy to inspect all HTTP and HTTPS traffic."],["D","Set up a NAC on all segments of the company network, and set the network firewall to block known malicious port numbers at the perimeter."]],"correct":"C","explanation":"A DNS filter blocks lookups to known bad domains, stopping users from reaching them, and a centralized TLS (HTTPS) inspection proxy lets the organization decrypt/inspect HTTP/HTTPS traffic for malicious content before re-encrypting it outbound."},{"num":559,"text":"A user receives a malicious text message that routes to a fake bank login. Which of the following attack types does this scenario describe?","options":[["A","Impersonation"],["B","Phishing"],["C","Vishing"],["D","Smishing"]],"correct":"D","explanation":"Smishing is phishing delivered via SMS/text messages; the malicious text lured the user to a fake bank site."},{"num":560,"text":"A group of people is working together to run multiple ransomware attacks against targets that the group selected to yield the most financial gain. Which of the following best describes this type of activity?","options":[["A","Organized crime"],["B","Nation-state actor"],["C","Shadow IT"],["D","Hacktivism"]],"correct":"A","explanation":"Coordinated ransomware campaigns for profit are characteristic of organized crime groups - criminal enterprises motivated by financial gain rather than ideology or national interest."},{"num":561,"text":"A security officer observes that a software development team is not complying with its corporate security policy on encrypting confidential data. Which of the following categories refers to this type of noncompliance?","options":[["A","External"],["B","Standard"],["C","Regulation"],["D","Internal"]],"correct":"D","explanation":"It\u2019s a violation of an internal corporate security policy, so the non-compliance is classified as internal."},{"num":562,"text":"Which of the following data types best describes an AI tool developed by a company to automate the ticketing system under a specific contract?","options":[["A","Classified"],["B","Regulated information"],["C","Open source"],["D","Intellectual property"]],"correct":"D","explanation":"The AI tool is a proprietary creation owned by the company under contract, making it intellectual property."},{"num":563,"text":"Which of the following would best allow a company to prevent access to systems from the internet?","options":[["A","Containerization"],["B","Virtualization"],["C","SD-WAN"],["D","Air-gapped"]],"correct":"D","explanation":"An air-gapped system is physically and logically isolated from any external (internet-facing) network, so packets from the internet simply have no path to reach it. This architectural separation is the most definitive way to prevent internet access altogether, rather than just limiting or monitoring it."},{"num":564,"text":"While conducting a business continuity tabletop exercise, the security team becomes concerned by potential impacts if a generator were to develop a fault during an extended outage. Which of the following is the team most likely to consider when conducting and planning infrastructure maintenance activities?","options":[["A","RPO"],["B","ARO"],["C","MTBF"],["D","MTTR"]],"correct":"C","explanation":"They\u2019re worried about how long the generator can run before it\u2019s likely to fail during a prolonged outage. MTBF quantifies the expected operational time between failures, guiding preventive maintenance schedules and part replacement intervals to reduce the chance of a fault when the generator is most needed."},{"num":565,"text":"A security analyst is working with the IT group to define appropriate procedures for the destruction of media and assets in the enterprise environment. Which of the following methods provides the strongest level of assurance that the data has been disposed of properly?","options":[["A","Degaussing"],["B","Multipass wipe"],["C","Hashing"],["D","Erasure"],["E","Shredding"]],"correct":"E","explanation":"Physically destroying the media (industrial shredding/pulverizing) renders the platters/chips irrecoverable, providing the highest assurance that no residual data can be reconstructed - unlike logical wipes or degaussing, which can fail or be bypassed on certain media types."},{"num":566,"text":"Which of the following vulnerabilities results in an application running extremely slowly due to an abnormally large number of incoming packets?","options":[["A","Race conditions"],["B","Cross-site scripting"],["C","Buffer overflow"],["D","Side loading"]],"correct":"C","explanation":"An overwhelming volume of packets can fill an application\u2019s input buffers faster than it can process them. Once those buffers are saturated, the program spends excessive time handling overflow conditions (or even overwrites memory), causing dramatic slowdowns and potential instability - classic symptoms of a buffer overflow\u2013style resource exhaustion."},{"num":567,"text":"A company experiences a breach. The investigation reveals that the threat actor used a zero-day vulnerability to gain access and move laterally. Which of the following would best improve the company\u2019s security posture and minimize the time to detect this type of incident?","options":[["A","NAC"],["B","IDS"],["C","DLP"],["D","UBA"]],"correct":"D","explanation":"UBA builds baselines of normal user and entity activity (logins, data access patterns, movement between hosts) and flags deviations - the kind of anomalous lateral movement a zero-day\u2013driven intruder generates. Because it\u2019s behavior-based rather than signature-based, it can surface unseen exploits faster and shrink detection time for novel attacks."},{"num":568,"text":"Which of the following prevents unauthorized modifications to internal processes, assets, and security controls?","options":[["A","Change management"],["B","Playbooks"],["C","Incident response"],["D","Acceptable use policy"]],"correct":"A","explanation":"A formal change management process requires every alteration to be requested, reviewed, approved, documented, and tested before deployment. That governance gate keeps internal processes, assets, and security controls from being modified ad hoc or by unauthorized personnel, ensuring integrity and auditability of all changes."},{"num":569,"text":"A user sits in a coffee shop on a government-issued laptop. A stranger starts a conversation with the user and starts asking about where the user works, what division the user works in, and additional personal information. Which of the following best describes the stranger\u2019s behavior?","options":[["A","Insider threat"],["B","Phishing"],["C","Social engineering"],["D","Risky"]],"correct":"C","explanation":"The stranger is manipulating a casual conversation to elicit sensitive details (employer, division, personal info). This intentional information-gathering through interpersonal interaction is classic social engineering exploiting human trust rather than technical flaws."},{"num":570,"text":"A company\u2019s Chief Information Security Officer (CISO) wants to enhance the capabilities of the incident response team. The CISO directs the incident response team to deploy a tool that rapidly analyzes host and network data from potentially compromised systems and forwards the data for further correlation and reporting. Which of the following tools should the incident response team deploy?","options":[["A","NAC"],["B","IPS"],["C","SIEM"],["D","EDR"]],"correct":"D","explanation":"EDR agents sit on hosts, continuously collect rich telemetry (processes, connections, file changes), and can capture network indicators from those endpoints. They rapidly analyze this data locally and ship it to a backend where it\u2019s correlated and reported \u2013 that\u2019s what the CISO wants to speed detection and investigation of compromised systems."},{"num":571,"text":"Which of the following is a component of a risk register?","options":[["A","Key risk indicators"],["B","Continuous risk assessment"],["C","Risk appetite"],["D","Risk culture"]],"correct":"A","explanation":"A risk register is a catalog of identified risks and their details; for each entry you track signals that a risk is materializing. Those measurable signals are key risk indicators (KRIs) - thresholds or metrics (e.g., failed logins/day, patch backlog age) tied to a specific risk so you can spot escalation early and trigger the planned response. Continuous assessment, appetite, and culture are program-level concepts, not individual register fields."},{"num":572,"text":"Which of the following most securely protects data at rest?","options":[["A","TLS 1.2"],["B","AES-256"],["C","Masking"],["D","Salting"]],"correct":"B","explanation":"AES with a 256-bit key is strong, standards-approved symmetric encryption specifically suited for protecting stored data. It renders the ciphertext unreadable without the key, meets common regulatory requirements (e.g., FIPS 140-2 validated implementations), and provides far stronger assurance for data at rest than transport protocols, masking, or password salting techniques that don\u2019t actually encrypt the full dataset."},{"num":573,"text":"Which of the following is a vulnerability concern for end-of-life hardware?","options":[["A","Failure to follow hardware disposal procedures could result in unintended data release."],["B","The supply chain may not have replacement hardware."],["C","Newly released software may require computing resources not available on legacy hardware."],["D","The vendor may stop providing patches and updates."]],"correct":"D","explanation":"Once hardware reaches end of life, manufacturers typically end security support. Without new firmware/ microcode patches or drivers, newly discovered vulnerabilities remain unpatched, leaving the device exposed indefinitely - this is the core security concern with EOL gear."},{"num":574,"text":"A company\u2019s security team is reviewing its business continuity plan and must determine the amount of time needed for operations to resume after a disaster. Which of the following describes the time frame the security team is trying to determine?","options":[["A","Recovery time objective"],["B","Recovery point objective"],["C","Mean time between failures"],["D","Mean time to repair"]],"correct":"A","explanation":"RTO is the maximum acceptable downtime: the target window within which systems and operations must be restored after a disruption. When the team asks \u201chow long until we\u2019re back up?\u201d, they\u2019re defining the RTO."},{"num":575,"text":"Which of the following is a risk for a company using end-of-life applications on its network?","options":[["A","Default credentials"],["B","Open service ports"],["C","Vulnerable software"],["D","Insecure networks"]],"correct":"C","explanation":"End-of-life applications no longer receive security patches. Newly found flaws stay unpatched, leaving the software inherently vulnerable and an easy entry point for attackers."},{"num":576,"text":"Which of the following makes IaC a preferred security architecture over traditional infrastructure models?","options":[["A","Common attacks are less likely to be effective."],["B","Configuration can be better managed and replicated."],["C","Outsourcing to a third party with more expertise in network defense is possible."],["D","Optimization can occur across a number of computing instances"]],"correct":"B","explanation":"IaC stores infrastructure definitions as version-controlled code, so every change is reviewable, auditable, and repeatable. You can spin up identical, securely preconfigured environments from the same template, eliminating drift and undocumented tweaks that plague traditional, manually built infrastructure. This consistency and traceability are what make IaC the more secure choice."},{"num":577,"text":"Which of the following is an advantage of a microservice-based architecture over traditional software architectures?","options":[["A","Updates can be done one or more times per day if security issues arise."],["B","Managing communication between microservices is more streamlined."],["C","The internal structure of the code is hidden from users, making exploits more difficult to write."],["D","The services are written by a single team and can be debugged more quickly."]],"correct":"A","explanation":"Microservices are small, independently deployable components. Because each service can be built, tested, and released on its own pipeline, a security fix in one area doesn\u2019t require rebuilding and redeploying the whole application. That independence enables rapid, even multiple-per-day patches, shrinking exposure windows when vulnerabilities are found."},{"num":578,"text":"An organization purchases software from an overseas company. The organization\u2019s IDS solution detects that advertising data from the software is unexpectedly reporting back to the overseas company. Which of the following threat vectors does this best describe?","options":[["A","Espionage"],["B","Supply chain"],["C","Nation-state"],["D","Insider threat"]],"correct":"B","explanation":"The compromise came through third-party software the organization obtained and trusted; its unexpected \u201cphone home\u201d behavior is a classic supply chain risk, where embedded code or telemetry from a vendor creates a hidden data exfiltration path."},{"num":579,"text":"Which of the following can be best used to discover a company\u2019s publicly available breach information?","options":[["A","OSINT"],["B","SIEM"],["C","CVE"],["D","CVSS"]],"correct":"A","explanation":"OSINT involves systematically gathering and analyzing publicly available data - news reports, paste sites, breach repositories, darknet mirrors, social media - to see whether details of your company\u2019s breach have been exposed. It\u2019s purpose-built for finding exactly this kind of public breach information."},{"num":580,"text":"An accounting clerk sent money to an attacker\u2019s bank account after receiving fraudulent instructions over the phone to use a new account. Which of the following would most likely prevent this activity in the future?","options":[["A","Standardizing security incident reporting"],["B","Executing regular phishing campaigns"],["C","Implementing insider threat detection measures"],["D","Updating processes for sending wire transfers"]],"correct":"D","explanation":"Stronger, verified procedures (e.g., dual approval, out-of-band callback to a known contact, preapproved account lists) make it impossible for a single clerk to act on a phone request alone. By baking verification steps into the wire-transfer workflow, future fraudulent instructions get stopped at the process gate."},{"num":581,"text":"Which of the following agreements defines response time, escalation points, and performance metrics?","options":[["A","BPA"],["B","MOA"],["C","NDA"],["D","SLA"]],"correct":"D","explanation":"An SLA spells out exactly how fast a provider must respond and resolve issues, what thresholds and KPIs will be measured (uptime, throughput, MTTR), and when/whom to escalate to if those targets aren\u2019t met, making it the formal document for response times, escalation paths, and performance metrics."},{"num":582,"text":"A private equity firm has been the target of protests. The firm discovers its public website has been defaced. Which of the following is most likely the threat actor?","options":[["A","Nation-state"],["B","Unskilled attacker"],["C","Organized crime"],["D","Hacktivist"]],"correct":"D","explanation":"Defacement tied to public protests signals an ideologically motivated actor. Hacktivists target visibility public sites - to broadcast a message or embarrass the organization, rather than to steal money or state secrets."},{"num":583,"text":"Which of the following is the most closely associated with confidentiality?","options":[["A","NDA"],["B","SOW"],["C","MOU"],["D","BPA"]],"correct":"A","explanation":"An NDA legally binds parties to keep specified information secret, directly enforcing the confidentiality pillar of security by prohibiting unauthorized disclosure of protected data."},{"num":584,"text":"During an assessment, an organization provides a penetration tester with a website URL and login credentials. However, the tester does not have access to the source code. Which of the following describes the type of test being performed?","options":[["A","Partially known"],["B","Unknown"],["C","Known"],["D","Obfuscated"]],"correct":"A","explanation":"The tester has some internal knowledge (valid credentials and target URL) but lacks full visibility into the application internals/source code. That limited insight falls squarely into gray/partially known testing, which blends external attacker perspective with select insider information to focus efforts efficiently."},{"num":585,"text":"A security analyst learns that an attack vector, which was used as a part of a recent incident, was a wellknown IoT device exploit. The analyst needs to review logs to identify the time of initial exploit. Which of the following logs should the analyst review first?","options":[["A","Wireless access point"],["B","Switch"],["C","Firewall"],["D","NAC"]],"correct":"C","explanation":"The firewall is the choke point that records every inbound/outbound session to the IoT device; its timestamps on the first suspicious connection will most reliably show when the exploit traffic first hit the network. Reviewing those entries pinpoints the initial compromise time before diving into more granular device or segment logs."},{"num":586,"text":"Which of the following best describes when a user installs an application from an unofficial application store?","options":[["A","Side loading"],["B","Jailbreaking"],["C","Privilege escalation"],["D","Code signing"]],"correct":"A","explanation":"Installing an app from an unofficial/third-party store bypasses the platform\u2019s vetted distribution channel, which is exactly what side loading means: loading software \u201cfrom the side\u201d instead of the official app store. This increases risk because the code may not be reviewed, signed, or scanned to the platform\u2019s security standards."},{"num":587,"text":"A security administrator must use a strategy to protect the company\u2019s data. The security administrator decides to deploy FDE on the end user devices and TLS for all web connections. Which of the following concepts are being used? (Choose two.)","options":[["A","Data segmentation"],["B","Data in transit"],["C","Data sovereignty"],["D","Data in use"],["E","Data at rest"],["F","Data redundancy"]],"correct":"BE","explanation":"TLS - Data in transit: TLS encrypts sessions as information moves across networks, preventing interception or tampering while the data is traveling. FDE - Data at rest: Full-disk encryption protects files stored on the device; if the drive is lost or stolen, the data remains unreadable without the key."},{"num":588,"text":"An administrator investigating an incident is concerned about the downtime of a critical server due to a failed drive. Which of the following would the administrator use to estimate the time needed to fix the issue?","options":[["A","MTTR"],["B","MTBF"],["C","RTO"],["D","RPO"]],"correct":"A","explanation":"MTTR (Mean Time to Repair) measures the average time required to repair a failed component or system and restore it to full functionality, making it the correct metric for estimating downtime due to a failed drive."},{"num":589,"text":"A business manager is concerned about the availability of an application running on hardware in the local data center. Which of the following solutions will improve availability while reducing maintenance overhead?","options":[["A","Deploy load balancing and HA."],["B","Transition from on premises to cloud."],["C","Purchase cybersecurity insurance."],["D","Decommission end-of-life hardware."]],"correct":"B","explanation":"Transitioning from on-premises to a cloud environment improves availability through the provider\u2019s redundant infrastructure and managed services, while reducing maintenance overhead since hardware and many operational tasks are handled by the cloud provider."},{"num":590,"text":"A company wants to ensure that a mission-critical database can only be accessed from specific internal IP addresses. Which of the following should the company deploy to meet this requirement?","options":[["A","Web application firewall"],["B","Network tap"],["C","Intrusion prevention system"],["D","Jump server"]],"correct":"D","explanation":"A jump server acts as a controlled access point that can be restricted to specific internal IP addresses, ensuring that only approved internal sources can connect to the mission-critical database."},{"num":591,"text":"A store is setting up wireless access for their employees. Management wants to limit the number of access points while ensuring all areas of the store are covered. Which of the following tools will help management determine the number of access points needed?","options":[["A","Signal locator"],["B","WPA3"],["C","Heat map"],["D","Site survey"]],"correct":"D","explanation":"A site survey analyzes the physical environment to determine optimal access point placement, ensuring full coverage with the fewest devices needed."},{"num":592,"text":"A security engineer has been assigned to work on a request from outside counsel. The security engineer must provide all email correspondence within a specific date range. Which of the following actions should be taken first in response to the request?","options":[["A","Send litigation hold notifications to identify affected data."],["B","Form a team to determine root cause analysis."],["C","Establish the chain of custody."],["D","Determine the type of preservation needed for evidence."]],"correct":"A","explanation":"Sending litigation hold notifications is the first step to ensure that all relevant email correspondence within the specified date range is preserved and not altered or deleted, maintaining compliance with legal requirements."},{"num":593,"text":"A red-team provider tailgates into an organization's facility. Which of the following has occurred?","options":[["A","Insider threat"],["B","Brute-force attack"],["C","Physical penetration test"],["D","Active reconnaissance"]],"correct":"C","explanation":"Tailgating into a facility during a red-team exercise is a form of physical penetration testing, where security is evaluated by attempting to bypass physical access controls."},{"num":594,"text":"Which of the following describes an agent-based application that detects and blocks malicious behavior on enterprise systems while disconnected from the corporate network?","options":[["A","Endpoint protection"],["B","System patching"],["C","HIDS"],["D","NGFW"]],"correct":"A","explanation":"Endpoint protection is an agent-based solution installed on devices that can detect and block malicious activity locally, allowing it to function even when the system is disconnected from the corporate network."},{"num":595,"text":"A manager meets with various stakeholders involved with a recently resolved security incident. During the meeting, they discuss potential improvements to the environment in order to better respond to future incidents. Which of the following incident response activities does this describe?","options":[["A","Recovery"],["B","Analysis"],["C","Lessons learned"],["D","Containment"]],"correct":"C","explanation":"The lessons learned phase occurs after an incident is resolved and involves reviewing the response process, identifying improvements, and implementing changes to enhance future incident handling."},{"num":596,"text":"A database engineer needs sample customer data for testing purposes. Which of the following techniques can be used to remove sensitive information from database records while still providing sufficient data to perform testing?","options":[["A","Obfuscation"],["B","RBAC"],["C","Tokenization"],["D","Filtering"]],"correct":"A","explanation":"Obfuscation masks or scrambles sensitive data elements, allowing realistic but anonymized records to be used for testing without exposing actual customer information."},{"num":597,"text":"Which of the following encryption methods protects data if a user loses their laptop?","options":[["A","Volume"],["B","Full disk"],["C","Partition"],["D","File"]],"correct":"B","explanation":"Full disk encryption secures all data on a laptop\u2019s storage, ensuring it remains protected and inaccessible if the device is lost or stolen."},{"num":598,"text":"A security analyst regularly receives emails from users who are concerned that attached files may be malicious. Which of the following should the analyst use to evaluate the suspicious files and report back as to whether or not files are a threat?","options":[["A","Sanitization"],["B","Sandbox"],["C","Static analysis"],["D","Enumeration"]],"correct":"B","explanation":"A sandbox safely executes and observes the behavior of suspicious files in an isolated environment, allowing the analyst to determine if they are malicious without risking the production network."},{"num":599,"text":"Which of the following would be used to detect an employee who is emailing a customer list to a personal account before leaving the company?","options":[["A","DLP"],["B","FIM"],["C","IDS"],["D","EDR"]],"correct":"A","explanation":"Data Loss Prevention (DLP) monitors and controls the movement of sensitive data, enabling detection of attempts to send protected information, such as a customer list, to unauthorized destinations."},{"num":600,"text":"A CIRT team updates their playbooks to include instructions to respond to a ransomware attack. To prepare for a real event, the team performs a simulation and assesses their performance afterward. Which of the following activities does this describe?","options":[["A","Lessons learned"],["B","Root cause analysis"],["C","Disaster recovery planning"],["D","Tabletop exercise"]],"correct":"D","explanation":"A tabletop exercise is a simulated scenario where team members discuss and walk through their planned response to an incident, such as a ransomware attack, and then assess performance to identify improvements."},{"num":601,"text":"Which of the following can automate vulnerability management?","options":[["A","CVE"],["B","SCAP"],["C","OSINT"],["D","CVSS"]],"correct":"B","explanation":"SCAP (Security Content Automation Protocol) is a standardized framework that enables automated vulnerability management, compliance checking, and security measurement."},{"num":602,"text":"Which of the following is a reason to perform a one-time risk assessment?","options":[["A","Quantifying an annual loss expectancy"],["B","Updating the risk register periodically"],["C","Complying with a regulation"],["D","Decommissioning an application"]],"correct":"D","explanation":"A one-time risk assessment is performed for unique events such as decommissioning an application, to evaluate potential security or compliance impacts before the system is retired."},{"num":603,"text":"An employee from the accounting department logs in to the website used for processing the company's payments. After logging in, a new desktop application automatically downloads on the employee's computer and causes the computer to restart. Which of the following attacks has occurred?","options":[["A","XSS"],["B","Watering hole"],["C","Typosquatting"],["D","Buffer overflow"]],"correct":"B","explanation":"A watering hole attack compromises a legitimate website frequently visited by the target, embedding malicious code that delivers malware, such as the unauthorized desktop application downloaded after the employee logged in."},{"num":604,"text":"An EDR solution recognizes that a specific workstation has outbound traffic to a malicious IP. Which of the following would be the best action to take to contain the threat?","options":[["A","Change the passwords for all users accessing that workstation."],["B","Isolate the workstation as part of immediate response."],["C","Patch the workstation because it is likely vulnerable."],["D","Review the hardening and policies affecting that workstation."]],"correct":"B","explanation":"Isolating the workstation immediately stops communication with the malicious IP and prevents further spread or data exfiltration, making it the most effective containment action."},{"num":605,"text":"Which of the following would most likely prevent exploitation of an end-of-life, business-critical system?","options":[["A","Monitoring"],["B","Isolation"],["C","Decommissioning"],["D","Encryption"]],"correct":"B","explanation":"Isolation places the end-of-life system on a segmented network or removes its external connectivity, reducing exposure and preventing attackers from exploiting its vulnerabilities while it remains in use."},{"num":606,"text":"Which of the following is the most likely motivation for a hacktivist?","options":[["A","Financial gain"],["B","Service disruption"],["C","Philosophical beliefs"],["D","Corporate espionage"]],"correct":"C","explanation":"Hacktivists are motivated by philosophical or political beliefs, using hacking to promote their cause or draw attention to specific social or ideological issues."},{"num":607,"text":"Which of the following is the best physical security control to prevent damage from a vehicle?","options":[["A","Security guard"],["B","Fencing"],["C","Lighting"],["D","Bollards"]],"correct":"D","explanation":"Bollards serve as a robust physical barrier designed to withstand and absorb the kinetic impact of a vehicle, thereby preventing unauthorized vehicular access or accidental collisions that could cause structural damage or endanger personnel."},{"num":608,"text":"A security team wants to work with the same organization's development team to ensure WAF policies are automatically created when applications are deployed. Which of the following concepts describes this capability?","options":[["A","IaC"],["B","IoT"],["C","IoC"],["D","IaaS"]],"correct":"A","explanation":"Infrastructure as Code (IaC) allows security configurations, such as WAF policies, to be automatically provisioned and managed as part of the application deployment process, ensuring consistency and reducing manual effort."},{"num":609,"text":"Which of the following uses proprietary controls and is designed to function in harsh environments over many years with limited remote access management?","options":[["A","ICS"],["B","Microservers"],["C","Containers"],["D","IoT"]],"correct":"A","explanation":"Industrial Control Systems (ICS) use proprietary controls and are built to operate reliably in harsh environments for extended periods, often with limited remote access and management capabilities."},{"num":610,"text":"Which of the following data recovery strategies will result in a quick recovery at low cost?","options":[["A","Hot"],["B","Cold"],["C","Manual"],["D","Warm"]],"correct":"B","explanation":"A cold site is the least expensive recovery option, providing space and infrastructure but no active systems, allowing for recovery at a lower cost\u2014though with slower setup compared to hot or warm sites."},{"num":611,"text":"An MSSP manages firewalls for hundreds of clients. Which of the following tools would be most helpful to create a standard configuration template in order to improve the efficiency of firewall changes?","options":[["A","SNMP"],["B","Benchmarks"],["C","Netflow"],["D","SCAP"]],"correct":"B","explanation":"Benchmarks provide standardized configuration guidelines, such as those from CIS, enabling the MSSP to create consistent firewall configuration templates and apply changes efficiently across multiple clients."},{"num":612,"text":"After multiple phishing simulations, the Chief Security Officer announces a new program that incentivizes employees to not click phishing links in the upcoming quarter. Which of the following security awareness execution techniques does this represent?","options":[["A","Computer-based training"],["B","Insider threat awareness"],["C","SOAR playbook"],["D","Gamification"]],"correct":"D","explanation":"Gamification uses rewards, competition, or incentives to motivate and reinforce desired behaviors - in this case, encouraging employees to avoid clicking phishing links through a reward-based program."},{"num":613,"text":"A security analyst sees an increase of vulnerabilities on workstations after a deployment of a company group policy. Which of the following vulnerability types will the analyst most likely find on the workstations?","options":[["A","Misconfiguration"],["B","Zero-day"],["C","Malicious update"],["D","Supply chain"]],"correct":"A","explanation":"A misconfiguration vulnerability occurs when system settings - such as those deployed via group policy are set insecurely, unintentionally weakening security and increasing exposure to threats."},{"num":614,"text":"Which of the following threat actors would most likely target an organization by using a logic bomb within an internally-developed application?","options":[["A","Nation-state"],["B","Trusted insider"],["C","Organized crime group"],["D","Hacktivist"]],"correct":"B","explanation":"A trusted insider, such as a disgruntled employee or contractor with authorized access to internal systems, is most likely to plant a logic bomb in an internally-developed application since they have both the access and knowledge needed to insert the malicious code."},{"num":615,"text":"Which of the following is a company addressing when it rolls out MDM on all COPE devices?","options":[["A","Malware outbreaks"],["B","Phishing attacks"],["C","Unsupported applications"],["D","Data masking"]],"correct":"C","explanation":"Mobile Device Management (MDM) on Corporate-Owned, Personally Enabled (COPE) devices enforces application control policies, helping prevent the installation and use of unsupported or unauthorized applications."},{"num":616,"text":"An organization failed to account for the right-to-be-forgotten regulations. Which of the following impacts might this action have on the company?","options":[["A","Fines"],["B","Data breaches"],["C","Revenue loss"],["D","Blackmail"]],"correct":"A","explanation":"Failing to comply with right-to-be-forgotten regulations, such as GDPR requirements, can lead to legal penalties and fines from regulatory authorities."},{"num":617,"text":"A company is experiencing issues with employees leaving the company for a competitor and taking customer contact information with them. Which of the following tools will help prevent this from reoccurring?","options":[["A","FIM"],["B","NAC"],["C","IDS"],["D","UBA"]],"correct":"D","explanation":"User Behavior Analytics (UBA) detects unusual or risky user activities, such as exfiltrating customer contact data, helping to identify and prevent insider threats before employees leave for a competitor."},{"num":618,"text":"A company that operates with most of its infrastructure in the cloud had its development environment breached. The attackers gained access via a public-facing development application and were able to pivot to the production environment. Which of the following architecture changes would best prevent this from occurring again?","options":[["A","Moving each environment to a separate VPC in the company cloud account"],["B","Deploying firewalls in the company cloud account"],["C","Migrating the development environment to an on-premises environment"],["D","Implementing security groups restricting access between environments"]],"correct":"A","explanation":"Placing development and production environments in separate VPCs provides strong network isolation, preventing attackers from pivoting between them even if one environment is compromised."},{"num":619,"text":"Which of the following security concepts is being followed when applying encryption to sensitive data?","options":[["A","Confidentiality"],["B","Non-repudiation"],["C","Availability"],["D","Integrity"]],"correct":"A","explanation":"Encryption ensures confidentiality by protecting sensitive data from unauthorized access, allowing only authorized parties with the correct decryption key to read it."},{"num":620,"text":"Which of the following cryptographic solutions would allow an organization to recover encrypted data after a key becomes corrupted or is deleted?","options":[["A","Self-signed certificates"],["B","Escrow"],["C","Tokenization"],["D","Trusted Platform Module"]],"correct":"B","explanation":"Key escrow securely stores encryption keys with a trusted third party or internal authority, enabling recovery of encrypted data if the original key is lost or corrupted."},{"num":621,"text":"An organization is evaluating the cost of licensing a new solution to prevent ransomware. Which of the following is the most helpful in making this decision?","options":[["A","ALE"],["B","SLE"],["C","RTO"],["D","ARO"]],"correct":"A","explanation":"Annual Loss Expectancy (ALE) estimates the yearly financial impact of a risk, helping the organization compare the potential cost of ransomware incidents against the cost of licensing the prevention solution."},{"num":622,"text":"Which of the following should be used to ensure that a device is inaccessible to a network-connected resource?","options":[["A","Disablement of unused services"],["B","Web application firewall"],["C","Host isolation"],["D","Network-based IDS"]],"correct":"C","explanation":"Host isolation removes a device from communicating with network-connected resources, ensuring it cannot access or affect other systems while remaining powered on for investigation or remediation."},{"num":623,"text":"During the investigation of a webmail log-in using compromised credentials, a security analyst needs to review information about the source IP for the log-in. Which of the following logs should the analyst retrieve?","options":[["A","Network"],["B","Application"],["C","System"],["D","Firewall"]],"correct":"B","explanation":"Application logs for the webmail service contain details about authentication events, including the source IP address used during the compromised log-in."},{"num":624,"text":"Which of the following should be used to select a label for a file based on the file\u2019s value, sensitivity, or applicable regulations?","options":[["A","Verification"],["B","Certification"],["C","Classification"],["D","Inventory"]],"correct":"C","explanation":"Classification assigns labels to files based on their sensitivity, value, and regulatory requirements, guiding how the data should be handled and protected."},{"num":625,"text":"A company makes a change during the appropriate change window, but the unsuccessful change extends beyond the scheduled time and impacts customers. Which of the following would prevent this from reoccurring?","options":[["A","User notification"],["B","Change approval"],["C","Risk analysis"],["D","Backout plan"]],"correct":"D","explanation":"A backout plan provides predefined steps to revert a change if it fails or causes issues, minimizing downtime and preventing extended customer impact."},{"num":626,"text":"A security analyst is collecting evidence in response to an incident. Which of the following must the analyst maintain in order to ensure the admissibility of the evidence in a court case?","options":[["A","Chain of custody"],["B","Legal hold"],["C","E-discovery"],["D","Tabletop exercise"]],"correct":"A","explanation":"Chain of custody is the documented process of handling and tracking evidence from collection to presentation in court, ensuring its integrity and admissibility."},{"num":627,"text":"Which of the following types of vulnerabilities involves attacking a system to access adjacent hosts?","options":[["A","VM escape"],["B","Side loading"],["C","Remote code execution"],["D","Resource exhaustion"]],"correct":"A","explanation":"VM escape exploits a vulnerability in the virtualization layer, allowing an attacker to break out of a virtual machine and gain access to the host system or adjacent virtual machines."},{"num":628,"text":"While reviewing a recent compromise, a forensics team discovers that there are hard-coded credentials in the database connection strings. Which of the following assessment types should be performed during software development to prevent this from reoccurring?","options":[["A","Vulnerability scan"],["B","Penetration test"],["C","Static analysis"],["D","Quality assurance"]],"correct":"C","explanation":"Static analysis examines source code without executing it, enabling the detection of security flaws such as hard-coded credentials early in the software development process."},{"num":629,"text":"Which of the following should be deployed on an externally facing web server in order to establish an encrypted connection?","options":[["A","Public key"],["B","Private key"],["C","Asymmetric key"],["D","Symmetric key"]],"correct":"A","explanation":"A public key is deployed on the web server within its digital certificate, allowing clients to establish an encrypted session by securely exchanging a symmetric key through asymmetric encryption."},{"num":630,"text":"A security administrator receives multiple reports about the same suspicious email. Which of the following is the most likely reason for the malicious email\u2019s continued delivery?","options":[["A","Employees are flagging legitimate emails as spam."],["B","Information from reported emails is not being used to tune email filtering tools."],["C","Employees are using shadow IT solutions for email."],["D","Employees are forwarding personal emails to company email addresses."]],"correct":"B","explanation":"If reported email data is not used to update and tune filtering tools, the malicious email can continue bypassing defenses and reaching other users\u2019 inboxes."},{"num":631,"text":"While browsing a web page, a user receives a pop-up with a link telling them to navigate to another site. To which of the following is the site vulnerable?","options":[["A","DoS"],["B","XSS"],["C","SQLi"],["D","TOC"]],"correct":"B","explanation":"Cross-Site Scripting (XSS) allows attackers to inject malicious scripts into a web page, which can display pop-ups or redirect users to other sites without their consent."},{"num":632,"text":"An administrator must secure several end-of-life SCADA devices in a manufacturing facility on a limited budget. Which of the following should the security administrator do to best secure these devices?","options":[["A","Segment the SCADA devices to their own subnet"],["B","Add the SCADA devices to a network monitoring tool"],["C","Apply security patches to the SCADA devices"],["D","Block internet access to the SCADA devices"]],"correct":"A","explanation":"Network segmentation isolates end-of-life SCADA devices from other systems, reducing the attack surface and limiting lateral movement, which is critical when patching or direct security updates are not possible."},{"num":633,"text":"A business is expanding to a new country and must protect customers from accidental disclosure of specific national identity information. Which of the following should the security engineer update to best meet business requirements?","options":[["A","SIEM"],["B","SCAP"],["C","DLP"],["D","WAF"]],"correct":"C","explanation":"Data Loss Prevention (DLP) can be configured to detect and prevent the unauthorized transmission of specific national identity information, ensuring compliance with privacy regulations in the new country."},{"num":634,"text":"Which of the following techniques would identify whether data has been modified in transit?","options":[["A","Hashing"],["B","Tokenization"],["C","Masking"],["D","Encryption"]],"correct":"A","explanation":"Hashing creates a unique fixed-length value based on the data, allowing verification of integrity by comparing the hash before and after transit to detect any modifications."},{"num":635,"text":"Which of the following strategies most effectively protects sensitive data at rest in a database?","options":[["A","Hashing"],["B","Masking"],["C","Tokenization"],["D","Obfuscation"]],"correct":"C","explanation":"Tokenization replaces sensitive data with non-sensitive, unique tokens while storing the actual data securely in a separate location, effectively protecting data at rest in a database."},{"num":636,"text":"Which of the following would an organization most likely use to minimize the loss of data on a file server in the event that data needs to be restored due to loss of the primary server?","options":[["A","Monitoring"],["B","Journaling"],["C","Obfuscation"],["D","Tokenization"]],"correct":"B","explanation":"Journaling records changes to files in real time, enabling quick restoration of the most recent data in case of primary server failure, thereby minimizing potential data loss."},{"num":637,"text":"Which of the following would help reduce the impact of a zero-day vulnerability in NAS installed on a large office network?","options":[["A","Encryption"],["B","Patching"],["C","Segmentation"],["D","Filtering"]],"correct":"C","explanation":"Segmentation isolates the NAS from the broader network, limiting an attacker\u2019s ability to exploit the zeroday vulnerability and reducing the potential impact on other systems."},{"num":638,"text":"Which of the following should a security analyst use to prioritize the remediation of a vulnerability?","options":[["A","OSINT"],["B","CVE"],["C","IoC"],["D","CVSS"]],"correct":"D","explanation":"The Common Vulnerability Scoring System (CVSS) provides a standardized severity score for vulnerabilities, enabling analysts to prioritize remediation efforts based on risk impact."},{"num":639,"text":"An IT team rolls out a new management application that uses a randomly generated MFA token that is sent to the administrator's phone. Despite this new MFA precaution, there is a security breach of the same software. Which of the following describes this kind of attack?","options":[["A","Smishing"],["B","Typosquatting"],["C","Espionage"],["D","Pretexting"]],"correct":"A","explanation":"Smishing uses fraudulent SMS messages to trick victims into revealing sensitive information or clicking malicious links, potentially compromising MFA tokens sent to a phone."},{"num":640,"text":"A security analyst reviews the following SIEM events: Which of the following best describes the observed behavior?","options":[["A","Brute-force attack"],["B","Privilege escalation"],["C","Cross-site scripting"],["D","Password sharing"]],"correct":"D","explanation":"The successful logins from multiple distant geographic locations within minutes indicate that the same credentials are being used by different individuals or systems, which is consistent with password sharing.","image":"q640.jpg"},{"num":641,"text":"A company hired a security consultant to suggest a device that will protect its inbound HTTP traffic by immediately blocking security violations. Which of the following should the consultant most likely suggest?","options":[["A","IPS"],["B","IDS"],["C","Proxy"],["D","WAF"]],"correct":"D","explanation":"A Web Application Firewall (WAF) protects inbound HTTP traffic by monitoring, filtering, and immediately blocking malicious requests targeting web applications."},{"num":642,"text":"A security manager needs an automated solution that will take immediate action to protect an organization against inbound malicious traffic. Which of the following is the best solution?","options":[["A","UEM"],["B","IPS"],["C","WAF"],["D","VPN"]],"correct":"B","explanation":"An Intrusion Prevention System (IPS) automatically detects and blocks malicious network traffic in real time, providing immediate protection against inbound threats."},{"num":643,"text":"A Chief Security Officer wants to change user authentication to the company wireless network. The authentication must use the LDAP database and must be centrally managed. Which of the following would help fulfill this requirement?","options":[["A","SAML"],["B","TACACS+"],["C","OAUTH"],["D","RADIUS"]],"correct":"D","explanation":"RADIUS provides centralized authentication, authorization, and accounting, and it can integrate with an LDAP database to authenticate users connecting to the company\u2019s wireless network."},{"num":644,"text":"An administrator is creating domain profiles for each employee within the company. The administrator wants to make the process more efficient by assigning permissions based on user roles and departments. Which of the following would most likely fulfill those requirements?","options":[["A","Resource provisioning"],["B","User provisioning"],["C","Security groups"],["D","Enforcing baselines"]],"correct":"C","explanation":"Security groups allow administrators to assign permissions collectively based on user roles or departments, streamlining domain profile management and reducing repetitive configuration tasks."},{"num":645,"text":"A systems administrator needs to update systems without disrupting operations. Which of the following should the systems administrator and company leadership agree on?","options":[["A","Maintenance window"],["B","Backout plan"],["C","Standard operating procedure"],["D","Impact analysis"]],"correct":"A","explanation":"A maintenance window is a scheduled period agreed upon in advance during which updates or changes can be made without disrupting normal business operations."},{"num":646,"text":"A company wants to improve the security of the local network by authenticating and encrypting all of the internal traffic between corporate sites. Which of the following should the company deploy to achieve this goal?","options":[["A","\u0415\u0410\u0420"],["B","IPSec"],["C","SD-WAN"],["D","WAF"]],"correct":"B","explanation":"IPsec authenticates and encrypts IP traffic, providing secure communication between corporate sites over the local or wide area network."},{"num":647,"text":"A security analyst identifies an incident in the network. Which of the following incident response activities would the security analyst perform next?","options":[["A","Containment"],["B","Detection"],["C","Eradication"],["D","Recovery"]],"correct":"A","explanation":"After identifying (detecting) an incident, the next step is containment, which aims to limit the spread and impact of the threat before proceeding to eradication or recovery."},{"num":648,"text":"An administrator discovers a cross-site scripting vulnerability on a company website. Which of the following will most likely remediate the issue?","options":[["A","Input validation"],["B","NGFW"],["C","Vulnerability scan"],["D","WAF"]],"correct":"A","explanation":"Input validation ensures that user-supplied data is properly sanitized before processing or displaying, effectively preventing cross-site scripting attacks."},{"num":649,"text":"A service provider wants a cost-effective way to rapidly expand from providing internet links to managing them. Which of the following methods will allow the service provider to best scale its services while maintaining performance consistency?","options":[["A","Escalation support"],["B","Increased workforce"],["C","Baseline enforcement"],["D","Technical debt"]],"correct":"C","explanation":"Baseline enforcement ensures consistent performance and security standards across managed services, allowing the provider to scale operations cost-effectively without sacrificing quality."},{"num":650,"text":"Which of the following control types describes an alert from a SIEM tool?","options":[["A","Preventive"],["B","Corrective"],["C","Compensating"],["D","Detective"]],"correct":"D","explanation":"A SIEM alert is a detective control because it identifies and reports suspicious or malicious activity after it occurs, enabling further investigation and response."},{"num":651,"text":"Which of the following attacks primarily targets insecure networks?","options":[["A","Evil twin"],["B","Impersonation"],["C","Watering hole"],["D","Pretexting"]],"correct":"A","explanation":"An evil twin attack sets up a rogue wireless access point that mimics a legitimate one, targeting insecure or poorly secured networks to capture user data."},{"num":652,"text":"A penetration testing report indicated that an organization should implement controls related to database input validation. Which of the following best identifies the type of vulnerability that was likely discovered during the test?","options":[["A","XSS"],["B","Command injection"],["C","Buffer overflow"],["D","SQLi"]],"correct":"D","explanation":"SQL injection (SQLi) exploits improper or missing input validation in database queries, allowing attackers to manipulate SQL commands and access or modify database content."},{"num":653,"text":"Which of the following activities would involve members of the incident response team and other stakeholders simulating an event?","options":[["A","Lessons learned"],["B","Digital forensics"],["C","Tabletop exercise"],["D","Root cause analysis"]],"correct":"C","explanation":"A tabletop exercise is a simulated event in which the incident response team and other stakeholders walk through their roles and decision-making processes to evaluate readiness and improve response plans."},{"num":654,"text":"Which of the following data classifications best applies when data is intended for internal organizational use or with commercial partners?","options":[["A","Public"],["B","Restricted"],["C","Confidential"],["D","Sensitive"]],"correct":"C","explanation":"Confidential data is intended for internal organizational use or for sharing with trusted commercial partners, requiring protection from unauthorized disclosure."},{"num":655,"text":"Which of the following technologies can achieve microsegmentation?","options":[["A","Next-generation firewalls"],["B","Software-defined networking"],["C","Embedded systems"],["D","Air-gapped"]],"correct":"B","explanation":"Software-defined networking (SDN) enables microsegmentation by allowing fine-grained, software-based control over network traffic flows, isolating workloads and minimizing attack surfaces."},{"num":656,"text":"Which of the following metrics impacts the backup schedule as part of the BIA?","options":[["A","RTO"],["B","RPO"],["C","MTTR"],["D","MTBF"]],"correct":"B","explanation":"The Recovery Point Objective (RPO) defines the maximum acceptable amount of data loss in terms of time, directly influencing how frequently backups must be performed."},{"num":657,"text":"A customer reports that software the customer downloaded from a public website has malware in it. However, the company that created the software denies any malware in its software at delivery time. Which of the following techniques will address this concern?","options":[["A","Secure storage"],["B","Static code analysis"],["C","Input validation"],["D","Code signing"]],"correct":"D","explanation":"Code signing uses digital certificates to verify the authenticity and integrity of software, ensuring it has not been tampered with after being created and delivered by the vendor."},{"num":658,"text":"After completing an annual external penetration test, a company receives the following guidance: Decommission two unused web servers currently exposed to the internet. Close 18 open and unused ports found on their existing production web servers. Remove company email addresses and contact info from public domain registration records. Which of the following security practices best describes these recommendations?","options":[["A","Attack surface reduction"],["B","Vulnerability assessment"],["C","Tabletop exercise"],["D","Business impact analysis"]],"correct":"A","explanation":"Attack surface reduction involves minimizing the number of exploitable points, such as unused servers, open ports, and publicly exposed contact information, that attackers could target."},{"num":659,"text":"Which of the following receives logs from various devices and services, and then presents alerts?","options":[["A","SIEM"],["B","SCADA"],["C","SNMP"],["D","SCAP"]],"correct":"A","explanation":"A SIEM (Security Information and Event Management) system collects logs from multiple sources, correlates the data, and generates alerts for suspicious or malicious activity."},{"num":660,"text":"A security analyst investigates logs and notices similar data types are being sent to IP addresses with a bad reputation. Which of the following attack types does this best describe?","options":[["A","Logic bomb"],["B","Worm"],["C","Spyware"],["D","Keylogger"]],"correct":"C","explanation":"Spyware covertly collects and transmits data to external servers, often to IP addresses with known bad reputations, matching the described behavior in the logs."},{"num":661,"text":"Which of the following describes a situation where a user is authorized before being authenticated?","options":[["A","Privilege escalation"],["B","Race condition"],["C","Tailgating"],["D","Impersonation"]],"correct":"A","explanation":"Privilege escalation can occur if authorization is granted without proper authentication, allowing a user to gain higher-level access than intended."},{"num":662,"text":"An employee decides to take malicious action against an organization after being passed over for a promotion. Which of the following threats does the employee now represent?","options":[["A","Insider threat"],["B","Nation-state"],["C","Shadow IT"],["D","Hacktivist"]],"correct":"A","explanation":"An insider threat involves a person within the organization, such as an employee, who uses their access for malicious purposes, often due to personal grievances or dissatisfaction."},{"num":663,"text":"At the start of a penetration test, the tester checks OSINT resources for information about the client environment. Which of the following types of reconnaissance is the tester performing?","options":[["A","Active"],["B","Passive"],["C","Offensive"],["D","Defensive"]],"correct":"B","explanation":"Passive reconnaissance involves gathering information from publicly available sources, such as OSINT resources, without directly interacting with the target environment."},{"num":664,"text":"An administrator is estimating the cost associated with an attack that could result in the replacement of a physical server. Which of the following processes is the administrator performing?","options":[["A","Quantitative risk analysis"],["B","Disaster recovery test"],["C","Physical security controls"],["D","Threat modeling"]],"correct":"A","explanation":"Quantitative risk analysis assigns a monetary value to potential losses, such as the cost of replacing a physical server after an attack."},{"num":665,"text":"A user's system became infected when malware was downloaded and extracted. The malware is now active in the computer's volatile storage. Which of the following best describes the technique leveraged by the malware?","options":[["A","Race condition"],["B","Zero-day exploit"],["C","Buffer overflow"],["D","Memory injection"]],"correct":"D","explanation":"Memory injection refers to a technique where malware is loaded directly into the system\u2019s volatile memory (RAM) to execute malicious code without writing files to disk, making detection and persistence more difficult. This matches the scenario where the malware is now active in the computer's volatile storage."},{"num":666,"text":"An attacker gained access to a virtual machine and was able to access the hypervisor. Which of the following describes this attack?","options":[["A","VM escape"],["B","SQL injection"],["C","Privilege escalation"],["D","Logic bomb"]],"correct":"A","explanation":"VM escape is an attack in which a malicious actor breaks out of the confines of a virtual machine to gain access to the underlying hypervisor or other virtual machines, matching the scenario described."},{"num":667,"text":"An administrator learns that users are receiving large quantities of unsolicited messages. The administrator checks the content filter and sees hundreds of messages sent to multiple users. Which of the following best describes this kind of attack?","options":[["A","Watering hole"],["B","Typosquatting"],["C","Business email compromise"],["D","Phishing"]],"correct":"D","explanation":"Phishing involves sending large quantities of unsolicited messages to users in an attempt to trick them into revealing sensitive information or performing malicious actions. This aligns with users receiving many unsolicited emails."},{"num":668,"text":"Which of the following can assist in recovering data if the decryption key is lost?","options":[["A","CSR"],["B","Salting"],["C","Root of trust"],["D","Escrow"]],"correct":"D","explanation":"Escrow refers to a trusted third party securely holding a copy of the decryption key, allowing recovery of encrypted data if the original key is lost."},{"num":669,"text":"A company's antivirus solution is effective in blocking malware but often has false positives. The security team has spent a significant amount of time on investigations but cannot determine a root cause. The company is looking for a heuristic solution. Which of the following should replace the antivirus solution?","options":[["A","SIEM"],["B","EDR"],["C","DLP"],["D","IDS"]],"correct":"B","explanation":"EDR (Endpoint Detection and Response) uses advanced heuristic and behavioral analysis to detect, investigate, and respond to threats, reducing false positives and providing deeper insight than traditional antivirus."},{"num":670,"text":"Attackers created a new domain name that looks similar to a popular file-sharing website. Which of the following threat vectors is being used?","options":[["A","Watering-hole attack"],["B","Brand impersonation"],["C","Phishing"],["D","Typosquatting"]],"correct":"D","explanation":"Typosquatting involves registering domain names that are visually or typographically similar to legitimate sites to trick users into visiting the malicious site, matching the scenario described."},{"num":671,"text":"Which of the following teams combines both offensive and defensive testing techniques to protect an organization's critical systems?","options":[["A","Red"],["B","Blue"],["C","Purple"],["D","Yellow"]],"correct":"C","explanation":"A Purple team combines both offensive (Red team) and defensive (Blue team) security techniques to improve an organization\u2019s overall security posture through collaborative testing and defense."},{"num":672,"text":"Which of the following best describes the practice of researching laws and regulations related to information security operations within a specific industry?","options":[["A","Compliance reporting"],["B","GDPR"],["C","Due diligence"],["D","Attestation"]],"correct":"C","explanation":"Due diligence is the practice of researching and understanding relevant laws and regulations to ensure that information security operations comply with legal and regulatory requirements for a specific industry."},{"num":673,"text":"Which of the following should a technician perform to verify the integrity of a file transferred from one device to another?","options":[["A","Authentication"],["B","Obfuscation"],["C","Hashing"],["D","Encryption"]],"correct":"C","explanation":"Hashing generates a unique value for file contents, allowing technicians to verify file integrity by comparing hashes before and after transfer to ensure the file was not altered."},{"num":674,"text":"During an investigation, a security analyst discovers traffic going out to a command-and-control server. The analyst must find out if any data exfiltration has occurred. Which of the following would best help the analyst determine this?","options":[["A","Application log"],["B","Metadata"],["C","Network log"],["D","Packet capture"]],"correct":"D","explanation":"Packet capture provides a detailed record of network traffic, allowing analysts to inspect the actual contents of communications to determine if sensitive data was exfiltrated to a command-and-control server."},{"num":675,"text":"A security analyst is investigating an alert that was produced by endpoint protection software. The analyst determines this event was a false positive triggered by an employee who attempted to download a file. Which of the following is the most likely reason the download was blocked?","options":[["A","A misconfiguration in the endpoint protection software"],["B","A zero-day vulnerability in the file"],["C","A supply chain attack on the endpoint protection vendor"],["D","Incorrect file permissions"]],"correct":"A","explanation":"A misconfiguration in the endpoint protection software can lead to false positives, causing legitimate files to be incorrectly flagged and blocked during download."},{"num":676,"text":"A company discovers that an employee was paid by a competitor to save internal business files to a thumb drive and deliver it to the competitor. Which of the following is most likely the employee's motivation?","options":[["A","Revenge"],["B","Financial gain"],["C","Blackmail"],["D","Data exfiltration"]],"correct":"B","explanation":"The employee was compensated by a competitor, making financial gain the most likely motivation for stealing and delivering internal business files."},{"num":677,"text":"Which of the following outlines the configuration, maintenance, and security roles between a cloud service provider and the customer?","options":[["A","Service-level agreement"],["B","Responsibility matrix"],["C","Memorandum of understanding"],["D","Non-disclosure agreement"]],"correct":"B","explanation":"A responsibility matrix clearly defines and outlines the division of configuration, maintenance, and security roles between a cloud service provider and the customer."},{"num":678,"text":"An attacker used XSS to compromise a web server. Which of the following solutions could have been used to prevent this attack?","options":[["A","NGFW"],["B","UTM"],["C","WAF"],["D","NAC"]],"correct":"C","explanation":"A WAF (Web Application Firewall) can detect and block malicious web traffic, including cross-site scripting (XSS) attacks, thereby preventing such vulnerabilities from being exploited."},{"num":680,"text":"Which of the following non-production sites is an operational mirror of the primary data center and is ready for use if the primary data center experiences an outage?","options":[["A","Hot"],["B","Warm"],["C","Cold"],["D","Frozen"]],"correct":"A","explanation":"A hot site is a fully operational mirror of the primary data center, maintained in real time and ready to take over operations immediately if the primary site experiences an outage."},{"num":681,"text":"Which of the following will harden access to a new database system? (Choose two.)","options":[["A","Jump server"],["B","NIDS"],["C","Monitoring"],["D","Proxy server"],["E","Host-based firewall"],["F","WAF"]],"correct":"AE","explanation":"A jump server restricts and controls administrative access to the database system, reducing the attack surface. A host-based firewall limits network connections directly to the database server, preventing unauthorized access and hardening the system."},{"num":682,"text":"A few weeks after deploying additional email servers, a company begins to receive complaints from employees that messages they send are going into their recipients' spam folders. Which of the following needs to be updated in order to resolve this issue?","options":[["A","CNAME"],["B","SMTP"],["C","DLP"],["D","SPF"]],"correct":"D","explanation":"An SPF (Sender Policy Framework) record needs to be updated to include the new email servers, allowing recipient systems to verify the legitimacy of the sending servers and prevent outgoing emails from being marked as spam."},{"num":683,"text":"A company uses a cloud-based platform for file storage and wants to ensure the security of its data in transit. Which of the following should the company verify are in place to secure this type of communication? (Choose two.)","options":[["A","TLS certificates"],["B","WPA2 encryption"],["C","HTTPS"],["D","Virtual private network"],["E","Encryption key management"],["F","Digital signatures"]],"correct":"AC","explanation":"TLS certificates enable secure, encrypted connections, while HTTPS ensures data in transit to and from the cloud storage is encrypted, protecting it from interception."}];
export default QUESTIONS;
